import SwiftUI

enum OpenClawActivityType {
    static var eyebrow: Font {
        body(size: 8).weight(.bold)
    }

    static var subheadSemiBold: Font {
        display(size: 15, weight: .semibold)
    }

    static var subheadBold: Font {
        display(size: 15, weight: .bold)
    }

    static var caption: Font {
        body(size: 12)
    }

    static func symbol(size: CGFloat, weight: Font.Weight) -> Font {
        .system(size: size, weight: weight)
    }

    private static func display(size: CGFloat, weight: Font.Weight) -> Font {
        .custom("RedHatDisplay-Regular", size: size, relativeTo: .subheadline).weight(weight)
    }

    private static func body(size: CGFloat) -> Font {
        .custom("Inter-Regular", size: size, relativeTo: .caption)
    }
}

import SwiftUI
import WidgetKit

@main
struct OpenClawActivityWidgetBundle: WidgetBundle {
    var body: some Widget {
        OpenClawLiveActivity()
    }
}

import ActivityKit
import Foundation
import SwiftUI
import WidgetKit

struct OpenClawLiveActivity: Widget {
    var body: some WidgetConfiguration {
        ActivityConfiguration(for: OpenClawActivityAttributes.self) { context in
            self.lockScreenView(context: context, state: self.displayState(context: context))
        } dynamicIsland: { context in
            let state = self.displayState(context: context)
            return DynamicIsland {
                DynamicIslandExpandedRegion(.leading) {
                    self.agentAvatar(context: context, state: state)
                }
                DynamicIslandExpandedRegion(.center) {
                    VStack(alignment: .leading, spacing: 1) {
                        Text("OPENCLAW")
                            .font(OpenClawActivityType.eyebrow)
                            .foregroundStyle(OpenClawActivityStyle.coral)
                        self.statusText(state: state)
                            .font(OpenClawActivityType.subheadSemiBold)
                            .lineLimit(1)
                            .minimumScaleFactor(0.8)
                    }
                }
                DynamicIslandExpandedRegion(.trailing) {
                    if self.isVoiceSpeaking(state: state) {
                        Text("LIVE")
                            .font(OpenClawActivityType.eyebrow)
                            .foregroundStyle(OpenClawActivityStyle.sea)
                    } else {
                        self.trailingView(state: state)
                    }
                }
                .contentMargins(.horizontal, 8)
            } compactLeading: {
                self.agentAvatar(context: context, state: state, compact: true)
            } compactTrailing: {
                self.compactTrailingView(state: state)
            } minimal: {
                self.agentAvatar(context: context, state: state, compact: true)
            }
            .keylineTint(self.islandKeylineTint(state: state))
        }
    }

    private func lockScreenView(
        context: ActivityViewContext<OpenClawActivityAttributes>,
        state: OpenClawActivityAttributes.ContentState) -> some View
    {
        HStack(spacing: 10) {
            self.agentAvatar(context: context, state: state)
            VStack(alignment: .leading, spacing: 2) {
                Text("OpenClaw")
                    .font(OpenClawActivityType.subheadBold)
                    .lineLimit(1)
                self.statusText(state: state)
                    .font(OpenClawActivityType.caption)
                    .foregroundStyle(.secondary)
                    .lineLimit(1)
                    .minimumScaleFactor(0.8)
            }
            Spacer()
            self.trailingView(state: state)
        }
        .padding(.horizontal, 12)
        .padding(.vertical, 8)
    }

    @ViewBuilder
    private func trailingView(state: OpenClawActivityAttributes.ContentState) -> some View {
        switch state.status {
        case .voiceSpeaking:
            self.voiceTrace(state: state)
                .frame(width: 64, height: 20)
        default:
            self.statusIcon(state: state)
                .font(OpenClawActivityType.symbol(size: 16, weight: .semibold))
                .frame(width: 28, height: 28)
        }
    }

    private func agentAvatar(
        context: ActivityViewContext<OpenClawActivityAttributes>,
        state: OpenClawActivityAttributes.ContentState,
        compact: Bool = false) -> some View
    {
        TalkAvatarWaveformView(
            phase: self.voicePhase(state: state),
            palette: .liveActivity,
            diameter: compact ? 30 : 42,
            avatarDiameter: compact ? 16 : 28,
            samples: self.voiceSamples(state: state))
        {
            Text(verbatim: context.state.agentBadge ?? Self.initials(context.attributes.agentName))
                .font(OpenClawActivityType.symbol(size: compact ? 8 : 13, weight: .bold))
                .foregroundStyle(.white)
                .minimumScaleFactor(0.6)
                .lineLimit(1)
                .frame(width: compact ? 16 : 28, height: compact ? 16 : 28)
                .background(OpenClawActivityStyle.surfaceElevated, in: Circle())
        }
        .accessibilityLabel(Text(verbatim: context.attributes.agentName))
    }

    private func voicePhase(state: OpenClawActivityAttributes.ContentState) -> TalkWaveformPhase {
        switch state.status {
        case .voiceSpeaking:
            .speaking(level: self.voiceSamples(state: state).last)
        case .voiceListening:
            .listening(
                level: self.voiceSamples(state: state).last ?? 0.15,
                speechActive: true)
        case .voiceActive:
            .idle
        default:
            .idle
        }
    }

    private static func initials(_ name: String) -> String {
        let words = name.split(whereSeparator: \.isWhitespace)
        let value = words.prefix(2).compactMap(\.first).map(String.init).joined()
        return value.isEmpty ? "OC" : value.uppercased()
    }

    @ViewBuilder
    private func compactTrailingView(state: OpenClawActivityAttributes.ContentState) -> some View {
        switch state.status {
        case .voiceSpeaking:
            Text("LIVE")
                .font(OpenClawActivityType.eyebrow)
                .foregroundStyle(OpenClawActivityStyle.sea)
        default:
            self.statusIcon(state: state)
                .font(OpenClawActivityType.symbol(size: 12, weight: .semibold))
                .frame(width: 18, height: 18)
        }
    }

    private func voiceTrace(
        state: OpenClawActivityAttributes.ContentState,
        sampleRange: ClosedRange<Double> = 0...1) -> some View
    {
        TalkVoiceTraceView(
            phase: self.voicePhase(state: state),
            palette: .liveActivity,
            samples: self.voiceSamples(state: state),
            sampleRange: sampleRange)
    }

    private func voiceSamples(state: OpenClawActivityAttributes.ContentState) -> [Double] {
        (state.voiceSamples ?? []).map { Double($0) / 255 }
    }

    private func isVoiceSpeaking(state: OpenClawActivityAttributes.ContentState) -> Bool {
        state.status == .voiceSpeaking
    }

    private func islandKeylineTint(state: OpenClawActivityAttributes.ContentState) -> Color? {
        switch state.status {
        case .voiceSpeaking:
            OpenClawActivityStyle.coral
        case .voiceListening, .voiceActive:
            OpenClawActivityStyle.sea
        default:
            nil
        }
    }

    @ViewBuilder
    private func statusIcon(state: OpenClawActivityAttributes.ContentState) -> some View {
        switch state.status {
        case .connecting, .reconnecting:
            Image(systemName: "arrow.triangle.2.circlepath")
                .foregroundStyle(OpenClawActivityStyle.info)
        case .disconnected:
            Image(systemName: "wifi.slash")
                .foregroundStyle(OpenClawActivityStyle.danger)
        case .paused:
            Image(systemName: "pause.fill")
                .foregroundStyle(OpenClawActivityStyle.warn)
        case .idle:
            Image(systemName: "checkmark")
                .foregroundStyle(OpenClawActivityStyle.ok)
        case .approvalNeeded, .actionRequired, .attention:
            Image(systemName: "exclamationmark.triangle.fill")
                .foregroundStyle(OpenClawActivityStyle.warn)
        case .toolRunning:
            Image(systemName: "hammer.fill")
                .foregroundStyle(OpenClawActivityStyle.info)
        case .voiceListening:
            Image(systemName: "mic.fill")
                .foregroundStyle(OpenClawActivityStyle.sea)
        case .voiceSpeaking:
            Image(systemName: "waveform")
                .foregroundStyle(OpenClawActivityStyle.coral)
        case .voiceActive:
            Image(systemName: "waveform")
                .foregroundStyle(OpenClawActivityStyle.sea)
        }
    }

    private func statusText(state: OpenClawActivityAttributes.ContentState) -> Text {
        if let detail = state.verbatimDetail {
            return Text(verbatim: detail)
        }
        return switch state.status {
        case .connecting: Text("Connecting...")
        case .reconnecting: Text("Reconnecting...")
        case .approvalNeeded: Text("Approval needed")
        case .actionRequired, .attention: Text("Action required")
        case .toolRunning:
            if let toolName = state.toolName {
                Text(verbatim: String(format: String(localized: "Using %@"), toolName))
            } else {
                Text("Using a tool")
            }
        case .voiceListening: Text("Listening")
        case .voiceSpeaking: Text("Speaking")
        case .voiceActive: Text("Voice active")
        case .paused: Text("Paused")
        case .idle: Text("Connected")
        case .disconnected: Text("Disconnected")
        }
    }

    private func displayState(
        context: ActivityViewContext<OpenClawActivityAttributes>) -> OpenClawActivityAttributes.ContentState
    {
        guard context.isStale else { return context.state }
        switch context.state.status {
        case .connecting, .reconnecting, .approvalNeeded, .actionRequired, .attention,
             .toolRunning, .voiceListening, .voiceSpeaking, .voiceActive:
            return OpenClawActivityAttributes.ContentState(
                status: .paused,
                verbatimDetail: nil,
                startedAt: context.state.startedAt,
                agentBadge: context.state.agentBadge)
        case .paused, .idle, .disconnected:
            return context.state
        }
    }
}

private enum OpenClawActivityStyle {
    // Carapace dark-theme tokens, kept local because the widget is a separate target.
    static let coral = Color(red: 245 / 255.0, green: 101 / 255.0, blue: 74 / 255.0)
    static let sea = Color(red: 79 / 255.0, green: 200 / 255.0, blue: 174 / 255.0)
    static let surfaceElevated = Color(red: 32 / 255.0, green: 32 / 255.0, blue: 36 / 255.0)
    static let info = sea
    static let danger = Color(red: 185 / 255.0, green: 28 / 255.0, blue: 28 / 255.0)
    static let ok = Color(red: 34 / 255.0, green: 197 / 255.0, blue: 94 / 255.0)
    static let warn = Color(red: 245 / 255.0, green: 158 / 255.0, blue: 11 / 255.0)
}

extension TalkWaveformPalette {
    fileprivate static let liveActivity = TalkWaveformPalette(
        active: [
            OpenClawActivityStyle.coral,
            OpenClawActivityStyle.sea,
        ],
        inactive: [
            OpenClawActivityStyle.surfaceElevated,
            OpenClawActivityStyle.surfaceElevated,
        ])
}

import Foundation

struct ShareAttachmentSummary: Equatable {
    var selectedImageCount = 0
    var acceptedImageCount = 0
    var videoCount = 0
    var fileCount = 0
    var unknownCount = 0

    mutating func recordUnclassifiedProvider(didLoadContent: Bool) {
        if !didLoadContent {
            self.unknownCount += 1
        }
    }

    var omissionMessage: String? {
        var details: [String] = []

        if self.selectedImageCount > self.acceptedImageCount {
            details.append(String(
                format: NSLocalizedString(
                    "Only %d of %d images can be sent.",
                    comment: "Share extension image attachment limit warning"),
                self.acceptedImageCount,
                self.selectedImageCount))
        }

        var unsupported: [String] = []
        if self.videoCount > 0 {
            let format = if self.videoCount == 1 {
                NSLocalizedString("%d video", comment: "Share extension unsupported video count")
            } else {
                NSLocalizedString("%d videos", comment: "Share extension unsupported video count")
            }
            unsupported.append(String(
                format: format,
                self.videoCount))
        }
        if self.fileCount > 0 {
            let format = if self.fileCount == 1 {
                NSLocalizedString("%d file", comment: "Share extension unsupported file count")
            } else {
                NSLocalizedString("%d files", comment: "Share extension unsupported file count")
            }
            unsupported.append(String(
                format: format,
                self.fileCount))
        }
        if self.unknownCount > 0 {
            let format = if self.unknownCount == 1 {
                NSLocalizedString("%d unsupported item", comment: "Share extension unsupported attachment count")
            } else {
                NSLocalizedString("%d unsupported items", comment: "Share extension unsupported attachment count")
            }
            unsupported.append(String(
                format: format,
                self.unknownCount))
        }

        if !unsupported.isEmpty {
            details.append(String(
                format: NSLocalizedString(
                    "OpenClaw Share cannot send %@ yet.",
                    comment: "Share extension unsupported attachment warning"),
                unsupported.joined(separator: ", ")))
        }

        guard !details.isEmpty else { return nil }
        details.append(NSLocalizedString(
            "Remove omitted items and share again.",
            comment: "Share extension omitted attachment recovery"))
        return details.joined(separator: " ")
    }
}

enum ShareAttachmentBlockReason: Equatable {
    case imageProcessingFailed
    case omitted(String)

    static func resolve(
        hasImageProcessingError: Bool,
        summary: ShareAttachmentSummary) -> Self?
    {
        if hasImageProcessingError {
            return .imageProcessingFailed
        }
        if let omissionMessage = summary.omissionMessage {
            return .omitted(omissionMessage)
        }
        return nil
    }
}

import Foundation

/// Lifecycle of the share compose card. Failure carries the already-localized
/// message so the footer can surface it verbatim.
enum ShareComposeStatus: Equatable {
    case preparing
    case ready
    case sending
    case sent
    case blocked(String)
    case failed(String)
}

/// Derived control availability for a compose status. Kept UIKit-free so the
/// logic-test target can assert the state machine without instantiating views.
struct ShareComposeControlState: Equatable {
    var isSendEnabled: Bool
    var isCancelEnabled: Bool
    var isEditable: Bool

    static func resolve(status: ShareComposeStatus, hasDraftText: Bool) -> Self {
        switch status {
        case .preparing:
            // Editing stays locked until extraction lands; prepareDraft() replaces
            // the draft wholesale and must not discard text typed mid-preparation.
            Self(isSendEnabled: false, isCancelEnabled: true, isEditable: false)
        case .ready, .failed:
            Self(isSendEnabled: hasDraftText, isCancelEnabled: true, isEditable: true)
        case .blocked:
            Self(isSendEnabled: false, isCancelEnabled: true, isEditable: true)
        case .sending, .sent:
            Self(isSendEnabled: false, isCancelEnabled: false, isEditable: false)
        }
    }
}

import UIKit

/// Compose card UI for the share extension. This target cannot link the app
/// design layer (`Sources/Design`), so the accent below mirrors
/// `OpenClawBrand.activationPrimaryAction`; keep both in sync when rebranding.
final class ShareComposeView: UIView, UITextViewDelegate {
    private enum Metric {
        static let pagePadding: CGFloat = 16
        static let cardRadius: CGFloat = 16
        static let sendHeight: CGFloat = 54
        static let thumbnailSize: CGFloat = 56
        static let thumbnailRadius: CGFloat = 12
        static let headerHeight: CGFloat = 48
    }

    private static let accent = UIColor { traits in
        traits.userInterfaceStyle == .dark
            ? UIColor(red: 238 / 255, green: 82 / 255, blue: 76 / 255, alpha: 1)
            : UIColor(red: 209 / 255, green: 54 / 255, blue: 51 / 255, alpha: 1)
    }

    var onSend: (() -> Void)?
    var onCancel: (() -> Void)?

    var draftText: String {
        self.textView.text ?? ""
    }

    private let titleLabel = UILabel()
    private let cancelButton = UIButton(configuration: .plain())
    private let hairline = UIView()
    private let textView = UITextView()
    private let placeholderLabel = UILabel()
    private let attachmentsRow = UIStackView()
    private let statusContainer = UIView()
    private let statusStack = UIStackView()
    private let statusSpinner = UIActivityIndicatorView(style: .medium)
    private let statusIcon = UIImageView()
    private let statusLabel = UILabel()
    private let sendButton = UIButton(configuration: ShareComposeView.makeSendConfiguration())
    private var status: ShareComposeStatus = .preparing

    override init(frame: CGRect) {
        super.init(frame: frame)
        self.configureSubviews()
        self.installLayout()
        self.apply(.preparing)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("init(coder:) is not supported")
    }

    func setDraft(_ text: String) {
        self.textView.text = text
        self.draftDidChange()
    }

    func setAttachmentPreviews(_ images: [UIImage]) {
        for view in self.attachmentsRow.arrangedSubviews {
            view.removeFromSuperview()
        }
        guard !images.isEmpty else {
            self.attachmentsRow.isHidden = true
            return
        }
        for image in images {
            let thumbnail = UIImageView(image: image)
            thumbnail.contentMode = .scaleAspectFill
            thumbnail.clipsToBounds = true
            thumbnail.layer.cornerRadius = Metric.thumbnailRadius
            thumbnail.layer.cornerCurve = .continuous
            thumbnail.widthAnchor.constraint(equalToConstant: Metric.thumbnailSize).isActive = true
            self.attachmentsRow.addArrangedSubview(thumbnail)
        }
        let spacer = UIView()
        spacer.setContentHuggingPriority(.defaultLow, for: .horizontal)
        self.attachmentsRow.addArrangedSubview(spacer)
        self.attachmentsRow.isHidden = false
    }

    func apply(_ status: ShareComposeStatus) {
        self.status = status
        switch status {
        case .preparing:
            self.showFooter(
                text: NSLocalizedString("Preparing share…", comment: "Share extension preparation status"),
                icon: nil,
                spinning: true)
        case .ready:
            self.statusContainer.isHidden = true
        case .sending:
            self.showFooter(
                text: NSLocalizedString("Sending to OpenClaw gateway…", comment: "Share extension sending status"),
                icon: nil,
                spinning: true)
        case .sent:
            self.showFooter(
                text: NSLocalizedString("Sent to OpenClaw.", comment: "Share extension success status"),
                icon: (name: "checkmark.circle.fill", tint: .systemGreen),
                spinning: false)
        case let .blocked(message), let .failed(message):
            self.showFooter(
                text: message,
                icon: (name: "exclamationmark.triangle.fill", tint: .systemOrange),
                spinning: false)
        }
        self.updateControls()
    }

    func focusDraft() {
        self.textView.becomeFirstResponder()
    }

    func textViewDidChange(_ textView: UITextView) {
        self.draftDidChange()
    }

    private func draftDidChange() {
        if case .failed = self.status {
            // Stale failure feedback confuses fresh edits; clear it once typing resumes.
            self.apply(.ready)
            return
        }
        self.updateControls()
    }

    private func updateControls() {
        let hasDraftText = !self.draftText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        let controls = ShareComposeControlState.resolve(status: self.status, hasDraftText: hasDraftText)
        self.sendButton.isEnabled = controls.isSendEnabled
        self.cancelButton.isEnabled = controls.isCancelEnabled
        self.textView.isEditable = controls.isEditable
        self.placeholderLabel.isHidden = !self.draftText.isEmpty
    }

    private func showFooter(text: String, icon: (name: String, tint: UIColor)?, spinning: Bool) {
        self.statusContainer.isHidden = false
        self.statusLabel.text = text
        if spinning {
            self.statusSpinner.startAnimating()
        } else {
            self.statusSpinner.stopAnimating()
        }
        if let icon {
            self.statusIcon.image = UIImage(systemName: icon.name)
            self.statusIcon.tintColor = icon.tint
            self.statusIcon.isHidden = false
        } else {
            self.statusIcon.isHidden = true
        }
        UIAccessibility.post(notification: .announcement, argument: text)
    }

    private func configureSubviews() {
        self.backgroundColor = .systemGroupedBackground

        self.titleLabel.text = "OpenClaw"
        self.titleLabel.font = .preferredFont(forTextStyle: .headline)
        self.titleLabel.adjustsFontForContentSizeCategory = true
        self.titleLabel.accessibilityTraits.insert(.header)

        var cancelConfiguration = UIButton.Configuration.plain()
        cancelConfiguration.attributedTitle = Self.attributedTitle(
            NSLocalizedString("Cancel", comment: "Share extension cancel action"),
            style: .body)
        cancelConfiguration.baseForegroundColor = Self.accent
        cancelConfiguration.contentInsets = NSDirectionalEdgeInsets(top: 11, leading: 0, bottom: 11, trailing: 8)
        self.cancelButton.configuration = cancelConfiguration
        self.cancelButton.accessibilityIdentifier = "share-compose.cancel"
        self.cancelButton.addAction(UIAction { [weak self] _ in self?.onCancel?() }, for: .touchUpInside)

        self.hairline.backgroundColor = .separator

        self.textView.font = .preferredFont(forTextStyle: .body)
        self.textView.adjustsFontForContentSizeCategory = true
        self.textView.backgroundColor = .secondarySystemGroupedBackground
        self.textView.layer.cornerRadius = Metric.cardRadius
        self.textView.layer.cornerCurve = .continuous
        self.textView.textContainerInset = UIEdgeInsets(top: 14, left: 12, bottom: 14, right: 12)
        self.textView.delegate = self
        self.textView.accessibilityIdentifier = "share-compose.draft"

        self.placeholderLabel.text = NSLocalizedString(
            "Add a message, then tap Send.",
            comment: "Share extension empty draft guidance")
        self.placeholderLabel.font = .preferredFont(forTextStyle: .body)
        self.placeholderLabel.adjustsFontForContentSizeCategory = true
        self.placeholderLabel.textColor = .tertiaryLabel
        self.placeholderLabel.numberOfLines = 0
        self.placeholderLabel.isAccessibilityElement = false
        self.textView.accessibilityHint = self.placeholderLabel.text

        self.attachmentsRow.axis = .horizontal
        self.attachmentsRow.spacing = 8
        self.attachmentsRow.isHidden = true

        self.statusSpinner.hidesWhenStopped = true
        self.statusIcon.preferredSymbolConfiguration = UIImage.SymbolConfiguration(textStyle: .footnote)
        self.statusIcon.isHidden = true
        self.statusLabel.font = .preferredFont(forTextStyle: .footnote)
        self.statusLabel.adjustsFontForContentSizeCategory = true
        self.statusLabel.textColor = .secondaryLabel
        self.statusLabel.numberOfLines = 0
        self.statusLabel.textAlignment = .center

        self.sendButton.accessibilityIdentifier = "share-compose.send"
        self.sendButton.addAction(UIAction { [weak self] _ in self?.onSend?() }, for: .touchUpInside)
        self.sendButton.configurationUpdateHandler = { button in
            var configuration = button.configuration
            configuration?.baseBackgroundColor = button.isEnabled ? Self.accent : .tertiarySystemFill
            configuration?.baseForegroundColor = button.isEnabled ? .white : .secondaryLabel
            button.configuration = configuration
        }
    }

    private func installLayout() {
        let header = UIView()
        header.addSubview(self.cancelButton)
        header.addSubview(self.titleLabel)

        self.textView.addSubview(self.placeholderLabel)

        self.statusStack.axis = .horizontal
        self.statusStack.spacing = 6
        self.statusStack.alignment = .center
        self.statusStack.addArrangedSubview(self.statusSpinner)
        self.statusStack.addArrangedSubview(self.statusIcon)
        self.statusStack.addArrangedSubview(self.statusLabel)
        self.statusContainer.addSubview(self.statusStack)

        let contentStack = UIStackView(arrangedSubviews: [
            self.textView,
            self.attachmentsRow,
            self.statusContainer,
            self.sendButton,
        ])
        contentStack.axis = .vertical
        contentStack.spacing = 12

        self.addSubview(header)
        self.addSubview(self.hairline)
        self.addSubview(contentStack)

        for view in [
            header, self.cancelButton, self.titleLabel, self.hairline,
            self.placeholderLabel, self.statusStack, contentStack,
        ] {
            view.translatesAutoresizingMaskIntoConstraints = false
        }

        NSLayoutConstraint.activate([
            header.topAnchor.constraint(equalTo: self.safeAreaLayoutGuide.topAnchor),
            header.leadingAnchor.constraint(equalTo: self.leadingAnchor, constant: Metric.pagePadding),
            header.trailingAnchor.constraint(equalTo: self.trailingAnchor, constant: -Metric.pagePadding),
            header.heightAnchor.constraint(equalToConstant: Metric.headerHeight),

            self.cancelButton.leadingAnchor.constraint(equalTo: header.leadingAnchor),
            self.cancelButton.centerYAnchor.constraint(equalTo: header.centerYAnchor),
            self.titleLabel.centerXAnchor.constraint(equalTo: header.centerXAnchor),
            self.titleLabel.centerYAnchor.constraint(equalTo: header.centerYAnchor),

            self.hairline.topAnchor.constraint(equalTo: header.bottomAnchor),
            self.hairline.leadingAnchor.constraint(equalTo: self.leadingAnchor),
            self.hairline.trailingAnchor.constraint(equalTo: self.trailingAnchor),
            self.hairline.heightAnchor.constraint(equalToConstant: 0.5),

            contentStack.topAnchor.constraint(equalTo: self.hairline.bottomAnchor, constant: 12),
            contentStack.leadingAnchor.constraint(equalTo: self.leadingAnchor, constant: Metric.pagePadding),
            contentStack.trailingAnchor.constraint(equalTo: self.trailingAnchor, constant: -Metric.pagePadding),
            contentStack.bottomAnchor.constraint(equalTo: self.keyboardLayoutGuide.topAnchor, constant: -12),

            self.textView.heightAnchor.constraint(greaterThanOrEqualToConstant: 72),
            self.attachmentsRow.heightAnchor.constraint(equalToConstant: Metric.thumbnailSize),
            self.sendButton.heightAnchor.constraint(equalToConstant: Metric.sendHeight),

            self.placeholderLabel.topAnchor.constraint(
                equalTo: self.textView.frameLayoutGuide.topAnchor,
                constant: 14),
            self.placeholderLabel.leadingAnchor.constraint(
                equalTo: self.textView.frameLayoutGuide.leadingAnchor,
                constant: 17),
            self.placeholderLabel.widthAnchor.constraint(
                lessThanOrEqualTo: self.textView.frameLayoutGuide.widthAnchor,
                constant: -34),

            self.statusStack.topAnchor.constraint(equalTo: self.statusContainer.topAnchor),
            self.statusStack.bottomAnchor.constraint(equalTo: self.statusContainer.bottomAnchor),
            self.statusStack.centerXAnchor.constraint(equalTo: self.statusContainer.centerXAnchor),
            self.statusStack.leadingAnchor.constraint(greaterThanOrEqualTo: self.statusContainer.leadingAnchor),
            self.statusStack.trailingAnchor.constraint(lessThanOrEqualTo: self.statusContainer.trailingAnchor),
        ])
    }

    private static func makeSendConfiguration() -> UIButton.Configuration {
        var configuration = self.sendConfigurationBase()
        configuration.cornerStyle = .capsule
        configuration.baseBackgroundColor = self.accent
        configuration.baseForegroundColor = .white
        configuration.image = UIImage(systemName: "paperplane.fill")
        configuration.imagePadding = 8
        configuration.preferredSymbolConfigurationForImage = UIImage.SymbolConfiguration(textStyle: .subheadline)
        configuration.attributedTitle = self.attributedTitle(
            NSLocalizedString("Send to OpenClaw", comment: "Share extension send action"),
            style: .headline)
        return configuration
    }

    /// Liquid Glass primary action on iOS 26 with the filled fallback that keeps
    /// the same label, tint, and hit target on iOS 18 hosts (see DESIGN.md).
    private static func sendConfigurationBase() -> UIButton.Configuration {
        if #available(iOS 26.0, *) {
            return .prominentGlass()
        }
        return .filled()
    }

    private static func attributedTitle(_ text: String, style: UIFont.TextStyle) -> AttributedString {
        var title = AttributedString(text)
        title.font = UIFont.preferredFont(forTextStyle: style)
        return title
    }
}

import Foundation
import OpenClawKit
import UniformTypeIdentifiers

struct ExtractedShareProviderContent {
    var payload: SharedContentPayload
    var imageProviders: [NSItemProvider]
    var attachmentSummary: ShareAttachmentSummary
}

@MainActor
enum ShareContentExtractor {
    static func extract(from items: [NSExtensionItem]) async -> ExtractedShareProviderContent {
        var title: String?
        var attributedContentText: String?
        var providers: [NSItemProvider] = []
        for item in items {
            if title == nil { title = item.attributedTitle?.string }
            if attributedContentText == nil { attributedContentText = item.attributedContentText?.string }
            providers.append(contentsOf: item.attachments ?? [])
        }

        var providersWithLoadedContent = Set<ObjectIdentifier>()
        var sharedURL: URL?
        for provider in providers {
            guard let providerURL = await self.loadURL(from: provider) else { continue }
            sharedURL = providerURL
            providersWithLoadedContent.insert(ObjectIdentifier(provider))
            break
        }

        var sharedText: String?
        for provider in providers {
            guard let providerText = await self.loadText(from: provider) else { continue }
            providersWithLoadedContent.insert(ObjectIdentifier(provider))
            guard let distinctText = SharePayloadNormalizer.distinctProviderText(
                providerText,
                sharedURL: sharedURL)
            else { continue }
            sharedText = distinctText
            break
        }

        var imageProviders: [NSItemProvider] = []
        var attachmentSummary = ShareAttachmentSummary()
        for provider in providers {
            if provider.hasItemConformingToTypeIdentifier(UTType.image.identifier) {
                attachmentSummary.selectedImageCount += 1
                imageProviders.append(provider)
            } else if provider.hasItemConformingToTypeIdentifier(UTType.movie.identifier) {
                attachmentSummary.videoCount += 1
            } else if provider.hasItemConformingToTypeIdentifier(UTType.fileURL.identifier) {
                attachmentSummary.fileCount += 1
            } else {
                // UTI conformance only promises a representation exists; count it as handled
                // only after the provider successfully delivers content we can send.
                attachmentSummary.recordUnclassifiedProvider(
                    didLoadContent: providersWithLoadedContent.contains(ObjectIdentifier(provider)))
            }
        }

        let supplementalTitle = SharePayloadNormalizer.distinctAttributedText(
            attributedContentText,
            sharedText: sharedText,
            sharedURL: sharedURL)
        return ExtractedShareProviderContent(
            payload: SharedContentPayload(title: title ?? supplementalTitle, url: sharedURL, text: sharedText),
            imageProviders: imageProviders,
            attachmentSummary: attachmentSummary)
    }

    private static func loadURL(from provider: NSItemProvider) async -> URL? {
        if provider.hasItemConformingToTypeIdentifier(UTType.url.identifier),
           let url = await self.loadURLValue(from: provider, typeIdentifier: UTType.url.identifier)
        {
            return url
        }

        if provider.hasItemConformingToTypeIdentifier(UTType.text.identifier),
           let text = await self.loadTextValue(from: provider, typeIdentifier: UTType.text.identifier),
           let url = SharePayloadNormalizer.webURL(from: text)
        {
            return url
        }

        return nil
    }

    private static func loadText(from provider: NSItemProvider) async -> String? {
        if provider.hasItemConformingToTypeIdentifier(UTType.plainText.identifier),
           let text = await self.loadTextValue(from: provider, typeIdentifier: UTType.plainText.identifier)
        {
            return text
        }

        if provider.hasItemConformingToTypeIdentifier(UTType.text.identifier),
           let text = await self.loadTextValue(from: provider, typeIdentifier: UTType.text.identifier)
        {
            return text
        }

        if provider.hasItemConformingToTypeIdentifier(UTType.url.identifier),
           let url = await self.loadURLValue(from: provider, typeIdentifier: UTType.url.identifier)
        {
            return url.absoluteString
        }

        return nil
    }

    private static func loadURLValue(from provider: NSItemProvider, typeIdentifier: String) async -> URL? {
        await withCheckedContinuation { continuation in
            provider.loadItem(forTypeIdentifier: typeIdentifier, options: nil) { item, _ in
                if let url = item as? URL {
                    continuation.resume(returning: url)
                } else if let value = item as? String, let url = URL(string: value) {
                    continuation.resume(returning: url)
                } else if let value = item as? NSString, let url = URL(string: value as String) {
                    continuation.resume(returning: url)
                } else {
                    continuation.resume(returning: nil)
                }
            }
        }
    }

    private static func loadTextValue(from provider: NSItemProvider, typeIdentifier: String) async -> String? {
        await withCheckedContinuation { continuation in
            provider.loadItem(forTypeIdentifier: typeIdentifier, options: nil) { item, _ in
                if let text = item as? String {
                    continuation.resume(returning: text)
                } else if let text = item as? NSString {
                    continuation.resume(returning: text as String)
                } else if let text = item as? NSAttributedString {
                    continuation.resume(returning: text.string)
                } else {
                    continuation.resume(returning: nil)
                }
            }
        }
    }
}

import Foundation
import OpenClawKit

enum ShareDraftComposer {
    /// These lines came from the legacy generated share template. Match the
    /// complete trimmed line so real content such as "Text: details" survives.
    private static let legacyScaffoldLines: Set<String> = [
        "shared from ios.",
        "text:",
        "shared attachment(s):",
        "please help me with this.",
    ]

    static func compose(from payload: SharedContentPayload) -> String {
        var fragments: [String] = []
        let title = self.sanitize(payload.title)
        let text = self.sanitize(payload.text)
        let url = payload.url?.absoluteString.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""

        if let title { fragments.append(title) }
        if let text { fragments.append(text) }
        if !url.isEmpty { fragments.append(url) }

        return fragments.joined(separator: "\n\n")
    }

    private static func sanitize(_ raw: String?) -> String? {
        guard let raw else { return nil }
        let cleanedLines = raw
            .components(separatedBy: .newlines)
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { line in
                !line.isEmpty && !self.legacyScaffoldLines.contains(line.lowercased())
            }
        let cleaned = cleanedLines.joined(separator: "\n").trimmingCharacters(in: .whitespacesAndNewlines)
        return cleaned.isEmpty ? nil : cleaned
    }
}

enum SharePayloadNormalizer {
    static func distinctProviderText(_ raw: String?, sharedURL: URL?) -> String? {
        guard let candidate = self.trimmed(raw) else { return nil }
        return candidate == self.trimmed(sharedURL?.absoluteString) ? nil : candidate
    }

    static func distinctAttributedText(_ raw: String?, sharedText: String?, sharedURL: URL?) -> String? {
        guard let candidate = self.trimmed(raw) else { return nil }
        let duplicates = [self.trimmed(sharedText), self.trimmed(sharedURL?.absoluteString)].compactMap(\.self)
        return duplicates.contains(candidate) ? nil : candidate
    }

    static func webURL(from raw: String) -> URL? {
        guard let trimmed = self.trimmed(raw) else { return nil }
        guard let components = URLComponents(string: trimmed),
              let scheme = components.scheme?.lowercased(),
              scheme == "http" || scheme == "https",
              components.host?.isEmpty == false
        else {
            return nil
        }
        return components.url
    }

    private static func trimmed(_ raw: String?) -> String? {
        guard let raw else { return nil }
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }
}

import Foundation
import OpenClawKit
import os
import UIKit
import UniformTypeIdentifiers

final class ShareViewController: UIViewController {
    private struct ShareAttachment: Codable {
        var type: String
        var mimeType: String
        var fileName: String
        var content: String
    }

    /// Keeps the encoded payload with its preview so the compose card can show
    /// thumbnails without re-decoding base64 content.
    private struct LoadedAttachment {
        var payload: ShareAttachment
        var preview: UIImage
    }

    private struct ExtractedShareContent {
        var payload: SharedContentPayload
        var attachments: [LoadedAttachment]
        var attachmentSummary: ShareAttachmentSummary
        var attachmentError: ShareImageProcessor.ProcessError?
    }

    private let logger = Logger(subsystem: "ai.openclawfoundation.app", category: "ShareExtension")
    private let composeView = ShareComposeView()
    private var didPrepareDraft = false
    private var isSending = false
    private var pendingAttachments: [ShareAttachment] = []
    /// Keep omission state controller-owned so send cannot bypass the disabled UI.
    private var attachmentBlockReason: ShareAttachmentBlockReason?

    override func loadView() {
        self.view = self.composeView
    }

    override func viewDidLoad() {
        super.viewDidLoad()
        self.preferredContentSize = CGSize(width: UIScreen.main.bounds.width, height: 420)
        self.composeView.onSend = { [weak self] in self?.handleSendTap() }
        self.composeView.onCancel = { [weak self] in
            self?.extensionContext?.completeRequest(returningItems: nil)
        }
    }

    override func viewDidAppear(_ animated: Bool) {
        super.viewDidAppear(animated)
        guard !self.didPrepareDraft else { return }
        self.didPrepareDraft = true
        Task { await self.prepareDraft() }
    }

    private func prepareDraft() async {
        let traceId = UUID().uuidString
        ShareGatewayRelaySettings.saveLastEvent("Share opened.")
        self.composeView.apply(.preparing)
        self.logger.info("share begin trace=\(traceId, privacy: .public)")
        let extracted = await self.extractSharedContent()
        let payload = extracted.payload
        self.pendingAttachments = extracted.attachments.map(\.payload)
        self.attachmentBlockReason = ShareAttachmentBlockReason.resolve(
            hasImageProcessingError: extracted.attachmentError != nil,
            summary: extracted.attachmentSummary)
        self.logger.info("share payload trace=\(traceId, privacy: .public)")
        self.logger.info(
            "share payload title=\(payload.title?.count ?? 0) text=\(payload.text?.count ?? 0)")
        self.logger.info(
            "share attachments hasURL=\(payload.url != nil) images=\(self.pendingAttachments.count)")
        let message = ShareDraftComposer.compose(from: payload)
        self.composeView.setDraft(message)
        self.composeView.setAttachmentPreviews(extracted.attachments.map(\.preview))
        self.composeView.focusDraft()
        if let blockReason = self.attachmentBlockReason {
            self.applyAttachmentBlockReason(blockReason)
        } else if message.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            self.composeView.apply(.ready)
            ShareGatewayRelaySettings.saveLastEvent("Share ready: waiting for message input.")
        } else {
            self.composeView.apply(.ready)
            ShareGatewayRelaySettings.saveLastEvent("Share ready: draft prepared.")
        }
    }

    private func handleSendTap() {
        guard !self.isSending else { return }
        Task { await self.sendCurrentDraft() }
    }

    private func sendCurrentDraft() async {
        if let blockReason = self.attachmentBlockReason {
            self.applyAttachmentBlockReason(blockReason)
            return
        }
        let trimmed = self.composeView.draftText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            ShareGatewayRelaySettings.saveLastEvent("Share blocked: message is empty.")
            self.composeView.apply(.failed(NSLocalizedString(
                "Message is empty.",
                comment: "Share extension empty message status")))
            return
        }

        self.isSending = true
        self.composeView.apply(.sending)
        ShareGatewayRelaySettings.saveLastEvent("Sending to gateway…")
        do {
            try await self.sendMessageToGateway(trimmed, attachments: self.pendingAttachments)
            ShareGatewayRelaySettings.saveLastEvent(
                "Sent to gateway (\(trimmed.count) chars, \(self.pendingAttachments.count) attachment(s)).")
            self.composeView.apply(.sent)
            UINotificationFeedbackGenerator().notificationOccurred(.success)
            // Give the success state a visible beat before the sheet dismisses.
            try? await Task.sleep(for: .milliseconds(600))
            self.extensionContext?.completeRequest(returningItems: nil)
        } catch {
            self.logger.error("share send failed reason=\(error.localizedDescription, privacy: .public)")
            ShareGatewayRelaySettings.saveLastEvent("Send failed: \(error.localizedDescription)")
            self.isSending = false
            self.composeView.apply(.failed(String(
                format: NSLocalizedString("Send failed: %@", comment: "Share extension failure status"),
                error.localizedDescription)))
        }
    }

    private func sendMessageToGateway(_ message: String, attachments: [ShareAttachment]) async throws {
        guard let config = ShareGatewayRelaySettings.loadConfigDiscardingUnscopedDeviceAuth() else {
            throw NSError(
                domain: "OpenClawShare",
                code: 10,
                userInfo: [
                    NSLocalizedDescriptionKey: NSLocalizedString(
                        "OpenClaw is not connected to a gateway yet.",
                        comment: "Share extension missing gateway error"),
                ])
        }
        guard let url = URL(string: config.gatewayURLString) else {
            throw NSError(
                domain: "OpenClawShare",
                code: 11,
                userInfo: [
                    NSLocalizedDescriptionKey: NSLocalizedString(
                        "Invalid saved gateway URL.",
                        comment: "Share extension invalid gateway error"),
                ])
        }

        let gateway = GatewayNodeSession()
        defer {
            Task { await gateway.disconnect() }
        }
        let makeOptions: (String) -> GatewayConnectOptions = { clientId in
            GatewayConnectOptions(
                role: "node",
                scopes: [],
                caps: [],
                commands: [],
                permissions: [:],
                clientId: clientId,
                clientMode: "node",
                clientDisplayName: "OpenClaw Share",
                deviceIdentityProfile: .shareExtension,
                includeDeviceIdentity: true,
                allowStoredDeviceAuth: config.gatewayStableID != nil,
                deviceAuthGatewayID: config.gatewayStableID)
        }

        do {
            try await gateway.connect(
                url: url,
                credentials: GatewayNodeSessionCredentials(
                    token: config.token,
                    password: config.password),
                connectOptions: makeOptions("openclaw-ios"),
                sessionBox: nil,
                onConnected: {},
                onDisconnected: { _ in },
                onInvoke: { req in
                    BridgeInvokeResponse(
                        id: req.id,
                        ok: false,
                        error: OpenClawNodeError(
                            code: .invalidRequest,
                            message: "share extension does not support node invoke"))
                })
        } catch {
            let expectsLegacyClientId = self.shouldRetryWithLegacyClientId(error)
            guard expectsLegacyClientId else { throw error }
            try await gateway.connect(
                url: url,
                credentials: GatewayNodeSessionCredentials(
                    token: config.token,
                    password: config.password),
                connectOptions: makeOptions("moltbot-ios"),
                sessionBox: nil,
                onConnected: {},
                onDisconnected: { _ in },
                onInvoke: { req in
                    BridgeInvokeResponse(
                        id: req.id,
                        ok: false,
                        error: OpenClawNodeError(
                            code: .invalidRequest,
                            message: "share extension does not support node invoke"))
                })
        }

        struct AgentRequestPayload: Codable {
            var message: String
            var sessionKey: String?
            var thinking: String
            var deliver: Bool
            var attachments: [ShareAttachment]?
            var receipt: Bool
            var receiptText: String?
            var to: String?
            var channel: String?
            var timeoutSeconds: Int?
            var key: String?
        }

        let deliveryChannel = config.deliveryChannel?.trimmingCharacters(in: .whitespacesAndNewlines)
        let deliveryTo = config.deliveryTo?.trimmingCharacters(in: .whitespacesAndNewlines)
        let canDeliverToRoute = (deliveryChannel?.isEmpty == false) && (deliveryTo?.isEmpty == false)

        let params = AgentRequestPayload(
            message: message,
            sessionKey: config.sessionKey,
            thinking: "low",
            deliver: canDeliverToRoute,
            attachments: attachments.isEmpty ? nil : attachments,
            receipt: canDeliverToRoute,
            receiptText: canDeliverToRoute ? "Just received your iOS share + request, working on it." : nil,
            to: canDeliverToRoute ? deliveryTo : nil,
            channel: canDeliverToRoute ? deliveryChannel : nil,
            timeoutSeconds: nil,
            key: UUID().uuidString)
        let data = try JSONEncoder().encode(params)
        guard let json = String(data: data, encoding: .utf8) else {
            throw NSError(
                domain: "OpenClawShare",
                code: 12,
                userInfo: [NSLocalizedDescriptionKey: "Failed to encode chat payload."])
        }
        struct NodeEventParams: Codable {
            var event: String
            var payloadJSON: String
        }
        let eventData = try JSONEncoder().encode(NodeEventParams(event: "agent.request", payloadJSON: json))
        guard let nodeEventParams = String(data: eventData, encoding: .utf8) else {
            throw NSError(
                domain: "OpenClawShare",
                code: 13,
                userInfo: [NSLocalizedDescriptionKey: "Failed to encode node event payload."])
        }
        _ = try await gateway.request(method: "node.event", paramsJSON: nodeEventParams, timeoutSeconds: 25)
    }

    private func shouldRetryWithLegacyClientId(_ error: Error) -> Bool {
        if let gatewayError = error as? GatewayResponseError {
            let code = gatewayError.code.lowercased()
            let message = gatewayError.message.lowercased()
            let pathValue = (gatewayError.details["path"]?.value as? String)?.lowercased() ?? ""
            let mentionsClientIdPath =
                message.contains("/client/id") || message.contains("client id")
                || pathValue.contains("/client/id")
            let isInvalidConnectParams =
                (code.contains("invalid") && code.contains("connect"))
                || message.contains("invalid connect params")
            if isInvalidConnectParams, mentionsClientIdPath {
                return true
            }
        }

        let text = error.localizedDescription.lowercased()
        return text.contains("invalid connect params")
            && (text.contains("/client/id") || text.contains("client id"))
    }

    private func extractSharedContent() async -> ExtractedShareContent {
        guard let items = self.extensionContext?.inputItems as? [NSExtensionItem] else {
            return ExtractedShareContent(
                payload: SharedContentPayload(title: nil, url: nil, text: nil),
                attachments: [],
                attachmentSummary: ShareAttachmentSummary(),
                attachmentError: nil)
        }

        let providerContent = await ShareContentExtractor.extract(from: items)
        var attachments: [LoadedAttachment] = []
        var attachmentSummary = providerContent.attachmentSummary
        var attachmentError: ShareImageProcessor.ProcessError?
        let maxImageAttachments = 3

        for provider in providerContent.imageProviders.prefix(maxImageAttachments) {
            guard attachmentError == nil else { break }
            do {
                let attachment = try await self.loadImageAttachment(
                    from: provider,
                    index: attachments.count)
                attachments.append(attachment)
            } catch let error as ShareImageProcessor.ProcessError {
                attachmentError = error
            } catch {
                attachmentError = .encodeFailed
            }
        }
        attachmentSummary.acceptedImageCount = attachments.count
        return ExtractedShareContent(
            payload: providerContent.payload,
            attachments: attachments,
            attachmentSummary: attachmentSummary,
            attachmentError: attachmentError)
    }

    private func loadImageAttachment(from provider: NSItemProvider, index: Int) async throws -> LoadedAttachment {
        let imageUTI = self.preferredImageTypeIdentifier(from: provider) ?? UTType.image.identifier
        guard let rawData = await self.loadDataValue(from: provider, typeIdentifier: imageUTI) else {
            throw ShareImageProcessor.ProcessError.invalidImage
        }

        let data = try await Task.detached(priority: .userInitiated) {
            try ShareImageProcessor.processForUpload(data: rawData)
        }.value
        guard let image = UIImage(data: data) else {
            throw ShareImageProcessor.ProcessError.invalidImage
        }

        return await LoadedAttachment(
            payload: ShareAttachment(
                type: "image",
                mimeType: "image/jpeg",
                fileName: "shared-image-\(index + 1).jpg",
                content: data.base64EncodedString()),
            preview: self.boundedPreview(from: image))
    }

    private func imageProcessingErrorMessage() -> String {
        NSLocalizedString(
            "The shared image could not be prepared.",
            comment: "Share extension image processing failure")
    }

    private func applyAttachmentBlockReason(_ blockReason: ShareAttachmentBlockReason) {
        switch blockReason {
        case .imageProcessingFailed:
            ShareGatewayRelaySettings.saveLastEvent("Share blocked: image processing failed.")
            self.composeView.apply(.blocked(self.imageProcessingErrorMessage()))
        case let .omitted(message):
            ShareGatewayRelaySettings.saveLastEvent("Share blocked: attachment(s) omitted.")
            self.composeView.apply(.blocked(message))
        }
    }

    /// Previews are retained for the sheet's lifetime; keep them bounded so
    /// three full-resolution photos cannot blow the extension memory cap.
    /// Never falls back to the full-size image.
    private func boundedPreview(from image: UIImage) async -> UIImage {
        let maxPixels: CGFloat = 336
        if let thumbnail = await image.byPreparingThumbnail(ofSize: CGSize(width: maxPixels, height: maxPixels)) {
            return thumbnail
        }
        let longestSide = max(image.size.width * image.scale, image.size.height * image.scale, 1)
        let scale = min(maxPixels / longestSide, 1)
        let target = CGSize(
            width: max(image.size.width * image.scale * scale, 1),
            height: max(image.size.height * image.scale * scale, 1))
        let format = UIGraphicsImageRendererFormat.default()
        format.scale = 1
        return UIGraphicsImageRenderer(size: target, format: format).image { _ in
            image.draw(in: CGRect(origin: .zero, size: target))
        }
    }

    private func preferredImageTypeIdentifier(from provider: NSItemProvider) -> String? {
        for identifier in provider.registeredTypeIdentifiers {
            guard let utType = UTType(identifier) else { continue }
            if utType.conforms(to: .image) {
                return identifier
            }
        }
        return nil
    }

    private func loadDataValue(from provider: NSItemProvider, typeIdentifier: String) async -> Data? {
        await withCheckedContinuation { continuation in
            provider.loadDataRepresentation(forTypeIdentifier: typeIdentifier) { data, _ in
                continuation.resume(returning: data)
            }
        }
    }
}

