/// Session-scoped dashboard rendered by the gateway Control UI.
struct SessionDashboardScreen: View {
    @Environment(NodeAppModel.self) private var appModel
    @Environment(\.dismiss) private var dismiss
    @State private var showsDesktop = false
    let sessionKey: String
    let agentId: String?

    var body: some View {
        let config = self.appModel.activeGatewayConnectConfig
        let storedOperatorToken = AuthenticatedControlUI.storedOperatorToken(config: config)
        ZStack {
            OpenClawProBackground()
            if let url = Self.dashboardURL(
                config: config,
                sessionKey: self.sessionKey,
                agentId: self.agentId)
            {
                AuthenticatedControlUIWebView(
                    url: url,
                    authScript: AuthenticatedControlUI.authUserScript(
                        config: config,
                        pageURL: url,
                        storedOperatorToken: storedOperatorToken,
                        usesNativeNavigationChrome: true),
                    tls: config?.tls,
                    allowedMainFramePathPrefix: Self.dashboardPathPrefix(config: config),
                    onMainFrameNavigationOutsideScope: {
                        self.dismiss()
                    })
                    .id(AuthenticatedControlUI.webContentIdentity(
                        config: config,
                        storedOperatorToken: storedOperatorToken))
                    .ignoresSafeArea(.container, edges: .bottom)
            } else {
                self.unavailableCard
            }
        }
        .navigationTitle("Dashboard")
        .navigationBarTitleDisplayMode(.inline)
        .toolbar {
            if self.appModel.isDesktopObserveAvailable {
                ToolbarItem(placement: .topBarTrailing) {
                    Button {
                        self.showsDesktop = true
                    } label: {
                        Image(systemName: "display")
                            .font(OpenClawType.subheadSemiBold)
                    }
                    .accessibilityLabel("Open Desktop")
                    .accessibilityIdentifier("SessionDashboard.Desktop")
                }
            }
            ToolbarItem(placement: .topBarTrailing) {
                Button {
                    self.dismiss()
                } label: {
                    Text("Done")
                        .font(OpenClawType.subheadSemiBold)
                }
            }
        }
        .navigationDestination(isPresented: self.$showsDesktop) {
            DesktopHubScreen(session: self.sessionKey, usesNativeNavigationChrome: true)
        }
    }

    private var unavailableCard: some View {
        VStack(spacing: 12) {
            ProIconBadge(systemName: "rectangle.grid.2x2", color: OpenClawBrand.accent)
            Text("Dashboard needs a connected gateway")
                .font(OpenClawType.subheadSemiBold)
            Text("Connect to your gateway to open this session dashboard.")
                .font(OpenClawType.caption)
                .foregroundStyle(.secondary)
                .multilineTextAlignment(.center)
        }
        .padding(24)
    }

    /// Converts the active gateway WebSocket endpoint into the shell-free
    /// dashboard focus route. Credentials stay in the startup script.
    static func dashboardURL(
        config: GatewayConnectConfig?,
        sessionKey: String,
        agentId: String? = nil) -> URL?
    {
        let normalizedSessionKey = sessionKey.trimmingCharacters(in: .whitespacesAndNewlines)
        if normalizedSessionKey.lowercased() == "global" {
            let normalizedAgentId = agentId?
                .trimmingCharacters(in: .whitespacesAndNewlines)
                .lowercased() ?? ""
            guard !normalizedAgentId.isEmpty,
                  let encodedAgent = Self.encodedRouteSegment(normalizedAgentId)
            else { return nil }
            return AuthenticatedControlUI.pageURL(
                config: config,
                path: ["focus", "dashboard", encodedAgent].joined(separator: "/"),
                queryItems: [])
        }

        let parts = normalizedSessionKey
            .split(separator: ":", omittingEmptySubsequences: false)
        guard parts.count >= 3,
              parts[0].lowercased() == "agent",
              parts.dropFirst().allSatisfy({ !$0.isEmpty })
        else { return nil }

        let encodedSegments = parts.dropFirst().map { Self.encodedRouteSegment(String($0)) }
        let routeSegments = encodedSegments.compactMap(\.self)
        guard routeSegments.count == encodedSegments.count,
              let encodedAgent = routeSegments.first
        else { return nil }
        let route = (["focus", "dashboard", encodedAgent, "~key"] + routeSegments.dropFirst())
            .joined(separator: "/")
        return AuthenticatedControlUI.pageURL(
            config: config,
            path: route,
            queryItems: [])
    }

    private static func encodedRouteSegment(_ value: String) -> String? {
        if value == "." {
            return "~dot"
        }
        if value == ".." {
            return "~dotdot"
        }
        guard let encoded = AuthenticatedControlUI.percentEncodedPathSegment(value) else { return nil }
        var escaped = encoded.replacingOccurrences(of: ".", with: "%2E")
        if escaped.hasPrefix("~") {
            escaped.insert("~", at: escaped.startIndex)
        }
        return escaped
    }

    static func dashboardPathPrefix(config: GatewayConnectConfig?) -> String? {
        AuthenticatedControlUI.pageURL(
            config: config,
            path: "focus/dashboard",
            queryItems: [])?.path
    }
}

import Contacts
import Foundation
import OpenClawKit

final class ContactsService: ContactsServicing {
    private let authorizationStatus: @Sendable () -> CNAuthorizationStatus

    init(
        authorizationStatus: @escaping @Sendable () -> CNAuthorizationStatus = {
            CNContactStore.authorizationStatus(for: .contacts)
        })
    {
        self.authorizationStatus = authorizationStatus
    }

    private static var payloadKeys: [CNKeyDescriptor] {
        [
            CNContactIdentifierKey as CNKeyDescriptor,
            CNContactGivenNameKey as CNKeyDescriptor,
            CNContactFamilyNameKey as CNKeyDescriptor,
            CNContactOrganizationNameKey as CNKeyDescriptor,
            CNContactPhoneNumbersKey as CNKeyDescriptor,
            CNContactEmailAddressesKey as CNKeyDescriptor,
            // CNContactFormatter requires more keys than payload(from:) accesses directly.
            // Fetch its declared key set; formatting a partial contact otherwise raises an
            // Objective-C CNContactPropertyNotFetchedException and crashes the app.
            CNContactFormatter.descriptorForRequiredKeys(for: .fullName),
        ]
    }

    func search(params: OpenClawContactsSearchParams) async throws -> OpenClawContactsSearchPayload {
        let store = try self.authorizedStore()

        let limit = max(1, min(params.limit ?? 25, 200))

        var contacts: [CNContact] = []
        if let query = params.query?.trimmingCharacters(in: .whitespacesAndNewlines), !query.isEmpty {
            let predicate = CNContact.predicateForContacts(matchingName: query)
            contacts = try store.unifiedContacts(matching: predicate, keysToFetch: Self.payloadKeys)
        } else {
            let request = CNContactFetchRequest(keysToFetch: Self.payloadKeys)
            try store.enumerateContacts(with: request) { contact, stop in
                contacts.append(contact)
                if contacts.count >= limit {
                    stop.pointee = true
                }
            }
        }

        let sliced = Array(contacts.prefix(limit))
        let payload = sliced.map { Self.payload(from: $0) }

        return OpenClawContactsSearchPayload(contacts: payload)
    }

    func add(params: OpenClawContactsAddParams) async throws -> OpenClawContactsAddPayload {
        let store = try self.authorizedStore()

        let givenName = params.givenName?.trimmingCharacters(in: .whitespacesAndNewlines)
        let familyName = params.familyName?.trimmingCharacters(in: .whitespacesAndNewlines)
        let organizationName = params.organizationName?.trimmingCharacters(in: .whitespacesAndNewlines)
        let displayName = params.displayName?.trimmingCharacters(in: .whitespacesAndNewlines)
        let phoneNumbers = Self.normalizeStrings(params.phoneNumbers)
        let emails = Self.normalizeStrings(params.emails, lowercased: true)

        let hasName = !(givenName ?? "").isEmpty || !(familyName ?? "").isEmpty || !(displayName ?? "").isEmpty
        let hasOrg = !(organizationName ?? "").isEmpty
        let hasDetails = !phoneNumbers.isEmpty || !emails.isEmpty
        guard hasName || hasOrg || hasDetails else {
            throw NSError(domain: "Contacts", code: 2, userInfo: [
                NSLocalizedDescriptionKey: "CONTACTS_INVALID: include a name, organization, phone, or email",
            ])
        }

        if !phoneNumbers.isEmpty || !emails.isEmpty {
            if let existing = try Self.findExistingContact(
                store: store,
                phoneNumbers: phoneNumbers,
                emails: emails)
            {
                return OpenClawContactsAddPayload(contact: Self.payload(from: existing))
            }
        }

        let contact = CNMutableContact()
        contact.givenName = givenName ?? ""
        contact.familyName = familyName ?? ""
        contact.organizationName = organizationName ?? ""
        if contact.givenName.isEmpty, contact.familyName.isEmpty, let displayName {
            contact.givenName = displayName
        }
        contact.phoneNumbers = phoneNumbers.map {
            CNLabeledValue(label: CNLabelPhoneNumberMobile, value: CNPhoneNumber(stringValue: $0))
        }
        contact.emailAddresses = emails.map {
            CNLabeledValue(label: CNLabelHome, value: $0 as NSString)
        }

        let save = CNSaveRequest()
        save.add(contact, toContainerWithIdentifier: nil)
        try store.execute(save)

        let persisted: CNContact = if !contact.identifier.isEmpty {
            try store.unifiedContact(
                withIdentifier: contact.identifier,
                keysToFetch: Self.payloadKeys)
        } else {
            contact
        }

        return OpenClawContactsAddPayload(contact: Self.payload(from: persisted))
    }

    private static func ensureAuthorization(status: CNAuthorizationStatus) -> Bool {
        switch status {
        case .authorized, .limited:
            return true
        case .notDetermined:
            return false
        case .restricted, .denied:
            return false
        @unknown default:
            return false
        }
    }

    private func authorizedStore() throws -> CNContactStore {
        let status = self.authorizationStatus()
        let authorized = Self.ensureAuthorization(status: status)
        guard authorized else {
            throw NSError(domain: "Contacts", code: 1, userInfo: [
                NSLocalizedDescriptionKey: "CONTACTS_PERMISSION_REQUIRED: grant Contacts permission",
            ])
        }
        return CNContactStore()
    }

    private static func normalizeStrings(_ values: [String]?, lowercased: Bool = false) -> [String] {
        (values ?? [])
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
            .map { lowercased ? $0.lowercased() : $0 }
    }

    private static func findExistingContact(
        store: CNContactStore,
        phoneNumbers: [String],
        emails: [String]) throws -> CNContact?
    {
        if phoneNumbers.isEmpty, emails.isEmpty {
            return nil
        }

        var matches: [CNContact] = []

        for phone in phoneNumbers {
            let predicate = CNContact.predicateForContacts(matching: CNPhoneNumber(stringValue: phone))
            let contacts = try store.unifiedContacts(matching: predicate, keysToFetch: Self.payloadKeys)
            matches.append(contentsOf: contacts)
        }

        for email in emails {
            let predicate = CNContact.predicateForContacts(matchingEmailAddress: email)
            let contacts = try store.unifiedContacts(matching: predicate, keysToFetch: Self.payloadKeys)
            matches.append(contentsOf: contacts)
        }

        return Self.matchContacts(contacts: matches, phoneNumbers: phoneNumbers, emails: emails)
    }

    private static func matchContacts(
        contacts: [CNContact],
        phoneNumbers: [String],
        emails: [String]) -> CNContact?
    {
        let normalizedPhones = Set(phoneNumbers.map { self.normalizePhone($0) }.filter { !$0.isEmpty })
        let normalizedEmails = Set(emails.map { $0.lowercased() }.filter { !$0.isEmpty })
        var seen = Set<String>()

        for contact in contacts {
            guard seen.insert(contact.identifier).inserted else { continue }
            let contactPhones = Set(contact.phoneNumbers.map { self.normalizePhone($0.value.stringValue) })
            let contactEmails = Set(contact.emailAddresses.map { String($0.value).lowercased() })

            if !normalizedPhones.isEmpty, !contactPhones.isDisjoint(with: normalizedPhones) {
                return contact
            }
            if !normalizedEmails.isEmpty, !contactEmails.isDisjoint(with: normalizedEmails) {
                return contact
            }
        }

        return nil
    }

    private static func normalizePhone(_ phone: String) -> String {
        let trimmed = phone.trimmingCharacters(in: .whitespacesAndNewlines)
        let digits = trimmed.unicodeScalars.filter { CharacterSet.decimalDigits.contains($0) }
        let normalized = String(String.UnicodeScalarView(digits))
        return normalized.isEmpty ? trimmed : normalized
    }

    private static func payload(from contact: CNContact) -> OpenClawContactPayload {
        OpenClawContactPayload(
            identifier: contact.identifier,
            displayName: CNContactFormatter.string(from: contact, style: .fullName)
                ?? "\(contact.givenName) \(contact.familyName)".trimmingCharacters(in: .whitespacesAndNewlines),
            givenName: contact.givenName,
            familyName: contact.familyName,
            organizationName: contact.organizationName,
            phoneNumbers: contact.phoneNumbers.map(\.value.stringValue),
            emails: contact.emailAddresses.map { String($0.value) })
    }
}

import OpenClawKit
import OpenClawProtocol
import SwiftUI

private enum AgentAutomationDetailSection: String, CaseIterable, Identifiable {
    case settings
    case history

    var id: String {
        self.rawValue
    }

    var title: String {
        switch self {
        case .settings: String(localized: "Settings")
        case .history: String(localized: "History")
        }
    }
}

private struct AgentAutomationNotice {
    enum Tone: Equatable {
        case success
        case warning
        case error

        var color: Color {
            switch self {
            case .success: OpenClawBrand.accent
            case .warning: .orange
            case .error: .red
            }
        }
    }

    let tone: Tone
    let title: String
    let message: String
}

struct AgentAutomationDetailScreen: View {
    @Environment(NodeAppModel.self) private var appModel
    @Environment(\.dismiss) private var dismiss

    @State private var job: CronJob
    @State private var draft: AgentAutomationDraft?
    @State private var runs: [CronRunLogEntry] = []
    @State private var selectedSection: AgentAutomationDetailSection = .settings
    @State private var loading = false
    @State private var actionName: String?
    @State private var notice: AgentAutomationNotice?
    @State private var confirmDelete = false

    private let sourceGatewayID: String
    private let pendingRunRegistry: AgentAutomationPendingRunRegistry
    private let onRunQueued: (String, String?) -> Void
    private let onChanged: () -> Void

    init(
        initialJob: CronJob,
        sourceGatewayID: String,
        pendingRunRegistry: AgentAutomationPendingRunRegistry,
        onRunQueued: @escaping (String, String?) -> Void,
        onChanged: @escaping () -> Void)
    {
        self._job = State(initialValue: initialJob)
        self._draft = State(initialValue: AgentAutomationDraft(job: initialJob))
        self.sourceGatewayID = sourceGatewayID
        self.pendingRunRegistry = pendingRunRegistry
        self.onRunQueued = onRunQueued
        self.onChanged = onChanged
    }

    var body: some View {
        NavigationStack {
            ZStack {
                OpenClawProBackground()
                ScrollView {
                    VStack(alignment: .leading, spacing: 14) {
                        self.summaryCard
                        self.sectionPicker
                        if let notice {
                            self.noticeCard(notice)
                        }
                        if self.selectedSection == .settings {
                            self.settingsContent
                        } else {
                            self.historyContent
                        }
                    }
                    .padding(.vertical, 12)
                }
                .scrollDismissesKeyboard(.interactively)
                if self.loading, self.draft == nil {
                    ProgressView()
                        .controlSize(.large)
                }
            }
            .navigationTitle("Automation")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button {
                        self.dismiss()
                    } label: {
                        Text("Close")
                            .font(OpenClawType.subheadSemiBold)
                    }
                }
                ToolbarItem(placement: .primaryAction) {
                    Button {
                        Task { await self.reload() }
                    } label: {
                        Image(systemName: "arrow.clockwise")
                    }
                    .disabled(self.loading || self.isBusy)
                    .accessibilityLabel("Refresh automation")
                }
            }
        }
        .font(OpenClawType.body)
        .presentationDetents([.large])
        .interactiveDismissDisabled(self.isBusy)
        .task { await self.initialLoad() }
        .confirmationDialog(
            "Delete this automation?",
            isPresented: self.$confirmDelete,
            titleVisibility: .visible)
        {
            Button(role: .destructive) {
                Task { await self.deleteAutomation() }
            } label: {
                Text("Delete Automation")
                    .font(OpenClawType.subheadSemiBold)
            }
            Button(role: .cancel) {} label: {
                Text("Cancel")
                    .font(OpenClawType.subheadSemiBold)
            }
        } message: {
            Text("This permanently removes the automation and its schedule from the Gateway.")
                .font(OpenClawType.caption)
        }
    }

    private var isBusy: Bool {
        self.actionName != nil
    }

    private var pendingRunID: String? {
        self.pendingRunRegistry.runID(for: self.job.id)
    }

    private var canAdmin: Bool {
        self.appModel.hasOperatorAdminScope
    }

    private var hasUnsavedChanges: Bool {
        guard let draft else { return false }
        return agentAutomationHasSemanticChanges(job: self.job, draft: draft)
    }

    private var summaryCard: some View {
        ProCard(radius: OpenClawProMetric.cardRadius) {
            VStack(alignment: .leading, spacing: 12) {
                HStack(alignment: .top, spacing: 12) {
                    ProIconBadge(
                        systemName: self.job.enabled ? "clock.arrow.circlepath" : "pause.circle.fill",
                        color: self.job.enabled ? OpenClawBrand.accent : .secondary)
                    VStack(alignment: .leading, spacing: 3) {
                        Text(self.job.name)
                            .font(OpenClawType.headline)
                            .lineLimit(2)
                        Text(self.scheduleSummary)
                            .font(OpenClawType.caption)
                            .foregroundStyle(.secondary)
                    }
                    Spacer(minLength: 8)
                    ProValuePill(
                        value: self.job.enabled ? String(localized: "active") : String(localized: "paused"),
                        color: self.job.enabled ? OpenClawBrand.accent : .secondary)
                }
                HStack(spacing: 8) {
                    self.summaryMetric(
                        title: String(localized: "Next run"),
                        value: Self.relativeTime(self.job.nextrunatms ?? self.stateMilliseconds("nextRunAtMs")))
                    self.summaryMetric(
                        title: String(localized: "Last run"),
                        value: Self.relativeTime(self.job.lastrunatms ?? self.stateMilliseconds("lastRunAtMs")))
                }
            }
        }
        .padding(.horizontal, OpenClawProMetric.pagePadding)
    }

    private func summaryMetric(title: String, value: String) -> some View {
        VStack(alignment: .leading, spacing: 3) {
            Text(title)
                .font(OpenClawType.caption2SemiBold)
                .foregroundStyle(.secondary)
            Text(value)
                .font(OpenClawType.subheadSemiBold)
                .lineLimit(1)
        }
        .padding(10)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(.thinMaterial, in: RoundedRectangle(cornerRadius: 10, style: .continuous))
    }

    private var sectionPicker: some View {
        Picker("Automation detail", selection: self.$selectedSection) {
            ForEach(AgentAutomationDetailSection.allCases) { section in
                Text(section.title)
                    .font(OpenClawType.captionSemiBold)
                    .tag(section)
            }
        }
        .pickerStyle(.segmented)
        .padding(.horizontal, OpenClawProMetric.pagePadding)
    }

    @ViewBuilder
    private var settingsContent: some View {
        if let draftBinding = Binding(self.$draft) {
            Group {
                self.identityCard(draftBinding)
                self.scheduleCard(draftBinding)
                self.actionCard(draftBinding)
                self.executionCard(draftBinding)
            }
            .disabled(self.loading || self.isBusy)
            self.managementCard(draftBinding)
                .disabled(self.loading || self.isBusy)
        } else {
            self.messageCard(
                icon: "exclamationmark.triangle.fill",
                color: .orange,
                title: String(localized: "Editing unavailable"),
                message: AgentAutomationEditError.invalidModel.localizedDescription)
        }
    }

    private func identityCard(_ draft: Binding<AgentAutomationDraft>) -> some View {
        self.cardSection(title: String(localized: "Details"), icon: "text.alignleft") {
            self.labeledField(
                String(localized: "Name"),
                text: draft.name,
                prompt: String(localized: "Automation name"))
            self.labeledField(
                String(localized: "Description"),
                text: draft.description,
                prompt: String(localized: "Optional context"),
                axis: .vertical)
        }
    }

    private func scheduleCard(_ draft: Binding<AgentAutomationDraft>) -> some View {
        self.cardSection(title: String(localized: "Schedule"), icon: "calendar.badge.clock") {
            Text(draft.wrappedValue.schedule.kindLabel)
                .font(OpenClawType.captionSemiBold)
                .foregroundStyle(OpenClawBrand.accent)
            self.scheduleFields(draft)
            if case .at = draft.wrappedValue.schedule {
                Toggle(isOn: draft.deleteAfterRun) {
                    VStack(alignment: .leading, spacing: 2) {
                        Text("Delete after successful run")
                            .font(OpenClawType.subheadSemiBold)
                        Text("Useful for one-time automations.")
                            .font(OpenClawType.caption)
                            .foregroundStyle(.secondary)
                    }
                }
                .tint(OpenClawBrand.accent)
            }
        }
    }

    @ViewBuilder
    private func scheduleFields(_ draft: Binding<AgentAutomationDraft>) -> some View {
        switch draft.wrappedValue.schedule {
        case .at:
            self.labeledField(
                String(localized: "ISO date and time"),
                text: self.scheduleBinding(draft, keyPath: \.at),
                prompt: "2030-01-15T09:00:00Z")
        case .every:
            self.labeledField(
                String(localized: "Interval (milliseconds)"),
                text: self.scheduleBinding(draft, keyPath: \.everyMs),
                prompt: "86400000",
                keyboard: .numberPad)
            self.labeledField(
                String(localized: "Anchor (milliseconds)"),
                text: self.scheduleBinding(draft, keyPath: \.anchorMs),
                prompt: String(localized: "Optional"),
                keyboard: .numberPad)
        case .cron:
            self.labeledField(
                String(localized: "Cron expression"),
                text: self.scheduleBinding(draft, keyPath: \.expression),
                prompt: "0 9 * * 1-5")
            self.labeledField(
                String(localized: "Time zone"),
                text: self.scheduleBinding(draft, keyPath: \.timezone),
                prompt: "America/Los_Angeles")
            self.labeledField(
                String(localized: "Stagger (milliseconds)"),
                text: self.scheduleBinding(draft, keyPath: \.staggerMs),
                prompt: String(localized: "Optional"),
                keyboard: .numberPad)
        case .onExit:
            self.labeledField(
                String(localized: "Command to watch"),
                text: self.scheduleBinding(draft, keyPath: \.command),
                prompt: "pnpm build")
            self.labeledField(
                String(localized: "Working directory"),
                text: self.scheduleBinding(draft, keyPath: \.cwd),
                prompt: String(localized: "Optional"))
        }
    }

    private func actionCard(_ draft: Binding<AgentAutomationDraft>) -> some View {
        self.cardSection(title: String(localized: "Action"), icon: "bolt.fill") {
            Text(draft.wrappedValue.payload.kindLabel)
                .font(OpenClawType.captionSemiBold)
                .foregroundStyle(OpenClawBrand.accent)
            self.payloadFields(draft)
        }
    }

    @ViewBuilder
    private func payloadFields(_ draft: Binding<AgentAutomationDraft>) -> some View {
        switch draft.wrappedValue.payload {
        case .systemEvent:
            self.labeledField(
                String(localized: "Event text"),
                text: self.payloadBinding(draft, keyPath: \.text),
                prompt: String(localized: "What should the agent know?"),
                axis: .vertical)
        case .agentTurn:
            self.labeledField(
                String(localized: "Message"),
                text: self.payloadBinding(draft, keyPath: \.message),
                prompt: String(localized: "What should the agent do?"),
                axis: .vertical)
            self.labeledField(
                String(localized: "Model"),
                text: self.payloadBinding(draft, keyPath: \.model),
                prompt: String(localized: "Gateway default"))
            self.labeledField(
                String(localized: "Thinking"),
                text: self.payloadBinding(draft, keyPath: \.thinking),
                prompt: String(localized: "Gateway default"))
        case .command:
            self.labeledField(
                String(localized: "Arguments (JSON array)"),
                text: self.payloadBinding(draft, keyPath: \.argvJSON),
                prompt: #"["openclaw","status"]"#,
                axis: .vertical)
            self.labeledField(
                String(localized: "Working directory"),
                text: self.payloadBinding(draft, keyPath: \.cwd),
                prompt: String(localized: "Optional"))
        }
    }

    private func executionCard(_ draft: Binding<AgentAutomationDraft>) -> some View {
        self.cardSection(title: String(localized: "Execution"), icon: "scope") {
            self.labeledField(
                String(localized: "Session target"),
                text: draft.sessionTarget,
                prompt: "main, isolated, current, or session:<id>")
            self.labeledField(
                String(localized: "Wake mode"),
                text: draft.wakeMode,
                prompt: "now or next-heartbeat")
            if self.job.delivery != nil || self.job.failurealert != nil {
                Text("Delivery and failure routing remain visible and editable in the Control UI.")
                    .font(OpenClawType.caption)
                    .foregroundStyle(.secondary)
            }
        }
    }

    private func managementCard(_ draft: Binding<AgentAutomationDraft>) -> some View {
        self.cardSection(title: String(localized: "Manage"), icon: "slider.horizontal.3") {
            if !self.canAdmin {
                Text("Admin scope is required to change, run, or delete automations.")
                    .font(OpenClawType.caption)
                    .foregroundStyle(.secondary)
            }
            HStack(spacing: 8) {
                self.actionButton(
                    title: String(localized: "Save"),
                    icon: "checkmark.circle.fill",
                    prominent: true,
                    enabled: self.canAdmin && self.hasUnsavedChanges && !self.isBusy)
                {
                    Task { await self.save(draft.wrappedValue) }
                }
                self.actionButton(
                    title: self.pendingRunID == nil ? String(localized: "Run Now") : String(localized: "Running"),
                    icon: self.pendingRunID == nil ? "play.fill" : "hourglass",
                    enabled: self.canAdmin && !self.hasUnsavedChanges && !self.isBusy && self.pendingRunID == nil)
                {
                    Task { await self.runNow() }
                }
            }
            HStack(spacing: 8) {
                self.actionButton(
                    title: self.job.enabled ? String(localized: "Pause") : String(localized: "Enable"),
                    icon: self.job.enabled ? "pause.fill" : "checkmark",
                    enabled: self.canAdmin && !self.hasUnsavedChanges && !self.isBusy)
                {
                    Task { await self.setEnabled(!self.job.enabled) }
                }
                self.actionButton(
                    title: String(localized: "Delete"),
                    icon: "trash",
                    role: .destructive,
                    enabled: self.canAdmin && !self.isBusy)
                {
                    self.confirmDelete = true
                }
            }
            if let actionName {
                HStack(spacing: 8) {
                    ProgressView().controlSize(.small)
                    Text(actionName)
                        .font(OpenClawType.caption)
                        .foregroundStyle(.secondary)
                }
            }
            if self.hasUnsavedChanges {
                Text("Save or discard edits before running, pausing, or enabling this automation.")
                    .font(OpenClawType.caption)
                    .foregroundStyle(.secondary)
            }
        }
    }

