struct AgentWorkspaceDirectoryList: View {
    @Environment(NodeAppModel.self) var appModel
    let agentId: String
    let path: String

    @State private var entries: [AgentsWorkspaceEntry] = []
    @State private var totalEntries = 0
    @State private var loading = false
    @State private var loadingMore = false
    @State private var errorText: String?

    var body: some View {
        List {
            if let errorText {
                Section {
                    Text(errorText)
                        .font(OpenClawType.footnote)
                        .foregroundStyle(OpenClawBrand.warn)
                }
            } else if self.entries.isEmpty, !self.loading {
                Section {
                    Text("This folder is empty.")
                        .font(OpenClawType.footnote)
                        .foregroundStyle(.secondary)
                }
            }
            Section {
                ForEach(self.entries, id: \.path) { entry in
                    self.entryRow(entry)
                }
                if self.entries.count < self.totalEntries {
                    self.loadMoreRow
                }
            }
        }
        .listStyle(.insetGrouped)
        .scrollContentBackground(.hidden)
        .font(OpenClawType.body)
        .overlay {
            if self.loading, self.entries.isEmpty {
                ProgressView()
            }
        }
        .refreshable {
            await self.reload()
        }
        .task(id: "\(self.agentId)|\(self.path)") {
            await self.reload()
        }
    }

    private func entryRow(_ entry: AgentsWorkspaceEntry) -> some View {
        let isDirectory = self.isDirectory(entry)
        return NavigationLink {
            if isDirectory {
                ZStack {
                    OpenClawProBackground()
                    AgentWorkspaceDirectoryList(agentId: self.agentId, path: entry.path)
                }
                .navigationTitle(AgentWorkspaceFilesScreen.displayName(forPath: entry.path))
                .navigationBarTitleDisplayMode(.inline)
                .toolbar(.visible, for: .navigationBar)
            } else {
                AgentWorkspaceFilePreview(agentId: self.agentId, path: entry.path)
                    .toolbar(.visible, for: .navigationBar)
            }
        } label: {
            HStack(spacing: 12) {
                Image(systemName: isDirectory ? "folder" : "doc.text")
                    .font(OpenClawType.subhead)
                    .foregroundStyle(isDirectory ? OpenClawBrand.accent : Color.secondary)
                    .frame(width: 24)
                VStack(alignment: .leading, spacing: 2) {
                    Text(entry.name)
                        .font(OpenClawType.subhead)
                        .foregroundStyle(.primary)
                        .lineLimit(1)
                    if let detail = self.entryDetail(entry) {
                        Text(detail)
                            .font(OpenClawType.caption)
                            .foregroundStyle(.secondary)
                            .lineLimit(1)
                    }
                }
            }
        }
    }

    private var loadMoreRow: some View {
        Button {
            Task { await self.loadMore() }
        } label: {
            HStack {
                Text("Load More")
                    .font(OpenClawType.subheadMedium)
                Spacer()
                if self.loadingMore {
                    ProgressView()
                } else {
                    Text(verbatim: String(
                        format: String(localized: "%1$@ of %2$@"),
                        self.entries.count.formatted(),
                        self.totalEntries.formatted()))
                        .font(OpenClawType.caption)
                        .foregroundStyle(.secondary)
                }
            }
        }
        .disabled(self.loadingMore)
    }

    private func isDirectory(_ entry: AgentsWorkspaceEntry) -> Bool {
        (entry.kind.value as? String) == "directory"
    }

    private func entryDetail(_ entry: AgentsWorkspaceEntry) -> String? {
        var parts: [String] = []
        if let size = entry.size {
            parts.append(ByteCountFormatter.string(fromByteCount: Int64(size), countStyle: .file))
        }
        if let updatedAtMs = entry.updatedatms {
            let date = Date(timeIntervalSince1970: Double(updatedAtMs) / 1000)
            parts.append(date.formatted(.relative(presentation: .named, unitsStyle: .abbreviated)))
        }
        return parts.isEmpty ? nil : parts.joined(separator: " • ")
    }

    @MainActor
    private func reload() async {
        self.loading = true
        self.errorText = nil
        defer { self.loading = false }
        if let result = await self.fetchPage(offset: 0) {
            self.entries = result.entries
            self.totalEntries = result.totalentries
        }
    }

    @MainActor
    private func loadMore() async {
        guard !self.loadingMore else { return }
        self.loadingMore = true
        defer { self.loadingMore = false }
        if let result = await self.fetchPage(offset: self.entries.count) {
            let known = Set(self.entries.map(\.path))
            self.entries.append(contentsOf: result.entries.filter { !known.contains($0.path) })
            self.totalEntries = result.totalentries
        }
    }

    @MainActor
    private func fetchPage(offset: Int) async -> AgentsWorkspaceListResult? {
        do {
            let params = AgentsWorkspaceListParams(
                agentid: self.agentId,
                path: self.path.isEmpty ? nil : self.path,
                offset: offset == 0 ? nil : offset,
                limit: nil)
            let paramsJSON = try Self.encodeParams(params)
            let data = try await self.appModel.operatorSession.request(
                method: "agents.workspace.list",
                paramsJSON: paramsJSON,
                timeoutSeconds: 12)
            return try JSONDecoder().decode(AgentsWorkspaceListResult.self, from: data)
        } catch {
            self.errorText = "Could not load this folder."
            return nil
        }
    }

    static func encodeParams(_ params: some Encodable) throws -> String {
        let data = try JSONEncoder().encode(params)
        return String(data: data, encoding: .utf8) ?? "{}"
    }
}

struct AgentWorkspaceFilePreview: View {
    @Environment(NodeAppModel.self) var appModel
    let agentId: String
    let path: String

    private struct ShareItem: Identifiable {
        let id = UUID()
        let fileURL: URL
    }

    @State private var file: AgentsWorkspaceFile?
    @State private var loading = false
    @State private var errorText: String?
    @State private var shareItem: ShareItem?
    @State private var showsShareError = false

    var body: some View {
        ZStack {
            OpenClawProBackground()
            self.content
        }
        .navigationTitle(AgentWorkspaceFilesScreen.displayName(forPath: self.path))
        .navigationBarTitleDisplayMode(.inline)
        .toolbar {
            ToolbarItem(placement: .topBarTrailing) {
                Button {
                    self.share()
                } label: {
                    Image(systemName: "square.and.arrow.up")
                }
                .accessibilityLabel("Share file")
                .disabled(self.file == nil)
            }
        }
        .sheet(item: self.$shareItem) { item in
            ChatTranscriptShareSheet(fileURL: item.fileURL)
        }
        .alert("Could not share this file.", isPresented: self.$showsShareError) {
            Button {
                self.showsShareError = false
            } label: {
                Text("OK")
                    .font(OpenClawType.subheadMedium)
            }
        }
        .task(id: "\(self.agentId)|\(self.path)") {
            await self.load()
        }
    }

    @ViewBuilder
    private var content: some View {
        if let file {
            self.preview(for: file)
        } else if self.loading {
            ProgressView()
        } else if let errorText {
            VStack(spacing: 8) {
                Image(systemName: "doc.questionmark")
                    .font(OpenClawType.title3SemiBold)
                    .foregroundStyle(.secondary)
                Text(errorText)
                    .font(OpenClawType.footnote)
                    .foregroundStyle(.secondary)
                    .multilineTextAlignment(.center)
            }
            .padding(OpenClawProMetric.pagePadding)
        }
    }

    @ViewBuilder
    private func preview(for file: AgentsWorkspaceFile) -> some View {
        if self.isImage(file), let image = self.decodedImage(file) {
            ScrollView([.horizontal, .vertical]) {
                Image(uiImage: image)
                    .resizable()
                    .scaledToFit()
                    .frame(maxWidth: .infinity)
                    .padding(OpenClawProMetric.pagePadding)
            }
        } else {
            ScrollView([.horizontal, .vertical]) {
                Text(ChatCodeHighlightCache.highlighted(
                    code: file.content,
                    languageId: self.languageId))
                    .font(OpenClawType.monoSmall)
                    .textSelection(.enabled)
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .padding(OpenClawProMetric.pagePadding)
            }
        }
    }

    private var fileExtension: String {
        (self.path as NSString).pathExtension.lowercased()
    }

    /// The highlighter's language ids line up with common file extensions;
    /// unknown ids fall back to plain text rendering.
    private var languageId: String? {
        self.fileExtension.isEmpty ? nil : self.fileExtension
    }

    private func isImage(_ file: AgentsWorkspaceFile) -> Bool {
        (file.encoding.value as? String) == "base64" && file.mimetype.hasPrefix("image/")
    }

    private func decodedImage(_ file: AgentsWorkspaceFile) -> UIImage? {
        guard let data = Data(base64Encoded: file.content) else { return nil }
        return UIImage(data: data)
    }

    @MainActor
    private func load() async {
        self.loading = true
        self.file = nil
        self.errorText = nil
        defer { self.loading = false }
        do {
            let params = AgentsWorkspaceGetParams(agentid: self.agentId, path: self.path)
            let paramsJSON = try AgentWorkspaceDirectoryList.encodeParams(params)
            let data = try await self.appModel.operatorSession.request(
                method: "agents.workspace.get",
                paramsJSON: paramsJSON,
                timeoutSeconds: 20)
            self.file = try JSONDecoder().decode(AgentsWorkspaceGetResult.self, from: data).file
        } catch {
            self.errorText = "This file cannot be previewed. It may be binary or too large."
        }
    }

    /// Mirrors the chat transcript export flow: write a temp copy, then hand
    /// it to the system share sheet.
    private func share() {
        guard let file else { return }
        let safeName = (file.name as NSString).lastPathComponent
        guard !safeName.isEmpty, safeName != ".", safeName != ".." else {
            self.showsShareError = true
            return
        }
        // Each share gets stable bytes at a unique URL; a later same-basename
        // export must not replace the item already handed to an extension.
        let directory = FileManager.default.temporaryDirectory
            .appendingPathComponent("OpenClawWorkspaceFiles", isDirectory: true)
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        let fileURL = directory.appendingPathComponent(safeName, isDirectory: false)
        do {
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
            if self.isImage(file) {
                guard let data = Data(base64Encoded: file.content) else {
                    self.showsShareError = true
                    return
                }
                try data.write(to: fileURL, options: .atomic)
            } else {
                try file.content.write(to: fileURL, atomically: true, encoding: .utf8)
            }
            self.shareItem = ShareItem(fileURL: fileURL)
        } catch {
            self.showsShareError = true
        }
    }
}

import Foundation
import SwiftUI

struct MobileBackgroundTask: Decodable, Identifiable, Equatable {
    struct Timestamp: Decodable, Equatable {
        let milliseconds: Double

        init(from decoder: Decoder) throws {
            let container = try decoder.singleValueContainer()
            if let number = try? container.decode(Double.self) {
                self.milliseconds = number
                return
            }
            let value = try container.decode(String.self)
            let fractionalFormatter = ISO8601DateFormatter()
            fractionalFormatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
            guard let date = fractionalFormatter.date(from: value) ?? ISO8601DateFormatter().date(from: value) else {
                throw DecodingError.dataCorruptedError(
                    in: container,
                    debugDescription: "Expected a millisecond timestamp or ISO-8601 date")
            }
            self.milliseconds = date.timeIntervalSince1970 * 1000
        }
    }

    let id: String
    let status: String
    let runtime: String?
    let title: String?
    let agentId: String?
    let sessionKey: String?
    let childSessionKey: String?
    let createdAt: Timestamp?
    let updatedAt: Timestamp?
    let startedAt: Timestamp?
    let endedAt: Timestamp?
    let lastActivity: String?
    let progressSummary: String?
    let terminalSummary: String?
    let error: String?
    let prompt: String?

    var displayTitle: String {
        self.title?.trimmingCharacters(in: .whitespacesAndNewlines).nilIfEmpty
            ?? self.id.trimmingCharacters(in: .whitespacesAndNewlines).nilIfEmpty
            ?? String(localized: "Background task")
    }

    var isActive: Bool {
        self.status == "queued" || self.status == "running"
    }

    var statusLabel: String {
        switch self.status {
        case "queued": String(localized: "Queued")
        case "running": String(localized: "Running")
        case "completed": String(localized: "Completed")
        default: String(localized: "Failed")
        }
    }

    var runtimeLabel: String {
        switch self.runtime {
        case "subagent": String(localized: "Subagent")
        case "cron": String(localized: "Cron")
        case "acp": "ACP"
        case "cli": "CLI"
        default: String(localized: "Task")
        }
    }

    var output: String? {
        let candidates = if self.status == "failed" || self.status == "timed_out" {
            [self.error, self.terminalSummary, self.lastActivity, self.progressSummary]
        } else {
            [self.terminalSummary, self.error, self.lastActivity, self.progressSummary]
        }
        return candidates.compactMap { $0?.trimmingCharacters(in: .whitespacesAndNewlines).nilIfEmpty }.first
    }

    var activityMilliseconds: Double {
        self.updatedAt?.milliseconds ?? self.endedAt?.milliseconds
            ?? self.startedAt?.milliseconds ?? self.createdAt?.milliseconds ?? 0
    }
}

extension String {
    fileprivate var nilIfEmpty: String? {
        self.isEmpty ? nil : self
    }
}

private struct MobileBackgroundTasksEnvelope: Decodable {
    let tasks: [MobileBackgroundTask]
}

private struct MobileBackgroundTaskEnvelope: Decodable {
    let task: MobileBackgroundTask
}

private struct MobileBackgroundTasksListParams: Encodable {
    let agentId: String
    let status: [String]?
    let limit: Int
}

private struct MobileBackgroundTaskGetParams: Encodable {
    let taskId: String
}

enum MobileBackgroundTaskList {
    @MainActor
    static func load(
        request: (_ status: [String], _ limit: Int) async throws -> [MobileBackgroundTask]) async throws
        -> [MobileBackgroundTask]
    {
        // Active first, terminal second: a monotonic active-to-terminal transition
        // is then present in at least one snapshot instead of falling between calls.
        let active = try await request(["queued", "running"], 200)
        let finished = try await request(["completed", "failed", "cancelled", "timed_out"], 100)
        return self.merge(recent: finished, active: active)
    }

    static func merge(
        recent: [MobileBackgroundTask],
        active: [MobileBackgroundTask]) -> [MobileBackgroundTask]
    {
        var byId: [String: MobileBackgroundTask] = [:]
        for task in recent + active {
            guard let current = byId[task.id] else {
                byId[task.id] = task
                continue
            }
            if task.activityMilliseconds > current.activityMilliseconds ||
                (task.activityMilliseconds == current.activityMilliseconds && !task.isActive)
            {
                byId[task.id] = task
            }
        }
        return byId.values.sorted {
            if $0.activityMilliseconds != $1.activityMilliseconds {
                return $0.activityMilliseconds > $1.activityMilliseconds
            }
            return $0.id < $1.id
        }
    }
}

struct BackgroundTasksScreen: View {
    @Environment(NodeAppModel.self) private var appModel
    let agentID: String

    @State private var tasks: [MobileBackgroundTask] = []
    @State private var loading = true
    @State private var errorMessage: String?

    private var activeTasks: [MobileBackgroundTask] {
        self.tasks.filter(\.isActive)
    }

    private var finishedTasks: [MobileBackgroundTask] {
        self.tasks.filter { !$0.isActive }.prefix(50).map(\.self)
    }

    var body: some View {
        NavigationStack {
            Group {
                if self.loading, self.tasks.isEmpty {
                    ProgressView {
                        Text("Loading background tasks…")
                            .font(OpenClawType.body)
                    }
                } else if let errorMessage, self.tasks.isEmpty {
                    ContentUnavailableView(
                        "Couldn’t Load Tasks",
                        systemImage: "exclamationmark.triangle",
                        description: Text(errorMessage).font(OpenClawType.body))
                } else if self.tasks.isEmpty {
                    ContentUnavailableView(
                        "No Background Tasks",
                        systemImage: "clock.arrow.circlepath",
                        description: Text("Tasks for this agent will appear here.")
                            .font(OpenClawType.body))
                } else {
                    List {
                        if let errorMessage {
                            Text(errorMessage)
                                .font(OpenClawType.footnote)
                                .foregroundStyle(OpenClawBrand.warn)
                        }
                        Section {
                            if self.activeTasks.isEmpty {
                                Text("No running tasks")
                                    .font(OpenClawType.body)
                                    .foregroundStyle(.secondary)
                            } else {
                                ForEach(self.activeTasks) { task in
                                    self.taskLink(task)
                                }
                            }
                        } header: {
                            Text("Running").font(OpenClawType.captionMedium)
                        }
                        Section {
                            if self.finishedTasks.isEmpty {
                                Text("No finished tasks")
                                    .font(OpenClawType.body)
                                    .foregroundStyle(.secondary)
                            } else {
                                ForEach(self.finishedTasks) { task in
                                    self.taskLink(task)
                                }
                            }
                        } header: {
                            Text("Finished").font(OpenClawType.captionMedium)
                        }
                    }
                    .listStyle(.insetGrouped)
                    .refreshable { await self.loadTasks() }
                }
            }
            .navigationTitle("Background Tasks")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    Button {
                        Task { await self.loadTasks() }
                    } label: {
                        Label {
                            Text("Refresh").font(OpenClawType.body)
                        } icon: {
                            Image(systemName: "arrow.clockwise")
                        }
                    }
                    .disabled(self.loading)
                }
            }
        }
        .task { await self.loadTasks() }
    }

    private func taskLink(_ task: MobileBackgroundTask) -> some View {
        NavigationLink {
            BackgroundTaskDetailScreen(task: task)
        } label: {
            VStack(alignment: .leading, spacing: 7) {
                Text(task.displayTitle)
                    .font(OpenClawType.subheadMedium)
                    .foregroundStyle(.primary)
                    .lineLimit(2)
                HStack(spacing: 7) {
                    Text(task.statusLabel)
                        .font(OpenClawType.captionMedium)
                        .foregroundStyle(self.statusColor(task))
                    Text(task.runtimeLabel)
                        .font(OpenClawType.caption)
                        .foregroundStyle(.secondary)
                    Spacer()
                }
                if let output = task.output {
                    Text(output)
                        .font(OpenClawType.footnote)
                        .foregroundStyle(.secondary)
                        .lineLimit(2)
                }
            }
            .padding(.vertical, 3)
        }
        .accessibilityIdentifier("background-task-\(task.id)")
    }

    private func statusColor(_ task: MobileBackgroundTask) -> Color {
        switch task.status {
        case "completed": OpenClawBrand.ok
        case "failed", "timed_out": OpenClawBrand.warn
        case "queued", "running": OpenClawBrand.accent
        default: .secondary
        }
    }

    @MainActor
    private func loadTasks() async {
        self.loading = true
        self.errorMessage = nil
        do {
            self.tasks = try await MobileBackgroundTaskList.load { status, limit in
                try await self.requestTasks(status: status, limit: limit)
            }
        } catch {
            self.errorMessage = error.localizedDescription
        }
        self.loading = false
    }

    private func requestTasks(status: [String]?, limit: Int) async throws -> [MobileBackgroundTask] {
        let params = MobileBackgroundTasksListParams(agentId: self.agentID, status: status, limit: limit)
        let data = try await self.request(method: "tasks.list", params: params)
        return try JSONDecoder().decode(MobileBackgroundTasksEnvelope.self, from: data).tasks
    }

    private func request(method: String, params: some Encodable) async throws -> Data {
        let payload = try JSONEncoder().encode(params)
        guard let paramsJSON = String(data: payload, encoding: .utf8) else {
            throw CocoaError(.fileReadCorruptFile)
        }
        return try await self.appModel.operatorSession.request(
            method: method,
            paramsJSON: paramsJSON,
            timeoutSeconds: 12)
    }
}

