            let selectionID = self.viewModel.thinkingSelectionID
            VStack(spacing: 0) {
                ChatActionMenuSectionHeader(
                    title: "Thinking",
                    resetAccessibilityIdentifier: selectionID == OpenClawChatViewModel.inheritedThinkingSelectionID
