            .contentShape(Rectangle())
            .accessibilityElement(children: .contain)
            .accessibilityIdentifier("chat-fast-mode-hit-target")
        }
        .padding(.horizontal, ChatActionMenuMetric.horizontalPadding)
        .padding(.vertical, 6)
    }

