@MainActor
@Observable
final class GatewayDiscoveryModel {
    struct DebugLogEntry: Identifiable, Equatable {
        var id = UUID()
        var ts: Date
        var message: String
    }

    struct DiscoveredGateway: Identifiable, Equatable {
        var id: GatewayStableIdentifier.Key {
            GatewayStableIdentifier.Key(self.stableID)
        }

        var name: String
        var endpoint: NWEndpoint
        var stableID: String
        var debugID: String
        var lanHost: String?
        var tailnetDns: String?
        var gatewayPort: Int?
        var tlsEnabled: Bool
        var tlsFingerprintSha256: String?
        var cliPath: String?

        static func == (lhs: Self, rhs: Self) -> Bool {
            lhs.name == rhs.name &&
                lhs.endpoint == rhs.endpoint &&
                GatewayStableIdentifier.matches(lhs.stableID, rhs.stableID) &&
                lhs.debugID == rhs.debugID &&
                lhs.lanHost == rhs.lanHost &&
                lhs.tailnetDns == rhs.tailnetDns &&
                lhs.gatewayPort == rhs.gatewayPort &&
                lhs.tlsEnabled == rhs.tlsEnabled &&
                lhs.tlsFingerprintSha256 == rhs.tlsFingerprintSha256 &&
                lhs.cliPath == rhs.cliPath
        }
    }

    var gateways: [DiscoveredGateway] = []
    var statusText: String = GatewayDiscoveryStatusText.idle
    private(set) var debugLog: [DebugLogEntry] = []

    private var browsers: [String: NWBrowser] = [:]
    private var gatewaysByDomain: [String: [DiscoveredGateway]] = [:]
    private var statesByDomain: [String: NWBrowser.State] = [:]
    private var debugLoggingEnabled = false
    private var lastStableIDs = Set<GatewayStableIdentifier.Key>()

    func setDebugLoggingEnabled(_ enabled: Bool) {
        let wasEnabled = self.debugLoggingEnabled
        self.debugLoggingEnabled = enabled
        if !enabled {
            self.debugLog = []
        } else if !wasEnabled {
            self.appendDebugLog("debug logging enabled")
            self.appendDebugLog("snapshot: status=\(self.statusText) gateways=\(self.gateways.count)")
        }
    }

    func start() {
        if !self.browsers.isEmpty { return }
        self.appendDebugLog("start()")

        for domain in OpenClawBonjour.gatewayServiceDomains {
            let browser = GatewayDiscoveryBrowserSupport.makeBrowser(
                serviceType: OpenClawBonjour.gatewayServiceType,
                domain: domain,
                queueLabelPrefix: "ai.openclawfoundation.app.gateway-discovery",
                onState: { [weak self] state in
                    guard let self else { return }
                    self.statesByDomain[domain] = state
                    self.updateStatusText()
                    self.appendDebugLog("state[\(domain)]: \(Self.prettyState(state))")
                },
                onResults: { [weak self] results in
                    guard let self else { return }
                    self.gatewaysByDomain[domain] = results.compactMap { result -> DiscoveredGateway? in
                        switch result.endpoint {
                        case let .service(name, _, _, _):
                            let decodedName = BonjourEscapes.decode(name)
                            let txt = result.endpoint.txtRecord?.dictionary ?? [:]
                            let advertisedName = txt["displayName"]
                            let prettyAdvertised = advertisedName
                                .map(Self.prettifyInstanceName)
                                .flatMap { $0.isEmpty ? nil : $0 }
                            let prettyName = prettyAdvertised ?? Self.prettifyInstanceName(decodedName)
                            return DiscoveredGateway(
                                name: prettyName,
                                endpoint: result.endpoint,
                                stableID: GatewayEndpointID.stableID(result.endpoint),
                                debugID: GatewayEndpointID.prettyDescription(result.endpoint),
                                lanHost: Self.txtValue(txt, key: "lanHost"),
                                tailnetDns: Self.txtValue(txt, key: "tailnetDns"),
                                gatewayPort: Self.txtIntValue(txt, key: "gatewayPort"),
                                tlsEnabled: Self.txtBoolValue(txt, key: "gatewayTls"),
                                tlsFingerprintSha256: Self.txtValue(txt, key: "gatewayTlsSha256"),
                                cliPath: Self.txtValue(txt, key: "cliPath"))
                        default:
                            return nil
                        }
                    }
                    .sorted { $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending }
                    self.recomputeGateways()
                })

            self.browsers[domain] = browser
        }
    }

    func stop() {
        self.appendDebugLog("stop()")
        for browser in self.browsers.values {
            browser.cancel()
        }
        self.browsers = [:]
        self.gatewaysByDomain = [:]
        self.statesByDomain = [:]
        self.gateways = []
        self.statusText = GatewayDiscoveryStatusText.stopped
    }

    private func recomputeGateways() {
        let next = self.gatewaysByDomain.values
            .flatMap(\.self)
            .sorted { $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending }

        let nextIDs = Set(next.map { GatewayStableIdentifier.Key($0.stableID) })
        let added = nextIDs.subtracting(self.lastStableIDs)
        let removed = self.lastStableIDs.subtracting(nextIDs)
        if !added.isEmpty || !removed.isEmpty {
            self.appendDebugLog("results: total=\(next.count) added=\(added.count) removed=\(removed.count)")
        }
        self.lastStableIDs = nextIDs
        self.gateways = next
    }

    private func updateStatusText() {
        self.statusText = GatewayDiscoveryStatusText.make(
            states: Array(self.statesByDomain.values),
            hasBrowsers: !self.browsers.isEmpty)
    }

    private static func prettyState(_ state: NWBrowser.State) -> String {
        switch state {
        case .setup:
            "setup"
        case .ready:
            "ready"
        case let .failed(err):
            "failed (\(err))"
        case .cancelled:
            "cancelled"
        case let .waiting(err):
            "waiting (\(err))"
        @unknown default:
            "unknown"
        }
    }

    private func appendDebugLog(_ message: String) {
        guard self.debugLoggingEnabled else { return }
        self.debugLog.append(DebugLogEntry(ts: Date(), message: message))
        if self.debugLog.count > 200 {
            self.debugLog.removeFirst(self.debugLog.count - 200)
        }
    }

    private static func prettifyInstanceName(_ decodedName: String) -> String {
        let normalized = decodedName.split(whereSeparator: \.isWhitespace).joined(separator: " ")
        let stripped = normalized.replacingOccurrences(of: " (OpenClaw)", with: "")
            .replacingOccurrences(of: #"\s+\(\d+\)$"#, with: "", options: .regularExpression)
        return stripped.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private static func txtValue(_ dict: [String: String], key: String) -> String? {
        let raw = dict[key]?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return raw.isEmpty ? nil : raw
    }

    private static func txtIntValue(_ dict: [String: String], key: String) -> Int? {
        guard let raw = self.txtValue(dict, key: key) else { return nil }
        return Int(raw)
    }

    private static func txtBoolValue(_ dict: [String: String], key: String) -> Bool {
        guard let raw = self.txtValue(dict, key: key)?.lowercased() else { return false }
        return raw == "1" || raw == "true" || raw == "yes"
    }
}

import Foundation
import OpenClawKit

@MainActor
final class GatewayHealthMonitor {
    struct Config {
        var intervalSeconds: Double
        var timeoutSeconds: Double
        var maxFailures: Int
    }

    private let config: Config
    private let sleep: @Sendable (UInt64) async -> Void
    private var task: Task<Void, Never>?

    init(
        config: Config = Config(intervalSeconds: 15, timeoutSeconds: 5, maxFailures: 3),
        sleep: @escaping @Sendable (UInt64) async -> Void = { nanoseconds in
            try? await Task.sleep(nanoseconds: nanoseconds)
        })
    {
        self.config = config
        self.sleep = sleep
    }

    func start(
        check: @escaping @Sendable () async throws -> Bool,
        onFailure: @escaping @Sendable (_ failureCount: Int) async -> Void)
    {
        self.stop()
        let config = self.config
        let sleep = self.sleep
        self.task = Task { @MainActor in
            var failures = 0
            while !Task.isCancelled {
                let ok = await Self.runCheck(check: check, timeoutSeconds: config.timeoutSeconds)
                if ok {
                    failures = 0
                } else {
                    failures += 1
                    if failures >= max(1, config.maxFailures) {
                        await onFailure(failures)
                        failures = 0
                    }
                }

                if Task.isCancelled { break }
                let interval = max(0.0, config.intervalSeconds)
                let nanos = UInt64(interval * 1_000_000_000)
                if nanos > 0 {
                    await sleep(nanos)
                } else {
                    await Task.yield()
                }
            }
        }
    }

    func stop() {
        self.task?.cancel()
        self.task = nil
    }

    private static func runCheck(
        check: @escaping @Sendable () async throws -> Bool,
        timeoutSeconds: Double) async -> Bool
    {
        let timeout = max(0.0, timeoutSeconds)
        if timeout == 0 {
            return await (try? check()) ?? false
        }
        do {
            let timeoutError = NSError(
                domain: "GatewayHealthMonitor",
                code: 1,
                userInfo: [NSLocalizedDescriptionKey: "health check timed out"])
            return try await AsyncTimeout.withTimeout(
                seconds: timeout,
                onTimeout: { timeoutError },
                operation: check)
        } catch {
            return false
        }
    }
}

import Foundation
import Observation
import OpenClawKit

/// Keeps operator sessions for non-focused gateways live in the foreground.
/// The focused gateway remains owned by `NodeAppModel`, including its capability-bearing
/// node session. This fleet therefore cannot route camera, screen, or device commands.
@MainActor
@Observable
final class GatewayOperatorFleet {
    nonisolated static func backgroundStableIDs(
        connectedStableIDs: [String],
        focusedStableID: String?) -> [String]
    {
        var seen = Set<GatewayStableIdentifier.Key>()
        return connectedStableIDs.filter { stableID in
            guard !GatewayStableIdentifier.matches(stableID, focusedStableID),
                  let key = GatewayStableIdentifier.key(stableID)
            else { return false }
            return seen.insert(key).inserted
        }
    }

    enum ConnectionState: String, Sendable {
        case connecting
        case connected
        case offline
        case needsAttention
    }

    struct Status: Identifiable, Sendable, Equatable {
        let stableID: String
        var name: String
        var state: ConnectionState
        var detail: String?

        var id: String {
            self.stableID
        }
    }

    private final class Runtime {
        let id = UUID()
        let session = GatewayNodeSession()
        var config: GatewayConnectConfig
        var name: String
        var task: Task<Void, Never>?
        var isPausedForAttention = false

        init(config: GatewayConnectConfig, name: String) {
            self.config = config
            self.name = name
        }
    }

    private(set) var statuses: [Status] = []
    @ObservationIgnored private var runtimes: [GatewayStableIdentifier.Key: Runtime] = [:]

    func reconcile(
        desiredStableIDs: [String],
        configs: [(config: GatewayConnectConfig, name: String)])
    {
        let desiredKeys = Set(desiredStableIDs.compactMap(GatewayStableIdentifier.key))
        var desired: [GatewayStableIdentifier.Key: (GatewayConnectConfig, String)] = [:]
        for item in configs {
            guard let key = GatewayStableIdentifier.key(item.config.effectiveStableID),
                  desiredKeys.contains(key)
            else { continue }
            desired[key] = (item.config, item.name)
        }

        // Endpoint resolution is transient for discovered gateways. Keep a healthy runtime on
        // its last proven route until the user disables, forgets, or focuses that gateway.
        for key in self.runtimes.keys where !desiredKeys.contains(key) {
            self.stopRuntime(key: key)
        }
        for (key, item) in desired {
            if let runtime = self.runtimes[key],
               runtime.config.hasSameConnectionInputs(as: item.0),
               runtime.task != nil || runtime.isPausedForAttention
            {
                runtime.name = item.1
                self.setStatus(
                    stableID: item.0.effectiveStableID,
                    name: item.1,
                    preservingState: true)
                continue
            }
            self.stopRuntime(key: key)
            self.startRuntime(config: item.0, name: item.1, key: key)
        }
        self.sortStatuses()
    }

    func stop(stableID: String) {
        guard let key = GatewayStableIdentifier.key(stableID) else { return }
        self.stopRuntime(key: key)
    }

    func stopAll() {
        for key in Array(self.runtimes.keys) {
            self.stopRuntime(key: key)
        }
    }

    private func startRuntime(
        config: GatewayConnectConfig,
        name: String,
        key: GatewayStableIdentifier.Key)
    {
        let runtime = Runtime(config: config, name: name)
        self.runtimes[key] = runtime
        self.setStatus(
            stableID: config.effectiveStableID,
            name: name,
            state: .connecting,
            detail: nil)
        runtime.task = Task { @MainActor [weak self, weak runtime] in
            guard let self, let runtime else { return }
            await self.run(runtime: runtime, key: key)
        }
    }

    private func stopRuntime(key: GatewayStableIdentifier.Key) {
        guard let runtime = self.runtimes.removeValue(forKey: key) else { return }
        runtime.task?.cancel()
        runtime.task = nil
        self.statuses.removeAll { GatewayStableIdentifier.matches($0.stableID, runtime.config.effectiveStableID) }
        Task {
            await runtime.session.disconnect()
        }
    }

    private func run(runtime: Runtime, key: GatewayStableIdentifier.Key) async {
        var attempt = 0
        while !Task.isCancelled, self.runtimes[key]?.id == runtime.id {
            let config = runtime.config
            self.setStatus(
                stableID: config.effectiveStableID,
                name: runtime.name,
                state: attempt == 0 ? .connecting : .offline,
                detail: attempt == 0 ? nil : String(localized: "Reconnecting…"))

            let options = Self.operatorOptions(from: config.nodeOptions)
            let sessionBox = config.tls.map {
                WebSocketSessionBox(session: GatewayTLSPinningSession(params: $0))
            }
            let runtimeID = runtime.id
            do {
                try await runtime.session.connect(
                    url: config.url,
                    credentials: GatewayNodeSessionCredentials(
                        token: config.token,
                        bootstrapToken: config.bootstrapToken,
                        password: config.password),
                    connectOptions: options,
                    sessionBox: sessionBox,
                    extraHeadersProvider: {
                        GatewaySettingsStore.loadGatewayCustomHeaders(
                            gatewayStableID: config.effectiveStableID)
                    },
                    onConnected: { [weak self] in
                        await MainActor.run {
                            guard let self, let runtime = self.runtimes[key], runtime.id == runtimeID else { return }
                            self.setStatus(
                                stableID: config.effectiveStableID,
                                name: runtime.name,
                                state: .connected,
                                detail: nil)
                            _ = GatewaySettingsStore.markGatewayConnected(
                                stableID: config.effectiveStableID,
                                atMs: Int(Date().timeIntervalSince1970 * 1000))
                        }
                    },
                    onDisconnected: { [weak self] reason in
                        await MainActor.run {
                            guard let self, let runtime = self.runtimes[key], runtime.id == runtimeID else { return }
                            self.setStatus(
                                stableID: config.effectiveStableID,
                                name: runtime.name,
                                state: .offline,
                                detail: reason)
                        }
                    },
                    onInvoke: { request in
                        BridgeInvokeResponse(
                            id: request.id,
                            ok: false,
                            error: OpenClawNodeError(
                                code: .invalidRequest,
                                message: "INVALID_REQUEST: background operator sessions cannot invoke node commands"))
                    })
                attempt = 0
                try await Task.sleep(for: .seconds(1))
            } catch is CancellationError {
                break
            } catch {
                guard !Task.isCancelled, self.runtimes[key]?.id == runtime.id else { break }
                attempt += 1
                let problem = GatewayConnectionProblemMapper.map(error: error)
                let pauses = problem?.pauseReconnect == true || problem?.needsPairingApproval == true
                runtime.isPausedForAttention = pauses
                self.setStatus(
                    stableID: config.effectiveStableID,
                    name: runtime.name,
                    state: pauses ? .needsAttention : .offline,
                    detail: problem?.message ?? error.localizedDescription)
                if pauses { break }
                let delay = min(pow(2.0, Double(min(attempt, 5))), 30.0)
                try? await Task.sleep(for: .seconds(delay))
            }
        }
        if self.runtimes[key]?.id == runtime.id {
            // A paused auth failure deliberately leaves its status visible, but the
            // finished task must not make a later reconciliation look connected.
            runtime.task = nil
        }
        await runtime.session.disconnect()
    }

    private static func operatorOptions(from nodeOptions: GatewayConnectOptions) -> GatewayConnectOptions {
        GatewayConnectOptions(
            role: "operator",
            scopes: ["operator.read", "operator.write", "operator.talk.secrets"],
            caps: [OpenClawGatewayClientCapability.inlineWidgets],
            commands: [],
            permissions: [:],
            clientId: nodeOptions.clientId,
            clientMode: "ui",
            clientDisplayName: nodeOptions.clientDisplayName,
            includeDeviceIdentity: true,
            allowStoredDeviceAuth: nodeOptions.allowStoredDeviceAuth,
            deviceAuthGatewayID: nodeOptions.deviceAuthGatewayID)
    }

    private func setStatus(
        stableID: String,
        name: String,
        state: ConnectionState? = nil,
        detail: String? = nil,
        preservingState: Bool = false)
    {
        if let index = self.statuses.firstIndex(where: {
            GatewayStableIdentifier.matches($0.stableID, stableID)
        }) {
            self.statuses[index].name = name
            if !preservingState, let state {
                self.statuses[index].state = state
                self.statuses[index].detail = detail
            }
        } else {
            self.statuses.append(Status(
                stableID: stableID,
                name: name,
                state: state ?? .offline,
                detail: detail))
        }
        self.sortStatuses()
    }

    private func sortStatuses() {
        self.statuses.sort { lhs, rhs in
            if lhs.name != rhs.name { return lhs.name.localizedStandardCompare(rhs.name) == .orderedAscending }
            return GatewayStableIdentifier.sortsBefore(lhs.stableID, rhs.stableID)
        }
    }
}

#if DEBUG
extension GatewayOperatorFleet {
    func _test_pauseRuntimeForAttention(stableID: String, detail: String = "Approval required") {
        guard let key = GatewayStableIdentifier.key(stableID),
              let runtime = self.runtimes[key]
        else { return }
        runtime.task?.cancel()
        runtime.task = nil
        runtime.isPausedForAttention = true
        self.setStatus(
            stableID: runtime.config.effectiveStableID,
            name: runtime.name,
            state: .needsAttention,
            detail: detail)
    }
}
