import Foundation
import Network
import os

enum TCPProbe {
    static func probe(host: String, port: Int, timeoutSeconds: Double, queueLabel: String) async -> Bool {
        guard port >= 1, port <= 65535 else { return false }
        guard let nwPort = NWEndpoint.Port(rawValue: UInt16(port)) else { return false }

        let endpointHost = NWEndpoint.Host(host)
        let connection = NWConnection(host: endpointHost, port: nwPort, using: .tcp)

        return await withCheckedContinuation { cont in
            let queue = DispatchQueue(label: queueLabel)
            let finished = OSAllocatedUnfairLock(initialState: false)
            let finish: @Sendable (Bool) -> Void = { ok in
                let shouldResume = finished.withLock { flag -> Bool in
                    if flag { return false }
                    flag = true
                    return true
                }
                guard shouldResume else { return }
                connection.cancel()
                cont.resume(returning: ok)
            }

            connection.stateUpdateHandler = { state in
                switch state {
                case .ready:
                    finish(true)
                case .failed, .cancelled:
                    finish(false)
                default:
                    break
                }
            }

            connection.start(queue: queue)
            queue.asyncAfter(deadline: .now() + timeoutSeconds) { finish(false) }
        }
    }
}

import SwiftUI

/// OpenClaw's product opt-in for requesting read-only summaries from Apple Health.
/// Apple Health permission remains owned by the system permission sheet and Settings.
struct AppleHealthAccessSectionView: View {
    @Environment(GatewayConnectionController.self) private var gatewayController
    @Environment(\.scenePhase) private var scenePhase
    @State private var healthEnabled = HealthAuthorization.isEnabled
    @State private var healthError: String?
    @State private var isRequesting = false

    var body: some View {
        DevicePermissionRow(
            identifierPrefix: "apple-health",
            identifier: "summaries",
            symbol: "heart.text.clipboard",
            tint: .red,
            title: LocalizedStringResource("Apple Health Summaries"),
            detail: self.healthDetail,
            grant: self.healthGrant,
            isRequesting: self.isRequesting,
            actionTitle: self.healthActionTitle,
            action: HealthAuthorization.isAvailable ? { self.handleHealthAction() } : nil)
            .onAppear { self.refresh() }
            .onChange(of: self.scenePhase) { _, phase in
                if phase == .active {
                    self.refresh()
                }
            }

        if let healthError {
            Text(healthError)
                .font(OpenClawType.footnote)
                .foregroundStyle(OpenClawBrand.danger)
        }
    }

    private var healthGrant: DevicePermissionGrant {
        guard HealthAuthorization.isAvailable else { return .denied }
        // HealthKit hides read authorization; this is only OpenClaw's sharing switch.
        return self.healthEnabled ? .granted : .notRequested
    }

    private var healthDetail: LocalizedStringResource {
        if !HealthAuthorization.isAvailable {
            return LocalizedStringResource("Apple Health data is unavailable on this device.")
        }
        if self.healthEnabled {
            return LocalizedStringResource(
                """
                Reads steps, sleep, resting heart rate, and workouts from Apple Health only when a summary is \
                requested. Only the aggregate leaves this device through your Gateway to your configured AI provider; \
                raw samples stay on this device and results may remain in chat history.
                """)
        }
        return LocalizedStringResource(
            """
            Creates read-only summaries from the Apple Health app for steps, sleep, resting heart rate, and workouts. \
            Only requested summaries leave this device through your Gateway to your configured AI provider; raw \
            samples stay on this device.
            """)
    }

    private var healthActionTitle: LocalizedStringResource? {
        guard HealthAuthorization.isAvailable else { return nil }
        return self.healthEnabled
            ? LocalizedStringResource("Turn Off Summaries")
            : LocalizedStringResource("Enable Apple Health Summaries")
    }

    private func handleHealthAction() {
        if self.healthEnabled {
            HealthAuthorization.disable()
            self.healthEnabled = false
            self.healthError = nil
            self.gatewayController.refreshActiveGatewayRegistrationFromSettings()
            return
        }

        guard !self.isRequesting else { return }
        Task { @MainActor in
            self.isRequesting = true
            defer { self.isRequesting = false }
            do {
                try await HealthAuthorization.enable()
                self.healthEnabled = true
                self.healthError = nil
                self.gatewayController.refreshActiveGatewayRegistrationFromSettings()
            } catch {
                self.healthError = error.localizedDescription
            }
        }
    }

    private func refresh() {
        self.healthEnabled = HealthAuthorization.isEnabled
    }
}

import Foundation
import HealthKit
import OpenClawKit

enum HealthAuthorization {
    static let enabledKey = "health.summary.enabled"

    static var isAvailable: Bool {
        HKHealthStore.isHealthDataAvailable()
    }

    static var isEnabled: Bool {
        self.isAvailable && UserDefaults.standard.bool(forKey: self.enabledKey)
    }

    static var readTypes: Set<HKObjectType> {
        var types: Set<HKObjectType> = [HKWorkoutType.workoutType()]
        if let steps = HKObjectType.quantityType(forIdentifier: .stepCount) {
            types.insert(steps)
        }
        if let sleep = HKObjectType.categoryType(forIdentifier: .sleepAnalysis) {
            types.insert(sleep)
        }
        if let restingHeartRate = HKObjectType.quantityType(forIdentifier: .restingHeartRate) {
            types.insert(restingHeartRate)
        }
        return types
    }

    @MainActor
    static func enable() async throws {
        guard self.isAvailable else {
            throw NSError(domain: "Health", code: 1, userInfo: [
                NSLocalizedDescriptionKey: "Health data is unavailable on this device.",
            ])
        }
        try await HKHealthStore().requestAuthorization(toShare: [], read: self.readTypes)
        // HealthKit intentionally does not reveal read denial. This flag records only
        // the user's explicit OpenClaw sharing choice, never inferred authorization.
        UserDefaults.standard.set(true, forKey: self.enabledKey)
    }

    static func disable() {
        UserDefaults.standard.removeObject(forKey: self.enabledKey)
    }
}

protocol HealthSummaryServicing: Sendable {
    func summary(params: OpenClawHealthSummaryParams) async throws -> OpenClawHealthSummaryPayload
}

actor HealthSummaryService: HealthSummaryServicing {
    private let healthStore: HKHealthStore

    init(healthStore: HKHealthStore = HKHealthStore()) {
        self.healthStore = healthStore
    }

    func summary(params: OpenClawHealthSummaryParams) async throws -> OpenClawHealthSummaryPayload {
        guard HealthAuthorization.isEnabled else {
            throw NSError(domain: "Health", code: 2, userInfo: [
                NSLocalizedDescriptionKey:
                    "HEALTH_ACCESS_DISABLED: enable Apple Health Summaries in OpenClaw Settings",
            ])
        }

        let now = Date()
        let range = Self.dateRange(now: now, calendar: .current)
        let stepCount = try await self.stepCount(in: range)
        let sleepDuration = try await self.sleepDuration(in: range)
        let restingHeartRate = try await self.restingHeartRate(in: range)
        let workouts = try await self.workouts(in: range)
        let formatter = ISO8601DateFormatter()

        return OpenClawHealthSummaryPayload(
            period: params.period,
            startISO: formatter.string(from: range.start),
            endISO: formatter.string(from: range.end),
            timeZoneIdentifier: TimeZone.current.identifier,
            stepCount: stepCount,
            sleepDurationMinutes: sleepDuration.map(Self.roundedMinutes),
            restingHeartRateBpm: restingHeartRate.map { ($0 * 10).rounded() / 10 },
            workoutCount: workouts?.count,
            workoutDurationMinutes: workouts.map { Self.roundedMinutes($0.duration) })
    }

    static func dateRange(
        now: Date,
        calendar: Calendar) -> DateInterval
    {
        let startOfToday = calendar.startOfDay(for: now)
        return DateInterval(start: startOfToday, end: now)
    }

    static func mergedDuration(
        intervals: [DateInterval],
        clippedTo range: DateInterval) -> TimeInterval?
    {
        let clipped = intervals.compactMap { interval -> DateInterval? in
            let start = max(interval.start, range.start)
            let end = min(interval.end, range.end)
            return end > start ? DateInterval(start: start, end: end) : nil
        }.sorted { $0.start < $1.start }
        guard var current = clipped.first else { return nil }

        var duration: TimeInterval = 0
        for interval in clipped.dropFirst() {
            if interval.start <= current.end {
                current = DateInterval(start: current.start, end: max(current.end, interval.end))
            } else {
                duration += current.duration
                current = interval
            }
        }
        return duration + current.duration
    }

    private static func roundedMinutes(_ seconds: TimeInterval) -> Int {
        Int((seconds / 60).rounded())
    }

    private func stepCount(in range: DateInterval) async throws -> Int? {
        guard let type = HKObjectType.quantityType(forIdentifier: .stepCount) else { return nil }
        let predicate = Self.quantityPredicate(type: type, range: range)
        let statistics = try await HKStatisticsQueryDescriptor(
            predicate: predicate,
            options: .cumulativeSum).result(for: self.healthStore)
        return statistics?.sumQuantity().map { Int($0.doubleValue(for: .count()).rounded()) }
    }

    private func restingHeartRate(in range: DateInterval) async throws -> Double? {
        guard let type = HKObjectType.quantityType(forIdentifier: .restingHeartRate) else { return nil }
        let predicate = Self.quantityPredicate(type: type, range: range)
        let statistics = try await HKStatisticsQueryDescriptor(
            predicate: predicate,
            options: .discreteAverage).result(for: self.healthStore)
        let beatsPerMinute = HKUnit.count().unitDivided(by: .minute())
        return statistics?.averageQuantity()?.doubleValue(for: beatsPerMinute)
    }

    private func sleepDuration(in range: DateInterval) async throws -> TimeInterval? {
        guard let type = HKObjectType.categoryType(forIdentifier: .sleepAnalysis) else { return nil }
        let predicate = HKQuery.predicateForSamples(
            withStart: range.start,
            end: range.end,
            options: [])
        let descriptor = HKSampleQueryDescriptor(
            predicates: [.categorySample(type: type, predicate: predicate)],
            sortDescriptors: [],
            limit: nil)
        let samples = try await descriptor.result(for: self.healthStore)
        let asleepIntervals = samples.compactMap { sample -> DateInterval? in
            guard let value = HKCategoryValueSleepAnalysis(rawValue: sample.value),
                  HKCategoryValueSleepAnalysis.allAsleepValues.contains(value)
            else { return nil }
            return DateInterval(start: sample.startDate, end: sample.endDate)
        }
        // Sleep stages and sources can overlap. Merge intervals so a minute is
        // never counted twice in the aggregate sent off device.
        return Self.mergedDuration(intervals: asleepIntervals, clippedTo: range)
    }

    private func workouts(in range: DateInterval) async throws -> (count: Int, duration: TimeInterval)? {
        let predicate = HKQuery.predicateForSamples(
            withStart: range.start,
            end: range.end,
            options: .strictStartDate)
        let descriptor = HKSampleQueryDescriptor(
            predicates: [.workout(predicate)],
            sortDescriptors: [],
            limit: nil)
        let samples = try await descriptor.result(for: self.healthStore)
        guard !samples.isEmpty else { return nil }
        let duration = samples.reduce(0) { $0 + $1.duration }
        return (samples.count, duration)
    }

    private static func quantityPredicate(
        type: HKQuantityType,
        range: DateInterval) -> HKSamplePredicate<HKQuantitySample>
    {
        let predicate = HKQuery.predicateForSamples(
            withStart: range.start,
            end: range.end,
            options: [])
        return .quantitySample(type: type, predicate: predicate)
    }
}

@preconcurrency import ActivityKit
import Foundation
import os

/// Owns the single ActivityKit presentation for connection, attention, tool,
/// and voice state. Producers update independent inputs; the arbiter decides
/// which state is visible so lower-priority updates cannot hide urgent work.
@MainActor
final class LiveActivityManager {
    static let shared = LiveActivityManager()

    private struct PendingActivityUpdate {
        var state: OpenClawActivityAttributes.ContentState
        var staleDate: Date?
    }

    private struct StatusPresentation {
        let status: OpenClawActivityAttributes.ContentState.Status
        let verbatimDetail: String?
    }

    private let logger = Logger(subsystem: "ai.openclawfoundation.app", category: "LiveActivity")
    private let connectingStaleSeconds: TimeInterval = 120
    private let transientStaleSeconds: TimeInterval = 300
    private let hydrationStaleSeconds: TimeInterval = 300
    private let voiceSamplePublishDelay = Duration.milliseconds(500)
    private let voiceStaleRefreshDelay = Duration.seconds(240)
    private let toolStaleRefreshDelay = Duration.seconds(240)

    private var arbiter = LiveActivityPresentationArbiter()
    private var currentActivity: Activity<OpenClawActivityAttributes>?
    private var currentState: OpenClawActivityAttributes.ContentState?
    private var currentStaleDate: Date?
    private var pendingActivityUpdate: PendingActivityUpdate?
    private var activityUpdateTask: Task<Void, Never>?
    private var activityGeneration: UInt64 = 0
    private var voiceSampleBuffer = LiveActivityVoiceSampleBuffer()
    private var pendingVoiceSample: UInt8?
    private var voiceSampleTask: Task<Void, Never>?
    private var voiceStaleRefreshTask: Task<Void, Never>?
    private var voiceStaleRefreshGeneration: UInt64 = 0
    private var toolStaleRefreshTask: Task<Void, Never>?
    private var toolStaleRefreshGeneration: UInt64 = 0
    #if DEBUG
    private var voicePreviewActive = false
    #endif

    private init() {
        self.hydrateCurrentAndPruneDuplicates()
    }

    func showConnecting(
        statusText: String = String(localized: "Connecting..."),
        agentName: String,
        sessionKey: String)
    {
        let presentation = Self.connectingPresentation(statusText: statusText)
        let startedAt = Self.lifecycleStartedAt(
            existing: self.arbiter.connection,
            agentName: agentName,
            sessionKey: sessionKey)
        let state = OpenClawActivityAttributes.ContentState(
            status: presentation.status,
            verbatimDetail: presentation.verbatimDetail,
            startedAt: startedAt)
        self.arbiter.setConnection(self.request(
            state: state,
            staleAfter: self.connectingStaleSeconds,
            agentName: agentName,
            sessionKey: sessionKey))
        self.reconcile(reason: "connecting")
    }

    func showAttention(statusText: String, agentName: String, sessionKey: String) {
        let presentation = Self.attentionPresentation(statusText: statusText)
        let startedAt = Self.lifecycleStartedAt(
            existing: self.arbiter.attention,
            agentName: agentName,
            sessionKey: sessionKey)
        let state = OpenClawActivityAttributes.ContentState(
            status: presentation.status,
            verbatimDetail: presentation.verbatimDetail,
            startedAt: startedAt)
        self.arbiter.setAttention(self.request(
            state: state,
            staleAfter: nil,
            agentName: agentName,
            sessionKey: sessionKey))
        self.reconcile(reason: "attention")
    }

    func showTool(id: String, name: String, agentName: String, agentBadge: String, sessionKey: String) {
        let toolName = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !id.isEmpty, !toolName.isEmpty else { return }
        let state = OpenClawActivityAttributes.ContentState(
            status: .toolRunning,
            verbatimDetail: nil,
            startedAt: .now,
            agentBadge: agentBadge,
            toolName: toolName)
        self.arbiter.startTool(
            id: id,
            request: self.request(
                state: state,
                staleAfter: self.transientStaleSeconds,
                agentName: agentName,
                sessionKey: sessionKey))
        self.ensureToolStaleRefreshTask()
        self.reconcile(reason: "tool_started")
    }

    func endTool(id: String, sessionKey: String) {
        self.arbiter.endTool(id: id, sessionKey: sessionKey)
        if self.arbiter.activeToolCount == 0 {
            self.stopToolStaleRefreshTask()
        }
        self.reconcile(reason: "tool_finished")
    }

    func showVoice(
        statusText: String,
        isListening: Bool,
        isSpeaking: Bool,
        audioLevel: Double?,
        agentName: String,
        agentBadge: String,
        sessionKey: String)
    {
        let status = LiveActivityPresentationArbiter.voiceStatus(
            isListening: isListening,
            isSpeaking: isSpeaking)
        let detail = Self.voiceDetail(statusText, status: status)
        let previousVoice = self.arbiter.voice
        let hasSameOwner = Self.hasSameOwner(
            previousVoice,
            agentName: agentName,
            sessionKey: sessionKey)
        let startedAt = Self.lifecycleStartedAt(
            existing: previousVoice,
            agentName: agentName,
            sessionKey: sessionKey)
        let hasMeasuredAudio = isSpeaking || isListening
        if !hasSameOwner || Self.shouldResetVoiceSamples(previousStatus: previousVoice?.state.status) {
            self.resetVoiceSamples()
        }
        if hasMeasuredAudio, let sample = LiveActivityVoiceSampleBuffer.quantize(audioLevel) {
            self.voiceSampleBuffer.append(sample)
        }
        let state = OpenClawActivityAttributes.ContentState(
            status: status,
            verbatimDetail: detail,
            startedAt: startedAt,
            agentBadge: agentBadge,
            voiceSamples: hasMeasuredAudio ? self.voiceSampleBuffer.payload : nil)
        self.arbiter.setVoice(self.request(
            state: state,
            staleAfter: self.transientStaleSeconds,
            agentName: agentName,
            sessionKey: sessionKey))
        self.ensureVoiceStaleRefreshTask()
        self.reconcile(reason: "voice_changed")
    }

    /// Coalesces the high-rate playback meter into a bounded two-updates-per-second
    /// envelope. The widget gets real motion without building an ActivityKit queue.
    func updateVoiceLevel(_ level: Double?) {
        guard let status = arbiter.voice?.state.status,
              status == .voiceSpeaking || status == .voiceListening,
              let sample = LiveActivityVoiceSampleBuffer.quantize(level)
        else { return }
        self.pendingVoiceSample = sample
        guard self.voiceSampleTask == nil else { return }
        self.voiceSampleTask = Task { [weak self] in
            guard let self else { return }
            try? await Task.sleep(for: self.voiceSamplePublishDelay)
            guard !Task.isCancelled else { return }
            self.voiceSampleTask = nil
            self.publishPendingVoiceSample()
        }
    }

    func endVoice() {
        #if DEBUG
        guard !self.voicePreviewActive else { return }
        #endif
        self.resetVoiceSamples()
        self.stopVoiceStaleRefreshTask()
        self.arbiter.setVoice(nil)
        self.reconcile(reason: "voice_finished")
    }

    #if DEBUG
    /// Simulator-only fixture. The widget supplies its own bounded animation;
    /// ActivityKit receives a state transition rather than audio-rate updates.
    func startVoicePreview() {
        self.voicePreviewActive = true
        self.showVoice(
            statusText: "Speaking",
            isListening: false,
            isSpeaking: true,
            audioLevel: nil,
            agentName: "Aiden",
            agentBadge: "🐕",
            sessionKey: "live-activity-preview")
    }
    #endif

    func handleReconnect() {
        self.arbiter.clearConnectionState()
        self.reconcile(reason: "connected")
    }

    func endActivity(reason: String) {
        self.arbiter.clearAll()
        self.stopToolStaleRefreshTask()
        self.stopVoiceStaleRefreshTask()
        self.resetVoiceSamples()
        #if DEBUG
        self.voicePreviewActive = false
        #endif
        self.endCurrentActivity(reason: reason)
    }

    private func request(
        state: OpenClawActivityAttributes.ContentState,
        staleAfter seconds: TimeInterval?,
        agentName: String,
        sessionKey: String) -> LiveActivityPresentationRequest
    {
        LiveActivityPresentationRequest(
            state: state,
            staleDate: seconds.map { Date().addingTimeInterval($0) },
            agentName: agentName,
            sessionKey: sessionKey)
    }

    private func reconcile(reason: String) {
        guard let request = arbiter.current else {
            self.endCurrentActivity(reason: reason)
            return
        }

        if let activity = currentActivity,
           activity.activityState == .active,
           activity.attributes.agentName != request.agentName ||
           activity.attributes.sessionKey != request.sessionKey
        {
            self.endCurrentActivity(reason: "context_changed")
            self.startActivity(request)
            return
        }

        if let activity = currentActivity, activity.activityState == .active {
            self.enqueueLatestUpdate(
                activity: activity,
                state: request.state,
                staleDate: request.staleDate)
            return
        }

        if let activity = currentActivity {
            // An inactive activity can still have a suspended update worker. Retire
            // that generation before replacing it or the new activity never starts one.
            self.activityGeneration &+= 1
            self.activityUpdateTask?.cancel()
            self.activityUpdateTask = nil
            self.pendingActivityUpdate = nil
            self.end(activity: activity)
            self.currentActivity = nil
            self.currentState = nil
            self.currentStaleDate = nil
        }
        self.startActivity(request)
    }

    private func publishPendingVoiceSample() {
        guard let sample = pendingVoiceSample,
              var request = arbiter.voice,
              request.state.status == .voiceSpeaking || request.state.status == .voiceListening
        else {
            self.pendingVoiceSample = nil
            return
        }
        self.pendingVoiceSample = nil
        self.voiceSampleBuffer.append(sample)
        request.state.voiceSamples = self.voiceSampleBuffer.payload
        request.staleDate = Date().addingTimeInterval(self.transientStaleSeconds)
        self.arbiter.setVoice(request)
        self.reconcile(reason: "voice_level")
    }

    private func resetVoiceSamples() {
        self.voiceSampleTask?.cancel()
        self.voiceSampleTask = nil
        self.pendingVoiceSample = nil
        self.voiceSampleBuffer.reset()
    }

    /// Active tool calls refresh their bounded deadline while this process owns
    /// them. Suspension or termination stops the heartbeat so stale work pauses.
    private func ensureToolStaleRefreshTask() {
        guard self.toolStaleRefreshTask == nil, self.arbiter.activeToolCount > 0 else { return }
        self.toolStaleRefreshGeneration &+= 1
        let generation = self.toolStaleRefreshGeneration
        self.toolStaleRefreshTask = Task { [weak self] in
            while !Task.isCancelled {
                guard let self else { return }
                try? await Task.sleep(for: self.toolStaleRefreshDelay)
                guard !Task.isCancelled,
                      generation == self.toolStaleRefreshGeneration,
                      self.arbiter.activeToolCount > 0
                else { break }
                self.arbiter.refreshTools(
                    staleDate: Date().addingTimeInterval(self.transientStaleSeconds))
                self.reconcile(reason: "tool_heartbeat")
            }
            guard let self, generation == self.toolStaleRefreshGeneration else { return }
            self.toolStaleRefreshTask = nil
        }
    }

    private func stopToolStaleRefreshTask() {
        self.toolStaleRefreshGeneration &+= 1
        self.toolStaleRefreshTask?.cancel()
        self.toolStaleRefreshTask = nil
    }

    private func ensureVoiceStaleRefreshTask() {
        guard self.voiceStaleRefreshTask == nil, self.arbiter.voice != nil else { return }
        self.voiceStaleRefreshGeneration &+= 1
        let generation = self.voiceStaleRefreshGeneration
        self.voiceStaleRefreshTask = Task { [weak self] in
            while !Task.isCancelled {
                guard let self else { return }
                try? await Task.sleep(for: self.voiceStaleRefreshDelay)
                guard !Task.isCancelled,
                      generation == self.voiceStaleRefreshGeneration,
                      self.arbiter.voice != nil
                else { break }
                self.arbiter.refreshVoice(
                    staleDate: Date().addingTimeInterval(self.transientStaleSeconds))
                self.reconcile(reason: "voice_heartbeat")
            }
            guard let self, generation == self.voiceStaleRefreshGeneration else { return }
            self.voiceStaleRefreshTask = nil
        }
    }

    private func stopVoiceStaleRefreshTask() {
        self.voiceStaleRefreshGeneration &+= 1
        self.voiceStaleRefreshTask?.cancel()
        self.voiceStaleRefreshTask = nil
    }

    private func startActivity(_ request: LiveActivityPresentationRequest) {
        guard ActivityAuthorizationInfo().areActivitiesEnabled else {
            self.logger.info("Live Activities disabled; skipping start")
            return
        }

        do {
            let activity = try Activity.request(
                attributes: OpenClawActivityAttributes(
                    agentName: request.agentName,
                    sessionKey: request.sessionKey),
                content: ActivityContent(state: request.state, staleDate: request.staleDate),
                pushType: nil)
            self.activityGeneration &+= 1
            self.currentActivity = activity
            self.currentState = request.state
            self.currentStaleDate = request.staleDate
            self.logger.info("started live activity id=\(activity.id, privacy: .public)")
        } catch {
            self.logger.error("failed to start live activity: \(error.localizedDescription, privacy: .public)")
        }
    }

    /// Keeps at most one ActivityKit update in flight and one replaceable next
    /// value. Slow or throttled ActivityKit writes cannot build an obsolete queue.
    private func enqueueLatestUpdate(
        activity: Activity<OpenClawActivityAttributes>,
        state: OpenClawActivityAttributes.ContentState,
        staleDate: Date?)
    {
        guard state != self.currentState || staleDate != self.currentStaleDate else { return }
        self.currentState = state
        self.currentStaleDate = staleDate
        self.pendingActivityUpdate = PendingActivityUpdate(state: state, staleDate: staleDate)
        guard self.activityUpdateTask == nil else { return }
        self.startUpdateWorker(activity: activity, generation: self.activityGeneration)
    }

    private func startUpdateWorker(activity: Activity<OpenClawActivityAttributes>, generation: UInt64) {
        self.activityUpdateTask = Task { [weak self] in
            while !Task.isCancelled {
                guard let self,
                      generation == self.activityGeneration,
                      self.currentActivity?.id == activity.id,
                      let pending = self.pendingActivityUpdate
                else { break }
                self.pendingActivityUpdate = nil
                await activity.update(ActivityContent(state: pending.state, staleDate: pending.staleDate))
            }

            guard let self, generation == self.activityGeneration else { return }
            self.activityUpdateTask = nil
            if self.pendingActivityUpdate != nil,
               self.currentActivity?.id == activity.id
            {
                self.startUpdateWorker(activity: activity, generation: generation)
            }
        }
    }

    private func endCurrentActivity(reason: String) {
        guard let activity = currentActivity else { return }
        let startedAt = self.currentState?.startedAt ?? .now
        self.activityGeneration &+= 1
        self.activityUpdateTask?.cancel()
        self.activityUpdateTask = nil
        self.pendingActivityUpdate = nil
        self.currentActivity = nil
        self.currentState = nil
        self.currentStaleDate = nil
        self.logger.info("ending live activity reason=\(reason, privacy: .public)")
        let finalState = OpenClawActivityAttributes.ContentState(
            status: .disconnected,
            verbatimDetail: nil,
            startedAt: startedAt)
        Task {
            await activity.end(
                ActivityContent(state: finalState, staleDate: nil),
                dismissalPolicy: .immediate)
        }
    }

    private func hydrateCurrentAndPruneDuplicates() {
        let active = Activity<OpenClawActivityAttributes>.activities
        guard !active.isEmpty else { return }

        let now = Date()
        let candidates = active.filter { activity in
            let state = activity.content.state
            guard activity.activityState == .active else { return false }
            return Self.shouldHydrate(
                status: state.status,
                startedAt: state.startedAt,
                staleDate: activity.content.staleDate,
                now: now,
                maximumStartAge: self.hydrationStaleSeconds)
        }

        guard let keeper = candidates.max(by: {
            $0.content.state.startedAt < $1.content.state.startedAt
        }) else {
            for activity in active {
                self.end(activity: activity)
            }
            return
        }

        self.activityGeneration &+= 1
        self.currentActivity = keeper
        self.currentState = keeper.content.state
        self.currentStaleDate = keeper.content.staleDate
        var request = LiveActivityPresentationRequest(
            state: keeper.content.state,
            staleDate: keeper.content.staleDate,
            agentName: keeper.attributes.agentName,
            sessionKey: keeper.attributes.sessionKey)
        switch keeper.content.state.status {
        case .approvalNeeded, .actionRequired, .attention:
            self.arbiter.setAttention(request)
        case .voiceActive, .voiceListening, .voiceSpeaking:
            self.arbiter.setVoice(request)
        case .toolRunning:
            // A hydrated tool has no invocation ID to balance. Keep it as the
            // lowest-priority fallback until a live producer replaces it.
            request.staleDate = Date().addingTimeInterval(self.transientStaleSeconds)
            self.arbiter.adoptInitialHydratedToolFallback(request)
        case .connecting, .reconnecting, .paused:
            self.arbiter.setConnection(request)
        case .idle, .disconnected:
            break
        }
        for activity in active where activity.id != keeper.id {
            self.end(activity: activity)
        }
        // Hydrated tool fallbacks renew their bounded lifetime above. Reconcile
        // that request so ActivityKit receives the renewed stale date too.
        self.reconcile(reason: "hydrate")
    }

    /// Voice and tool activities renew `staleDate` while their producer is
    /// alive. Their original start time can therefore be old without making a
    /// heartbeat-refreshed presentation obsolete after process relaunch.
    nonisolated static func shouldHydrate(
        status: OpenClawActivityAttributes.ContentState.Status,
        startedAt: Date,
        staleDate: Date?,
        now: Date,
        maximumStartAge: TimeInterval = 300) -> Bool
    {
        guard status != .idle, status != .disconnected else { return false }
        if let staleDate, staleDate <= now {
            return false
        }
        switch status {
        case .approvalNeeded, .actionRequired, .attention:
            return true
        case .voiceActive, .voiceListening, .voiceSpeaking, .toolRunning:
            return staleDate != nil || now.timeIntervalSince(startedAt) < maximumStartAge
        case .connecting, .reconnecting, .paused:
            return now.timeIntervalSince(startedAt) < maximumStartAge
        case .idle, .disconnected:
            return false
        }
    }

    /// A live voice producer owns the waveform buffer. Phase changes preserve
    /// its recent envelope; only a newly adopted producer starts a new trace.
    nonisolated static func shouldResetVoiceSamples(
        previousStatus: OpenClawActivityAttributes.ContentState.Status?) -> Bool
    {
        previousStatus == nil
    }

    nonisolated static func hasSameOwner(
        _ existing: LiveActivityPresentationRequest?,
        agentName: String,
        sessionKey: String) -> Bool
    {
        existing?.agentName == agentName && existing?.sessionKey == sessionKey
    }

    nonisolated static func lifecycleStartedAt(
        existing: LiveActivityPresentationRequest?,
        agentName: String,
        sessionKey: String,
        now: Date = .now) -> Date
    {
        guard self.hasSameOwner(existing, agentName: agentName, sessionKey: sessionKey) else {
            return now
        }
        return existing?.state.startedAt ?? now
    }

    private func end(activity: Activity<OpenClawActivityAttributes>) {
        let startedAt = activity.content.state.startedAt
        Task {
            await activity.end(
                ActivityContent(
                    state: OpenClawActivityAttributes.ContentState(
                        status: .disconnected,
                        verbatimDetail: nil,
                        startedAt: startedAt),
                    staleDate: nil),
                dismissalPolicy: .immediate)
        }
    }

    /// Existing callers still pass rendered app copy. Collapse known values here so
    /// ActivityKit persists semantics; only unknown external detail remains verbatim.
    private static func connectingPresentation(statusText: String) -> StatusPresentation {
        if statusText == String(localized: "Connecting...") || statusText == "Connecting..." {
            return StatusPresentation(status: .connecting, verbatimDetail: nil)
        }
        if statusText == String(localized: "Reconnecting...") || statusText == "Reconnecting..." {
            return StatusPresentation(status: .reconnecting, verbatimDetail: nil)
        }
        return StatusPresentation(status: .connecting, verbatimDetail: self.normalizedDetail(statusText))
    }

    private static func attentionPresentation(statusText: String) -> StatusPresentation {
        if statusText == String(localized: "Approval needed") || statusText == "Approval needed" {
            return StatusPresentation(status: .approvalNeeded, verbatimDetail: nil)
        }
        if statusText == String(localized: "Action required") || statusText == "Action required" {
            return StatusPresentation(status: .actionRequired, verbatimDetail: nil)
        }
        return StatusPresentation(status: .attention, verbatimDetail: self.normalizedDetail(statusText))
    }

    private static func normalizedDetail(_ value: String) -> String? {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    private static func voiceDetail(
        _ value: String,
        status: OpenClawActivityAttributes.ContentState.Status) -> String?
    {
        let knownLabels: [String] = switch status {
        case .voiceListening:
            [
                String(localized: "Listening"),
                String(localized: "Listening (PTT)"),
                String(localized: "Listening (Realtime)"),
            ]
        case .voiceSpeaking:
            [
                String(localized: "Speaking…"),
                String(localized: "Speaking (System)…"),
                String(localized: "Generating voice…"),
            ]
        case .voiceActive:
            [String(localized: "Ready")]
        default:
            []
        }
        if knownLabels.contains(value) {
            return nil
        }
        return self.normalizedDetail(value)
    }
}

import Foundation

struct LiveActivityPresentationRequest: Equatable {
    var state: OpenClawActivityAttributes.ContentState
    var staleDate: Date?
    var agentName: String
    var sessionKey: String
}

struct LiveActivityVoiceSampleBuffer {
    private(set) var values: [UInt8] = []
    let capacity: Int

    init(capacity: Int = 24) {
        self.capacity = max(capacity, 1)
    }

    var payload: [UInt8]? {
        self.values.isEmpty ? nil : self.values
    }

    static func quantize(_ level: Double?) -> UInt8? {
        guard let level, level.isFinite else { return nil }
        let clamped = min(max(level, 0), 1)
        return UInt8((clamped * 255).rounded())
    }

    mutating func append(_ sample: UInt8) {
        self.values.append(sample)
        if self.values.count > self.capacity {
            self.values.removeFirst(self.values.count - self.capacity)
        }
    }

    mutating func reset() {
        self.values.removeAll(keepingCapacity: true)
    }
}

/// Keeps independent producers from overwriting higher-priority Live Activity
/// state. ActivityKit receives one reconciled presentation instead of competing
/// connection, tool, and voice writes.
struct LiveActivityPresentationArbiter {
    private struct ToolIdentity: Hashable {
        let sessionKey: String
        let id: String
    }

    private(set) var connection: LiveActivityPresentationRequest?
    private(set) var attention: LiveActivityPresentationRequest?
    private(set) var voice: LiveActivityPresentationRequest?
    private(set) var hydratedToolFallback: LiveActivityPresentationRequest?
    private var toolsByIdentity: [ToolIdentity: LiveActivityPresentationRequest] = [:]
    private var toolOrder: [ToolIdentity] = []

    var current: LiveActivityPresentationRequest? {
        if let attention {
            return attention
        }
        if let toolIdentity = toolOrder.last,
           let tool = toolsByIdentity[toolIdentity]
        {
            return tool
        }
        return self.voice ?? self.connection ?? self.hydratedToolFallback
    }

    var activeToolCount: Int {
        self.toolsByIdentity.count
    }

    static func voiceStatus(
        isListening: Bool,
        isSpeaking: Bool) -> OpenClawActivityAttributes.ContentState.Status
    {
        if isSpeaking {
            return .voiceSpeaking
        }
        if isListening {
            return .voiceListening
        }
        return .voiceActive
    }

    mutating func setConnection(_ request: LiveActivityPresentationRequest?) {
        if request != nil {
            self.hydratedToolFallback = nil
        }
        self.connection = request
    }

    mutating func setAttention(_ request: LiveActivityPresentationRequest?) {
        self.attention = request
    }

    mutating func setVoice(_ request: LiveActivityPresentationRequest?) {
        if request != nil {
            self.hydratedToolFallback = nil
        }
        self.voice = request
    }

    /// Called only by synchronous process-start hydration before the manager
    /// escapes its initializer. Live producers consume this one-time fallback.
    mutating func adoptInitialHydratedToolFallback(_ request: LiveActivityPresentationRequest?) {
        self.hydratedToolFallback = request
    }

    mutating func refreshVoice(staleDate: Date) {
        self.voice?.staleDate = staleDate
    }

    mutating func startTool(id: String, request: LiveActivityPresentationRequest) {
        guard !id.isEmpty else { return }
        self.hydratedToolFallback = nil
        let identity = ToolIdentity(sessionKey: request.sessionKey, id: id)
        if self.toolsByIdentity[identity] == nil {
            self.toolOrder.append(identity)
        }
        self.toolsByIdentity[identity] = request
    }

    mutating func endTool(id: String, sessionKey: String) {
        self.hydratedToolFallback = nil
        let identity = ToolIdentity(sessionKey: sessionKey, id: id)
        self.toolsByIdentity[identity] = nil
        self.toolOrder.removeAll { $0 == identity }
    }

    mutating func refreshTools(staleDate: Date) {
        for identity in self.toolsByIdentity.keys {
            self.toolsByIdentity[identity]?.staleDate = staleDate
        }
    }

    mutating func clearConnectionState() {
        self.connection = nil
        self.attention = nil
        self.hydratedToolFallback = nil
    }

    mutating func clearAll() {
        self.connection = nil
        self.attention = nil
        self.voice = nil
        self.hydratedToolFallback = nil
        self.toolsByIdentity.removeAll(keepingCapacity: true)
        self.toolOrder.removeAll(keepingCapacity: true)
    }
}

import ActivityKit
import Foundation

/// Shared schema used by iOS app + Live Activity widget extension.
struct OpenClawActivityAttributes: ActivityAttributes {
    var agentName: String
    var sessionKey: String

    struct ContentState: Codable, Hashable {
        enum Status: String, CaseIterable, Codable, Hashable {
            case connecting
            case reconnecting
            case approvalNeeded
            case actionRequired
            case attention
            case toolRunning
            case voiceListening
            case voiceSpeaking
            case voiceActive
            case paused
            case idle
            case disconnected
        }

        var status: Status
        var verbatimDetail: String?
        var startedAt: Date
        var agentBadge: String?
        var toolName: String?
        /// Recent playback-envelope samples, oldest first, quantized from 0...1.
        /// Live Activity updates carry the real audible signal across the app/widget boundary.
        var voiceSamples: [UInt8]?

        private enum CodingKeys: String, CodingKey {
            case status
            case verbatimDetail
            case startedAt
            case agentBadge
            case toolName
            case voiceSamples
        }

        private enum LegacyCodingKeys: String, CodingKey {
            case statusText
            case isIdle
            case isDisconnected
            case isConnecting
        }

        init(
            status: Status,
            verbatimDetail: String?,
            startedAt: Date,
            agentBadge: String? = nil,
            toolName: String? = nil,
            voiceSamples: [UInt8]? = nil)
        {
            self.status = status
            self.verbatimDetail = verbatimDetail
            self.startedAt = startedAt
            self.agentBadge = agentBadge
            self.toolName = toolName
            self.voiceSamples = voiceSamples
        }

        init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            self.startedAt = try container.decode(Date.self, forKey: .startedAt)

            if let status = try container.decodeIfPresent(Status.self, forKey: .status) {
                self.status = status
                self.verbatimDetail = try container.decodeIfPresent(String.self, forKey: .verbatimDetail)
                self.agentBadge = try container.decodeIfPresent(String.self, forKey: .agentBadge)
                self.toolName = try container.decodeIfPresent(String.self, forKey: .toolName)
                self.voiceSamples = try container.decodeIfPresent([UInt8].self, forKey: .voiceSamples)
                return
            }

            // Live Activities can outlive an app update. Decode the shipped boolean
            // schema once, then all new writes use the semantic status shape.
            let legacy = try decoder.container(keyedBy: LegacyCodingKeys.self)
            let statusText = try legacy.decodeIfPresent(String.self, forKey: .statusText)
            let presentation = try Self.legacyPresentation(
                statusText: statusText,
                isIdle: legacy.decodeIfPresent(Bool.self, forKey: .isIdle) ?? false,
                isDisconnected: legacy.decodeIfPresent(Bool.self, forKey: .isDisconnected) ?? false,
                isConnecting: legacy.decodeIfPresent(Bool.self, forKey: .isConnecting) ?? false)
            status = presentation.status
            self.verbatimDetail = presentation.verbatimDetail
            self.agentBadge = nil
            self.toolName = nil
            self.voiceSamples = nil
        }

        func encode(to encoder: Encoder) throws {
            var container = encoder.container(keyedBy: CodingKeys.self)
            try container.encode(self.status, forKey: .status)
            try container.encodeIfPresent(self.verbatimDetail, forKey: .verbatimDetail)
            try container.encode(self.startedAt, forKey: .startedAt)
            try container.encodeIfPresent(self.agentBadge, forKey: .agentBadge)
            try container.encodeIfPresent(self.toolName, forKey: .toolName)
            try container.encodeIfPresent(self.voiceSamples, forKey: .voiceSamples)
        }

        private static func legacyPresentation(
            statusText: String?,
            isIdle: Bool,
            isDisconnected: Bool,
            isConnecting: Bool) -> (status: Status, verbatimDetail: String?)
        {
            if isDisconnected {
                return (.disconnected, nil)
            }
            if isIdle {
                return (.idle, nil)
            }

            let trimmed = statusText?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            let detail = trimmed.isEmpty ? nil : trimmed
            if isConnecting {
                if let detail, Self.matchesShippedTranslation(detail, key: "Reconnecting...") {
                    return (.reconnecting, nil)
                }
                if let detail, Self.matchesShippedTranslation(detail, key: "Connecting...") {
                    return (.connecting, nil)
                }
                return (.connecting, detail)
            }
            if let detail, Self.matchesShippedTranslation(detail, key: "Approval needed") {
                return (.approvalNeeded, nil)
            }
            if let detail, Self.matchesShippedTranslation(detail, key: "Action required") {
                return (.actionRequired, nil)
            }
            return (.attention, detail)
        }

        private static func matchesShippedTranslation(_ value: String, key: String) -> Bool {
            if value == key {
                return true
            }
            return Bundle.main.localizations.contains { localization in
                guard let path = Bundle.main.path(forResource: localization, ofType: "lproj"),
                      let bundle = Bundle(path: path)
                else {
                    return false
                }
                return bundle.localizedString(forKey: key, value: key, table: nil) == value
            }
        }
    }
}

import Observation

/// Keeps Talk's ActivityKit presentation alive independently of whichever app
/// surface is mounted. Chat, Control, and iPad can all start Talk, so no view
/// may own this lifecycle.
@MainActor
final class VoiceLiveActivityCoordinator {
    private weak var appModel: NodeAppModel?

    func start(appModel: NodeAppModel) {
        guard self.appModel == nil else { return }
        self.appModel = appModel
        self.syncPresentation()
        self.observePresentationState()
        self.observeAudioLevel()
    }

    private func observePresentationState() {
        guard let appModel else { return }
        withObservationTracking {
            _ = appModel.talkMode.isEnabled
            _ = appModel.talkMode.statusText
            _ = appModel.talkMode.isSpeaking
            _ = appModel.talkMode.isListening
            _ = appModel.chatSessionKey
            _ = appModel.chatAgentName
            _ = appModel.chatAgentAvatarText
        } onChange: { [weak self] in
            Task { @MainActor in
                guard let self else { return }
                self.syncPresentation()
                self.observePresentationState()
            }
        }
    }

    private func observeAudioLevel() {
        guard let appModel else { return }
        withObservationTracking {
            _ = appModel.talkMode.isSpeaking
            _ = appModel.talkMode.isListening
            _ = appModel.talkMode.playbackLevel
            _ = appModel.talkMode.micLevel
        } onChange: { [weak self] in
            Task { @MainActor in
                guard let self else { return }
                self.syncAudioLevel()
                self.observeAudioLevel()
            }
        }
    }

    private func syncPresentation() {
        guard let appModel else { return }
        guard appModel.talkMode.isEnabled else {
            LiveActivityManager.shared.endVoice()
            return
        }
        LiveActivityManager.shared.showVoice(
            statusText: appModel.talkMode.statusText,
            isListening: appModel.talkMode.isListening,
            isSpeaking: appModel.talkMode.isSpeaking,
            audioLevel: Self.currentAudioLevel(appModel: appModel),
            agentName: appModel.chatAgentName,
            agentBadge: AgentIdentityPresentation.badge(
                avatarText: appModel.chatAgentAvatarText,
                displayName: appModel.chatAgentName),
            sessionKey: appModel.chatSessionKey)
    }

    private func syncAudioLevel() {
        guard let appModel else { return }
        LiveActivityManager.shared.updateVoiceLevel(Self.currentAudioLevel(appModel: appModel))
    }

    private static func currentAudioLevel(appModel: NodeAppModel) -> Double? {
        if appModel.talkMode.isSpeaking {
            return appModel.talkMode.playbackLevel
        }
        if appModel.talkMode.isListening {
            return appModel.talkMode.micLevel
        }
        return nil
    }
}

import CoreLocation
import Foundation
import OpenClawKit
import UIKit

@MainActor
final class LocationService: NSObject, CLLocationManagerDelegate, ConcurrentLocationServiceCommon {
    enum Error: Swift.Error {
        case timeout
        case unavailable
    }

    private let manager = CLLocationManager()
    private var authWaitID: UUID?
    private var authWaitRequiresDeterminedStatus = false
    private var authContinuation: CheckedContinuation<CLAuthorizationStatus, Never>?
    private var locationContinuation: CheckedContinuation<CLLocation, Swift.Error>?
    var locationRequestContinuations: [UUID: CheckedContinuation<CLLocation, Swift.Error>] = [:]
    private var cachedAuthorizationSnapshot = LocationAuthorizationSnapshot.undetermined
    private var authorizationChangeHandler: (@MainActor @Sendable (LocationAuthorizationSnapshot) -> Void)?
    private var significantLocationCallback: (@Sendable (CLLocation) -> Void)?
    private var isMonitoringSignificantChanges = false

    var locationManager: CLLocationManager {
        self.manager
    }

    /// Compatibility witness for the shipped single-waiter protocol; app calls use the
    /// concurrent extension and its per-request continuation dictionary.
    var locationRequestContinuation: CheckedContinuation<CLLocation, Swift.Error>? {
        get { self.locationContinuation }
        set { self.locationContinuation = newValue }
    }

    override init() {
        super.init()
        self.configureLocationManager()
    }

    func authorizationStatus() -> CLAuthorizationStatus {
        self.cachedAuthorizationSnapshot.authorizationStatus
    }

    func accuracyAuthorization() -> CLAccuracyAuthorization {
        self.cachedAuthorizationSnapshot.accuracyAuthorization
    }

    func authorizationSnapshot() -> LocationAuthorizationSnapshot {
        self.cachedAuthorizationSnapshot
    }

    func ensureAuthorization(mode: OpenClawLocationMode) async -> CLAuthorizationStatus {
        guard CLLocationManager.locationServicesEnabled() else { return .denied }

        let status = self.authorizationStatus()
        if status == .notDetermined {
            let updated = await self.requestAuthorization(requiresDeterminedStatus: true) {
                self.manager.requestWhenInUseAuthorization()
            }
            if mode != .always { return updated }
        }

        if mode == .always {
            let current = self.authorizationStatus()
            if current == .authorizedWhenInUse {
                return await self.requestAuthorization(requiresDeterminedStatus: false) {
                    self.manager.requestAlwaysAuthorization()
                }
            }
            return current
        }

        return self.authorizationStatus()
    }

    func currentLocation(
        params: OpenClawLocationGetParams,
        desiredAccuracy: OpenClawLocationAccuracy,
        maxAgeMs: Int?,
        timeoutMs: Int?) async throws -> CLLocation
    {
        _ = params
        return try await LocationCurrentRequest.resolve(
            manager: self.manager,
            desiredAccuracy: desiredAccuracy,
            maxAgeMs: maxAgeMs,
            timeoutMs: timeoutMs,
            request: { try await self.requestLocationOnce() },
            withTimeout: { timeoutMs, operation in
                try await self.withTimeout(timeoutMs: timeoutMs, operation: operation)
            })
    }

    private func requestAuthorization(
        requiresDeterminedStatus: Bool,
        request: () -> Void) async -> CLAuthorizationStatus
    {
        await withCheckedContinuation { cont in
            let waitID = UUID()
            self.authWaitID = waitID
            self.authWaitRequiresDeterminedStatus = requiresDeterminedStatus
            self.authContinuation = cont
            // Install the waiter before requesting permission so a fast delegate callback cannot be lost.
            request()
            Task { @MainActor in
                let clock = ContinuousClock()
                let noPromptDeadline = clock.now.advanced(by: .milliseconds(1500))
                var activeUndeterminedDeadline: ContinuousClock.Instant?
                var observedPrompt = UIApplication.shared.applicationState != .active
                // A slow system prompt must not trigger the no-callback fallback. Once iOS makes
                // the app inactive, wait until the user dismisses the prompt and the app returns.
                while self.authWaitID == waitID, self.authContinuation != nil {
                    try? await Task.sleep(for: .milliseconds(100))
                    let applicationIsActive = UIApplication.shared.applicationState == .active
                    if !applicationIsActive {
                        observedPrompt = true
                        activeUndeterminedDeadline = nil
                        continue
                    }
                    guard observedPrompt || clock.now >= noPromptDeadline else { continue }
                    let status = self.authorizationStatus()
                    if Self.shouldCompleteAuthorizationWait(
                        status: status,
                        requiresDeterminedStatus: requiresDeterminedStatus)
                    {
                        self.finishAuthorizationWait(waitID: waitID, status: status)
                        continue
                    }
                    if observedPrompt, activeUndeterminedDeadline == nil {
                        activeUndeterminedDeadline = clock.now.advanced(by: .milliseconds(1500))
                    }
                    let fallbackDeadline = activeUndeterminedDeadline ?? noPromptDeadline
                    guard clock.now >= fallbackDeadline else { continue }
                    self.finishAuthorizationWait(
                        waitID: waitID,
                        status: status,
                        allowUndeterminedFallback: true)
                }
            }
        }
    }

    nonisolated static func shouldCompleteAuthorizationWait(
        status: CLAuthorizationStatus,
        requiresDeterminedStatus: Bool,
        allowUndeterminedFallback: Bool = false) -> Bool
    {
        allowUndeterminedFallback || !requiresDeterminedStatus || status != .notDetermined
    }

    private func finishAuthorizationWait(
        waitID: UUID,
        status: CLAuthorizationStatus,
        allowUndeterminedFallback: Bool = false)
    {
        guard self.authWaitID == waitID, let cont = self.authContinuation else { return }
        guard Self.shouldCompleteAuthorizationWait(
            status: status,
            requiresDeterminedStatus: self.authWaitRequiresDeterminedStatus,
            allowUndeterminedFallback: allowUndeterminedFallback)
        else { return }
        self.authWaitID = nil
        self.authWaitRequiresDeterminedStatus = false
        self.authContinuation = nil
        cont.resume(returning: status)
    }

    private func withTimeout<T: Sendable>(
        timeoutMs: Int,
        operation: @escaping @Sendable () async throws -> T) async throws -> T
    {
        try await AsyncTimeout.withTimeoutMs(timeoutMs: timeoutMs, onTimeout: { Error.timeout }, operation: operation)
    }

    func startMonitoringSignificantLocationChanges(onUpdate: @escaping @Sendable (CLLocation) -> Void) {
        self.significantLocationCallback = onUpdate
        guard !self.isMonitoringSignificantChanges else { return }
        self.isMonitoringSignificantChanges = true
        self.manager.startMonitoringSignificantLocationChanges()
    }

    func setBackgroundLocationUpdatesEnabled(_ enabled: Bool) {
        self.manager.allowsBackgroundLocationUpdates = enabled
    }

    func setAuthorizationChangeHandler(
        _ handler: @escaping @MainActor @Sendable (LocationAuthorizationSnapshot) -> Void)
    {
        self.authorizationChangeHandler = handler
    }

    func stopMonitoringSignificantLocationChanges() {
        self.significantLocationCallback = nil
        self.isMonitoringSignificantChanges = false
        self.manager.stopMonitoringSignificantLocationChanges()
    }

    nonisolated func locationManagerDidChangeAuthorization(_ manager: CLLocationManager) {
        // Apple guarantees this callback for the initial state and every authorization
        // change. Cache both values here so UI construction never performs synchronous XPC.
        let snapshot = LocationAuthorizationSnapshot(
            authorizationStatus: manager.authorizationStatus,
            accuracyAuthorization: manager.accuracyAuthorization)
        Task { @MainActor in
            self.cachedAuthorizationSnapshot = snapshot
            self.authorizationChangeHandler?(snapshot)
            guard let waitID = self.authWaitID else { return }
            self.finishAuthorizationWait(waitID: waitID, status: snapshot.authorizationStatus)
        }
    }

    nonisolated func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
        let locs = locations
        Task { @MainActor in
            // Resolve all one-shot requests first so overlapping callers share this update.
            let continuations = Array(self.locationRequestContinuations.values) + [self.locationContinuation]
                .compactMap(\.self)
            self.locationRequestContinuations.removeAll()
            self.locationContinuation = nil
            for continuation in continuations {
                if let latest = locs.last {
                    continuation.resume(returning: latest)
                } else {
                    continuation.resume(throwing: Error.unavailable)
                }
            }
            // Don't return — also forward to significant-change consumers below.
            if let callback = self.significantLocationCallback, let latest = locs.last {
                callback(latest)
            }
        }
    }

    nonisolated func locationManager(_ manager: CLLocationManager, didFailWithError error: Swift.Error) {
        let err = error
        Task { @MainActor in
            let continuations = Array(self.locationRequestContinuations.values) + [self.locationContinuation]
                .compactMap(\.self)
            self.locationRequestContinuations.removeAll()
            self.locationContinuation = nil
            for continuation in continuations {
                continuation.resume(throwing: err)
            }
        }
    }
}

import CoreLocation
import Foundation
import OpenClawKit

enum LocationSettingsAction: Equatable {
    case setMode(OpenClawLocationMode)
    case openAppSettings(OpenClawLocationMode)
}

struct LocationSettingsPresentation: Equatable {
    var selectedMode: OpenClawLocationMode
    var summary: LocationPermissionSummary

    var sharingControlIsOn: Bool {
        self.selectedMode != .off
    }

    var showsAccessLevel: Bool {
        self.selectedMode != .off
    }

    var accessLevelText: String? {
        self.selectedMode.locationAccessLevelText
    }

    var statusText: String? {
        guard self.selectedMode != .off else { return nil }
        guard self.summary.needsAttention else { return nil }

        if !self.summary.locationServicesEnabled {
            return String(localized: "Location Services are off in iOS Settings.")
        }

        switch self.summary.authorizationStatus {
        case .notDetermined:
            return String(localized: "iOS permission is required to share location.")
        case .denied:
            return String(localized: "Location permission is denied in iOS Settings.")
        case .restricted:
            return String(localized: "Location permission is restricted on this device.")
        case .authorizedWhenInUse where self.selectedMode == .always:
            return String(localized: "iOS currently allows location only while using the app.")
        case .authorizedWhenInUse, .authorizedAlways:
            return nil
        default:
            return String(localized: "OpenClaw cannot determine the current iOS location permission.")
        }
    }

    func toggleAction(defaultEnabledMode: OpenClawLocationMode = .whileUsing) -> LocationSettingsAction {
        if self.sharingControlIsOn {
            return .setMode(.off)
        }
        let mode = self.selectedMode == .off ? defaultEnabledMode : self.selectedMode
        return self.enableAction(mode: mode)
    }

    func accessLevelAction(mode: OpenClawLocationMode) -> LocationSettingsAction {
        self.enableAction(mode: mode)
    }

    private func enableAction(mode: OpenClawLocationMode) -> LocationSettingsAction {
        if !self.summary.locationServicesEnabled {
            return .openAppSettings(mode)
        }

        switch self.summary.authorizationStatus {
        case .denied, .restricted:
            return .openAppSettings(mode)
        default:
            return .setMode(mode)
        }
    }
}

extension OpenClawLocationMode {
    var locationAccessLevelText: String? {
        switch self {
        case .off:
            nil
        case .whileUsing:
            String(localized: "While Using the App")
        case .always:
            String(localized: "Always")
        }
    }
}

import CoreLocation
import Foundation
import OpenClawKit

/// Monitors significant location changes and pushes `location.update`
/// events to the gateway so the severance hook can determine whether
/// the user is at their configured work location.
@MainActor
enum SignificantLocationMonitor {
    static func startIfNeeded(
        locationService: any LocationServicing,
        locationMode: OpenClawLocationMode,
        gateway: GatewayNodeSession,
        beforeSend: (@MainActor @Sendable () async -> Void)? = nil)
    {
        guard locationMode == .always else { return }
        let status = locationService.authorizationStatus()
        guard status == .authorizedAlways else { return }
        locationService.setBackgroundLocationUpdatesEnabled(true)
        locationService.startMonitoringSignificantLocationChanges { location in
            struct Payload: Codable {
                var lat: Double
                var lon: Double
                var accuracyMeters: Double
                var source: String?
            }
            let payload = Payload(
                lat: location.coordinate.latitude,
                lon: location.coordinate.longitude,
                accuracyMeters: location.horizontalAccuracy,
                source: "ios-significant-location")
            guard let data = try? JSONEncoder().encode(payload),
                  let json = String(data: data, encoding: .utf8)
            else { return }
            Task { @MainActor in
                if let beforeSend {
                    await beforeSend()
                }
                await gateway.sendEvent(event: "location.update", payloadJSON: json)
            }
        }
    }
}

import Foundation
import OpenClawKit
import Photos
import UIKit

enum PhotoLibraryAccess {
    static func authorizationStatus() -> PHAuthorizationStatus {
        PHPhotoLibrary.authorizationStatus(for: .readWrite)
    }

    static func canRead(_ status: PHAuthorizationStatus) -> Bool {
        status == .authorized || status == .limited
    }

    static func requestReadWrite() async -> PHAuthorizationStatus {
        await PHPhotoLibrary.requestAuthorization(for: .readWrite)
    }
}

final class PhotoLibraryService: PhotosServicing {
    // The gateway WebSocket has a max payload size; returning large base64 blobs
    // can cause the gateway to close the connection. Keep photo payloads small
    // enough to safely fit in a single RPC frame.
    //
    // This is a transport constraint (not a security policy). If callers need
    // full-resolution media, we should switch to an HTTP media handle flow.
    private static let maxTotalBase64Chars = 340 * 1024
    private static let maxPerPhotoBase64Chars = 300 * 1024

    func latest(params: OpenClawPhotosLatestParams) async throws -> OpenClawPhotosLatestPayload {
        let status = await Self.ensureAuthorization()
        guard PhotoLibraryAccess.canRead(status) else {
            throw NSError(domain: "Photos", code: 1, userInfo: [
                NSLocalizedDescriptionKey: "PHOTOS_PERMISSION_REQUIRED: grant Photos permission",
            ])
        }

        let limit = max(1, min(params.limit ?? 1, 20))
        let fetchOptions = PHFetchOptions()
        fetchOptions.fetchLimit = limit
        fetchOptions.sortDescriptors = [NSSortDescriptor(key: "creationDate", ascending: false)]
        let assets = PHAsset.fetchAssets(with: .image, options: fetchOptions)

        var results: [OpenClawPhotoPayload] = []
        var remainingBudget = Self.maxTotalBase64Chars
        let maxWidth = params.maxWidth.flatMap { $0 > 0 ? $0 : nil } ?? 1600
        let quality = params.quality.map { max(0.1, min(1.0, $0)) } ?? 0.85
        let formatter = ISO8601DateFormatter()

        assets.enumerateObjects { asset, _, stop in
            if results.count >= limit {
                stop.pointee = true
                return
            }
            if let payload = try? Self.renderAsset(
                asset,
                maxWidth: maxWidth,
                quality: quality,
                formatter: formatter)
            {
                // Keep the entire response under the gateway WS max payload.
                if payload.base64.count > remainingBudget {
                    stop.pointee = true
                    return
                }
                remainingBudget -= payload.base64.count
                results.append(payload)
            }
        }

        return OpenClawPhotosLatestPayload(photos: results)
    }

    private static func ensureAuthorization() async -> PHAuthorizationStatus {
        // Don’t prompt during node.invoke; prompts block the invoke and lead to timeouts.
        PhotoLibraryAccess.authorizationStatus()
    }

    private static func renderAsset(
        _ asset: PHAsset,
        maxWidth: Int,
        quality: Double,
        formatter: ISO8601DateFormatter) throws -> OpenClawPhotoPayload
    {
        let manager = PHImageManager.default()
        let options = PHImageRequestOptions()
        options.isSynchronous = true
        options.isNetworkAccessAllowed = true
        options.deliveryMode = .highQualityFormat

        let targetSize: CGSize = {
            guard maxWidth > 0 else { return PHImageManagerMaximumSize }
            let aspect = CGFloat(asset.pixelHeight) / CGFloat(max(1, asset.pixelWidth))
            let width = CGFloat(maxWidth)
            return CGSize(width: width, height: width * aspect)
        }()

        var image: UIImage?
        manager.requestImage(
            for: asset,
            targetSize: targetSize,
            contentMode: .aspectFit,
            options: options)
        { result, _ in
            image = result
        }

        guard let image else {
            throw NSError(domain: "Photos", code: 2, userInfo: [
                NSLocalizedDescriptionKey: "photo load failed",
            ])
        }

        let (data, finalImage) = try encodeJpegUnderBudget(
            image: image,
            quality: quality,
            maxBase64Chars: maxPerPhotoBase64Chars)

        let created = asset.creationDate.map { formatter.string(from: $0) }
        return OpenClawPhotoPayload(
            format: "jpeg",
            base64: data.base64EncodedString(),
            width: Int(finalImage.size.width),
            height: Int(finalImage.size.height),
            createdAt: created)
    }

    private static func encodeJpegUnderBudget(
        image: UIImage,
        quality: Double,
        maxBase64Chars: Int) throws -> (Data, UIImage)
    {
        var currentImage = image
        var currentQuality = max(0.1, min(1.0, quality))

        // Try lowering JPEG quality first, then downscale if needed.
        for _ in 0..<10 {
            guard let data = currentImage.jpegData(compressionQuality: currentQuality) else {
                throw NSError(domain: "Photos", code: 3, userInfo: [
                    NSLocalizedDescriptionKey: "photo encode failed",
                ])
            }

            let base64Len = ((data.count + 2) / 3) * 4
            if base64Len <= maxBase64Chars {
                return (data, currentImage)
            }

            if currentQuality > 0.35 {
                currentQuality = max(0.25, currentQuality - 0.15)
                continue
            }

            // Downscale by ~25% each step once quality is low.
            let newWidth = max(240, currentImage.size.width * 0.75)
            if newWidth >= currentImage.size.width {
                break
            }
            currentImage = self.resize(image: currentImage, targetWidth: newWidth)
        }

        throw NSError(domain: "Photos", code: 4, userInfo: [
            NSLocalizedDescriptionKey: "photo too large for gateway transport; try smaller maxWidth/quality",
        ])
    }

    private static func resize(image: UIImage, targetWidth: CGFloat) -> UIImage {
        let size = image.size
        if size.width <= 0 || size.height <= 0 || targetWidth <= 0 {
            return image
        }
        let scale = targetWidth / size.width
        let targetSize = CGSize(width: targetWidth, height: max(1, size.height * scale))
        let format = UIGraphicsImageRendererFormat.default()
        format.scale = 1
        let renderer = UIGraphicsImageRenderer(size: targetSize, format: format)
        return renderer.image { _ in
            image.draw(in: CGRect(origin: .zero, size: targetSize))
        }
    }
}

import Foundation

enum AgentIdentityPresentation {
    nonisolated static func badge(avatarText: String?, displayName: String) -> String {
        self.normalizedBadgeEmoji(avatarText) ?? self.initialsBadge(for: displayName)
    }

    nonisolated static func initialsBadge(for displayName: String) -> String {
        let words = displayName
            .split(whereSeparator: { $0.isWhitespace || $0 == "-" || $0 == "_" })
            .prefix(2)
        let initials = words.compactMap(\.first).map(String.init).joined()
        return initials.isEmpty ? "OC" : initials.uppercased()
    }

    nonisolated static func normalizedBadgeEmoji(_ value: String?) -> String? {
        guard let value else { return nil }
        let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return normalized.isEmpty || normalized == "?" ? nil : normalized
    }
}

import Foundation
import OpenClawKit

extension NodeAppModel {
    static func normalizeWatchNotifyParams(_ params: OpenClawWatchNotifyParams) -> OpenClawWatchNotifyParams {
        var normalized = params
        normalized.title = params.title.trimmingCharacters(in: .whitespacesAndNewlines)
        normalized.body = params.body.trimmingCharacters(in: .whitespacesAndNewlines)
        normalized.promptId = self.trimmedOrNil(params.promptId)
        normalized.sessionKey = self.trimmedOrNil(params.sessionKey)
        normalized.gatewayStableID = self.trimmedOrNil(params.gatewayStableID)
        normalized.kind = self.trimmedOrNil(params.kind)
        normalized.details = self.trimmedOrNil(params.details)
        normalized.priority = self.normalizedWatchPriority(params.priority, risk: params.risk)
        normalized.risk = self.normalizedWatchRisk(params.risk, priority: normalized.priority)

        let normalizedActions = self.normalizeWatchActions(
            params.actions,
            kind: normalized.kind,
            promptId: normalized.promptId)
        normalized.actions = normalizedActions.isEmpty ? nil : normalizedActions
        return normalized
    }

    static func normalizeWatchActions(
        _ actions: [OpenClawWatchAction]?,
        kind: String?,
        promptId: String?) -> [OpenClawWatchAction]
    {
        let provided = (actions ?? []).compactMap { action -> OpenClawWatchAction? in
            let id = action.id.trimmingCharacters(in: .whitespacesAndNewlines)
            let label = action.label.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !id.isEmpty, !label.isEmpty else { return nil }
            return OpenClawWatchAction(
                id: id,
                label: label,
                style: self.trimmedOrNil(action.style))
        }
        if !provided.isEmpty {
            return Array(provided.prefix(4))
        }

        // Only auto-insert quick actions when this is a prompt/decision flow.
        guard promptId?.isEmpty == false else {
            return []
        }

        let normalizedKind = kind?.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() ?? ""
        if normalizedKind.contains("approval") || normalizedKind.contains("approve") {
            return [
                OpenClawWatchAction(id: "approve", label: "Approve"),
                OpenClawWatchAction(id: "decline", label: "Decline", style: "destructive"),
                OpenClawWatchAction(id: "open_phone", label: "Open iPhone"),
                OpenClawWatchAction(id: "escalate", label: "Escalate"),
            ]
        }

        return [
            OpenClawWatchAction(id: "done", label: "Done"),
            OpenClawWatchAction(id: "snooze_10m", label: "Snooze 10m"),
            OpenClawWatchAction(id: "open_phone", label: "Open iPhone"),
            OpenClawWatchAction(id: "escalate", label: "Escalate"),
        ]
    }

    static func normalizedWatchRisk(
        _ risk: OpenClawWatchRisk?,
        priority: OpenClawNotificationPriority?) -> OpenClawWatchRisk?
    {
        if let risk { return risk }
        switch priority {
        case .passive:
            return .low
        case .active:
            return .medium
        case .timeSensitive:
            return .high
        case nil:
            return nil
        }
    }

    static func normalizedWatchPriority(
        _ priority: OpenClawNotificationPriority?,
        risk: OpenClawWatchRisk?) -> OpenClawNotificationPriority?
    {
        if let priority { return priority }
        switch risk {
        case .low:
            return .passive
        case .medium:
            return .active
        case .high:
            return .timeSensitive
        case nil:
            return nil
        }
    }

    static func trimmedOrNil(_ value: String?) -> String? {
        let trimmed = value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return trimmed.isEmpty ? nil : trimmed
    }
}

