/// Closed grant state for one device permission shown in Settings.
enum DevicePermissionGrant: Equatable {
    case granted
    case limited
    case notRequested
    case denied
}

/// Device permissions managed by the Privacy & Access Settings section.
enum DevicePermissionKind {
    case photos
    case contacts
    case calendar
    case reminders

    var symbol: String {
        switch self {
        case .photos: "photo.on.rectangle"
        case .contacts: "person.crop.circle.fill"
        case .calendar: "calendar"
        case .reminders: "checklist"
        }
    }

    var tint: Color {
        switch self {
        case .photos: .orange
        case .contacts: .blue
        case .calendar: .teal
        case .reminders: .green
        }
    }

    var title: LocalizedStringResource {
        switch self {
        case .photos: LocalizedStringResource("Photos")
        case .contacts: LocalizedStringResource("Contacts")
        case .calendar: LocalizedStringResource("Calendar")
        case .reminders: LocalizedStringResource("Reminders")
        }
    }
}

/// Pure status→grant maps keep every Settings row on one vocabulary.
enum DevicePermissionStatusMap {
    static func contacts(_ status: CNAuthorizationStatus) -> DevicePermissionGrant {
        switch status {
        case .authorized: .granted
        case .limited: .limited
        case .notDetermined: .notRequested
        case .denied, .restricted: .denied
        @unknown default: .denied
        }
    }

    static func photos(_ status: PHAuthorizationStatus) -> DevicePermissionGrant {
        switch status {
        case .authorized: .granted
        case .limited: .limited
        case .notDetermined: .notRequested
        case .denied, .restricted: .denied
        @unknown default: .denied
        }
    }

    /// Full read access; `.writeOnly` surfaces as `.limited` ("Add-Only").
    static func eventKitRead(_ status: EKAuthorizationStatus) -> DevicePermissionGrant {
        switch status {
        case .authorized, .fullAccess: .granted
        case .writeOnly: .limited
        case .notDetermined: .notRequested
        case .denied, .restricted: .denied
        @unknown default: .denied
        }
    }

    /// Add-events access; `.writeOnly` already satisfies it.
    static func eventKitWrite(_ status: EKAuthorizationStatus) -> DevicePermissionGrant {
        switch status {
        case .authorized, .fullAccess, .writeOnly: .granted
        case .notDetermined: .notRequested
        case .denied, .restricted: .denied
        @unknown default: .denied
        }
    }
}

import EventKit

protocol EventKitPermissionStore: AnyObject {
    func requestWriteOnlyAccessToEvents(
        completion: @escaping @Sendable (Bool, (any Error)?) -> Void)
    func requestFullAccessToEvents(
        completion: @escaping @Sendable (Bool, (any Error)?) -> Void)
    func requestFullAccessToReminders(
        completion: @escaping @Sendable (Bool, (any Error)?) -> Void)
}

extension EKEventStore: EventKitPermissionStore {}

/// Keeps one event store alive while Calendar or Reminders permission sheets are active.
///
/// EventKit recommends retaining a long-lived store. A temporary store can disappear
/// before its asynchronous authorization callback completes, leaving the UI waiting
/// even though iOS persisted the user's choice.
/// `PermissionRequestBridge` starts every store request on the main actor; the unchecked
/// conformance only allows that private store owner to cross the bridge's sendable closure.
final class EventKitPermissionRequester: @unchecked Sendable {
    private let store: any EventKitPermissionStore

    init(store: any EventKitPermissionStore = EKEventStore()) {
        self.store = store
    }

    func requestWriteOnlyAccessToEvents() async -> Bool {
        await PermissionRequestBridge.awaitRequest { [self] completion in
            self.store.requestWriteOnlyAccessToEvents { granted, _ in
                completion(granted)
            }
        }
    }

    func requestFullAccessToEvents() async -> Bool {
        await PermissionRequestBridge.awaitRequest { [self] completion in
            self.store.requestFullAccessToEvents { granted, _ in
                completion(granted)
            }
        }
    }

    func requestFullAccessToReminders() async -> Bool {
        await PermissionRequestBridge.awaitRequest { [self] completion in
            self.store.requestFullAccessToReminders { granted, _ in
                completion(granted)
            }
        }
    }
}

import Foundation

enum PermissionRequestBridge {
    final class Box: @unchecked Sendable {
        private let lock = NSLock()
        private var continuation: CheckedContinuation<Bool, Never>?
        private var hasResumed = false

        func install(_ continuation: CheckedContinuation<Bool, Never>) -> Bool {
            self.lock.lock()
            if self.hasResumed {
                self.lock.unlock()
                continuation.resume(returning: false)
                return false
            }
            self.continuation = continuation
            self.lock.unlock()
            return true
        }

        func resume(_ value: Bool) {
            self.lock.lock()
            guard !self.hasResumed else {
                self.lock.unlock()
                return
            }
            self.hasResumed = true
            let continuation = self.continuation
            self.continuation = nil
            self.lock.unlock()
            continuation?.resume(returning: value)
        }

        func canStartRequest() -> Bool {
            self.lock.lock()
            let canStart = !self.hasResumed
            self.lock.unlock()
            return canStart
        }
    }

    static func awaitRequest(
        _ start: @escaping @Sendable (@escaping @Sendable (Bool) -> Void) -> Void) async -> Bool
    {
        let box = Box()
        return await withTaskCancellationHandler {
            await withCheckedContinuation(isolation: nil) { continuation in
                guard !Task.isCancelled else {
                    continuation.resume(returning: false)
                    return
                }
                guard box.install(continuation) else { return }
                Task { @MainActor in
                    guard box.canStartRequest() else { return }
                    start { granted in
                        box.resume(granted)
                    }
                }
            }
        } onCancel: {
            box.resume(false)
        }
    }
}

import Foundation
import UIKit

enum BackgroundAliveBeacon {
    static let eventName = "node.presence.alive"
    static let minSuccessIntervalSeconds: TimeInterval = 10 * 60

    enum Trigger: String, CaseIterable, Codable {
        case background
        case silentPush = "silent_push"
        case bgAppRefresh = "bg_app_refresh"
        case significantLocation = "significant_location"
        case manual
        case connect
    }

    struct Payload: Encodable {
        var trigger: String
        var sentAtMs: Int64
        var displayName: String
        var version: String
        var platform: String
        var deviceFamily: String
        var modelIdentifier: String
        var pushTransport: String?
    }

    struct NodeEventRequestPayload: Codable {
        var event: String = BackgroundAliveBeacon.eventName
        var payloadJSON: String
    }

    struct NodeEventResponsePayload: Decodable {
        var ok: Bool?
        var event: String?
        var handled: Bool?
        var reason: String?
    }

    static func normalizeTrigger(_ raw: String) -> Trigger {
        let normalized = raw.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return Trigger(rawValue: normalized) ?? .background
    }

    static func shouldSkipRecentSuccess(
        isGatewayConnected: Bool,
        now: Date,
        lastSuccessAtMs: Double?,
        minInterval: TimeInterval = Self.minSuccessIntervalSeconds) -> Bool
    {
        guard isGatewayConnected else { return false }
        guard let lastSuccessAtMs, lastSuccessAtMs > 0 else { return false }
        let elapsed = now.timeIntervalSince1970 - (lastSuccessAtMs / 1000.0)
        return elapsed >= 0 && elapsed < minInterval
    }

    @MainActor
    static func makePayload(trigger: Trigger, displayName: String, pushTransport: String?) -> Payload {
        Payload(
            trigger: trigger.rawValue,
            sentAtMs: Int64(Date().timeIntervalSince1970 * 1000),
            displayName: displayName,
            version: DeviceInfoHelper.appVersion(),
            platform: DeviceInfoHelper.platformString(),
            deviceFamily: DeviceInfoHelper.deviceFamily(),
            modelIdentifier: DeviceInfoHelper.modelIdentifier(),
            pushTransport: pushTransport)
    }

    static func makeNodeEventRequestPayloadJSON(
        payload: Payload,
        encoder: JSONEncoder = JSONEncoder()) throws -> String
    {
        let payloadData = try encoder.encode(payload)
        guard let payloadJSON = String(data: payloadData, encoding: .utf8) else {
            throw EncodingError.invalidValue(payload, EncodingError.Context(
                codingPath: [],
                debugDescription: "Failed to encode background alive payload as UTF-8"))
        }
        let requestData = try encoder.encode(NodeEventRequestPayload(payloadJSON: payloadJSON))
        guard let requestJSON = String(data: requestData, encoding: .utf8) else {
            throw EncodingError.invalidValue(payload, EncodingError.Context(
                codingPath: [],
                debugDescription: "Failed to encode node.event payload as UTF-8"))
        }
        return requestJSON
    }

    static func decodeResponse(_ data: Data) -> NodeEventResponsePayload? {
        try? JSONDecoder().decode(NodeEventResponsePayload.self, from: data)
    }
}

