/// Keeps notification failures Sendable across the system prompt and timeout tasks.
struct NotificationCallError: Error {
    let message: String
}

@MainActor
enum NotificationOperationRunner {
    /// Permission callbacks may ignore cancellation. The shared race retires their task
    /// before returning so late callbacks cannot start a notification for a cancelled caller.
    static func run<Value: Sendable>(
        timeoutSeconds: Double,
        operation: @escaping @Sendable () async throws -> Value) async -> Result<Value, NotificationCallError>
    {
        do {
            let value = try await AsyncTimeout.withTimeout(
                seconds: timeoutSeconds,
                onTimeout: { NotificationCallError(message: "notification request timed out") },
                operation: operation)
            return .success(value)
        } catch let error as NotificationCallError {
            return .failure(error)
        } catch {
            return .failure(NotificationCallError(message: error.localizedDescription))
        }
    }
}

enum NotificationServingPreference {
    static let storageKey = "notifications.serving.enabled"
    static let defaultEnabled = true

    static func isEnabled(defaults: UserDefaults = .standard) -> Bool {
        guard defaults.object(forKey: self.storageKey) != nil else {
            return self.defaultEnabled
        }
        return defaults.bool(forKey: self.storageKey)
    }
}

import Foundation
import OSLog
@preconcurrency import WatchConnectivity

private struct WatchConnectivityTransportCallbacks {
    var statusUpdateHandler: (@Sendable (WatchMessagingStatus) -> Void)?
    var inboundEventHandler: (@Sendable (WatchMessagingInboundEvent) -> Void)?
}

func updateWatchSnapshotApplicationContext(_ payload: [String: Any], with session: WCSession, lock: NSLock) throws {
    try lock.withLock {
        let context = WatchMessagingPayloadCodec.encodeSnapshotApplicationContext(
            payload,
            merging: session.applicationContext)
        // The caller may retire while another snapshot holds this lock.
        try Task.checkCancellation()
        try session.updateApplicationContext(context)
    }
}

final class WatchConnectivityTransport: NSObject, @unchecked Sendable {
    private nonisolated static let logger = Logger(subsystem: "ai.openclawfoundation.app", category: "watch.messaging")

    private let session: WCSession?
    private let activationGate = WatchSessionActivationGate()
    private let callbacksLock = NSLock()
    private let snapshotContextLock = NSLock()
    private var callbacks = WatchConnectivityTransportCallbacks()

    override init() {
        if WCSession.isSupported() {
            self.session = WCSession.default
        } else {
            self.session = nil
        }
        super.init()
        if let session = self.session {
            session.delegate = self
        }
    }

    nonisolated static func isSupportedOnDevice() -> Bool {
        WCSession.isSupported()
    }

    func status() async -> WatchMessagingStatus {
        try? await self.ensureActivated()
        return self.currentStatusSnapshot()
    }

    func currentStatusSnapshot() -> WatchMessagingStatus {
        guard let session = self.session else {
            return WatchMessagingStatus(
                supported: false,
                paired: false,
                appInstalled: false,
                reachable: false,
                activationState: "unsupported")
        }
        return Self.status(for: session)
    }

    func setStatusUpdateHandler(_ handler: (@Sendable (WatchMessagingStatus) -> Void)?) {
        self.updateCallbacks { $0.statusUpdateHandler = handler }
    }

    func setInboundEventHandler(_ handler: (@Sendable (WatchMessagingInboundEvent) -> Void)?) {
        self.updateCallbacks { $0.inboundEventHandler = handler }
    }

    func activate() {
        guard let session = self.session else { return }
        self.beginActivation(session)
    }

    func sendPayload(_ payload: [String: Any]) async throws -> WatchNotificationSendResult {
        try await self.sendPayload(payload, isSnapshot: false)
    }

    func sendSnapshotPayload(_ payload: [String: Any]) async throws -> WatchNotificationSendResult {
        try await self.sendPayload(payload, isSnapshot: true)
    }

    private func sendPayload(
        _ payload: [String: Any],
        isSnapshot: Bool) async throws -> WatchNotificationSendResult
    {
        try await Self.deliverPayload(
            prepareSession: {
                try await self.ensureActivated()
                return try self.requireReadySession()
            },
            sendImmediately: { session in
                guard session.isReachable else { return false }
                try await sendReachableWatchMessage(payload, with: session)
                return true
            },
            enqueue: { session in
                if isSnapshot {
                    do {
                        try updateWatchSnapshotApplicationContext(
                            payload,
                            with: session,
                            lock: self.snapshotContextLock)
                        return "applicationContext"
                    } catch {
                        Self.logger.error(
                            "watch updateApplicationContext failed: \(error.localizedDescription, privacy: .public)")
                    }
                }
                try Task.checkCancellation()
                _ = session.transferUserInfo(payload)
                return "transferUserInfo"
            })
    }

    static func deliverPayload<Session>(
        prepareSession: () async throws -> Session,
        sendImmediately: (Session) async throws -> Bool,
        enqueue: (Session) throws -> String) async throws -> WatchNotificationSendResult
    {
        let session = try await prepareSession()
        // Activation may outlive its caller; only a live request may start a transfer.
        try Task.checkCancellation()
        do {
            if try await sendImmediately(session) {
                return WatchNotificationSendResult(
                    deliveredImmediately: true,
                    queuedForDelivery: false,
                    transport: "sendMessage")
            }
        } catch {
            Self.logger.error("watch sendMessage failed: \(error.localizedDescription, privacy: .public)")
        }
        // A failed interactive attempt has not admitted a new background transfer.
        try Task.checkCancellation()
        return try WatchNotificationSendResult(
            deliveredImmediately: false,
            queuedForDelivery: true,
            transport: enqueue(session))
    }

    private func updateCallbacks(_ update: (inout WatchConnectivityTransportCallbacks) -> Void) {
        self.callbacksLock.lock()
        defer { self.callbacksLock.unlock() }
        update(&self.callbacks)
    }

    private func callbacksSnapshot() -> WatchConnectivityTransportCallbacks {
        self.callbacksLock.lock()
        defer { self.callbacksLock.unlock() }
        return self.callbacks
    }

    private func requireReadySession() throws -> WCSession {
        guard let session = self.session else {
            throw WatchMessagingError.unsupported
        }
        guard session.activationState == .activated else {
            throw WatchSessionActivationError.failed("session stayed inactive")
        }
        let snapshot = Self.status(for: session)
        guard snapshot.paired else {
            throw WatchMessagingError.notPaired
        }
        guard snapshot.appInstalled else {
            throw WatchMessagingError.watchAppNotInstalled
        }
        return session
    }

    private func beginActivation(_ session: WCSession) {
        if self.activationGate.beginActivation() {
            session.activate()
        }
    }

    private func ensureActivated() async throws {
        guard let session = self.session else { return }
        if session.activationState == .activated {
            self.activationGate.complete(activated: true, errorDescription: nil)
            return
        }
        self.beginActivation(session)
        try await self.activationGate.waitUntilActivated()
    }

    private func emitStatusUpdate(_ snapshot: WatchMessagingStatus) {
        guard let handler = self.callbacksSnapshot().statusUpdateHandler else {
            return
        }
        Task { @MainActor in
            handler(snapshot)
        }
    }

    private func emitInboundEvent(_ event: WatchMessagingInboundEvent) {
        guard let handler = self.callbacksSnapshot().inboundEventHandler else {
            return
        }
        Task { @MainActor in
            handler(event)
        }
    }

    private nonisolated static func status(for session: WCSession) -> WatchMessagingStatus {
        let activationState = session.activationState
        let isActivated = activationState == .activated
        return WatchMessagingStatus(
            supported: true,
            paired: isActivated && session.isPaired,
            appInstalled: isActivated && session.isWatchAppInstalled,
            reachable: isActivated && session.isReachable,
            activationState: self.activationStateLabel(activationState))
    }

    private nonisolated static func activationStateLabel(_ state: WCSessionActivationState) -> String {
        switch state {
        case .notActivated:
            "notActivated"
        case .inactive:
            "inactive"
        case .activated:
            "activated"
        @unknown default:
            "unknown"
        }
    }
}

extension WatchConnectivityTransport: WCSessionDelegate {
    func session(
        _ session: WCSession,
        activationDidCompleteWith activationState: WCSessionActivationState,
        error: (any Error)?)
    {
        self.activationGate.complete(
            activated: activationState == .activated,
            errorDescription: error?.localizedDescription)
        GatewayDiagnostics.log(
            "watch messaging: activation complete "
                + "state=\(Self.activationStateLabel(activationState)) "
                + "error=\(error?.localizedDescription ?? "none")")
        if let error {
            Self.logger.error("watch activation failed: \(error.localizedDescription, privacy: .public)")
        } else {
            Self.logger.debug(
                "watch activation state=\(Self.activationStateLabel(activationState), privacy: .public)")
        }
        self.emitStatusUpdate(Self.status(for: session))
    }

    func sessionDidBecomeInactive(_ session: WCSession) {
        GatewayDiagnostics.log("watch messaging: session became inactive")
        self.emitStatusUpdate(Self.status(for: session))
    }

    func sessionDidDeactivate(_ session: WCSession) {
        GatewayDiagnostics.log("watch messaging: session did deactivate; reactivating")
        self.activationGate.reset()
        self.beginActivation(session)
        self.emitStatusUpdate(Self.status(for: session))
    }

    func sessionWatchStateDidChange(_ session: WCSession) {
        GatewayDiagnostics.log(
            "watch messaging: watch state changed "
                + "paired=\(session.isPaired) installed=\(session.isWatchAppInstalled)")
        self.emitStatusUpdate(Self.status(for: session))
    }

    func session(_: WCSession, didReceiveMessage message: [String: Any]) {
        let type = (message["type"] as? String) ?? "unknown"
        GatewayDiagnostics.log("watch messaging: didReceiveMessage type=\(type)")
        if let event = WatchMessagingPayloadCodec.parseInboundPayload(
            message,
            transport: "sendMessage")
        {
            self.emitInboundEvent(event)
        }
    }

    func session(
        _: WCSession,
        didReceiveMessage message: [String: Any],
        replyHandler: @escaping ([String: Any]) -> Void)
    {
        let type = (message["type"] as? String) ?? "unknown"
        GatewayDiagnostics.log("watch messaging: didReceiveMessageWithReply type=\(type)")
        guard let event = WatchMessagingPayloadCodec.parseInboundPayload(
            message,
            transport: "sendMessage")
        else {
            replyHandler(["ok": false, "error": "unsupported_payload"])
            return
        }
        replyHandler(["ok": true])
        self.emitInboundEvent(event)
    }

    func session(_: WCSession, didReceiveUserInfo userInfo: [String: Any]) {
        let type = (userInfo["type"] as? String) ?? "unknown"
        GatewayDiagnostics.log("watch messaging: didReceiveUserInfo type=\(type)")
        if let event = WatchMessagingPayloadCodec.parseInboundPayload(
            userInfo,
            transport: "transferUserInfo")
        {
            self.emitInboundEvent(event)
        }
    }

    func sessionReachabilityDidChange(_ session: WCSession) {
        GatewayDiagnostics.log(
            "watch messaging: reachability changed "
                + "reachable=\(session.isReachable) paired=\(session.isPaired) "
                + "installed=\(session.isWatchAppInstalled)")
        self.emitStatusUpdate(Self.status(for: session))
    }
}

import Foundation
import OpenClawKit

enum WatchMessagingInboundEvent {
    case reply(WatchQuickReplyEvent)
    case execApprovalResolve(WatchExecApprovalResolveEvent)
    case execApprovalSnapshotRequest(WatchExecApprovalSnapshotRequestEvent)
    case appSnapshotRequest(WatchAppSnapshotRequestEvent)
    case appCommand(WatchAppCommandEvent)
}

enum WatchMessagingPayloadCodec {
    private static let durableSnapshotTypes = [
        OpenClawWatchPayloadType.appSnapshot.rawValue,
        OpenClawWatchPayloadType.execApprovalSnapshot.rawValue,
    ]

    static let completedChatReplyTextLimit = 4000

    static func nowMs() -> Int64 {
        Int64(Date().timeIntervalSince1970 * 1000)
    }

    static func nonEmpty(_ value: String?) -> String? {
        let trimmed = value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return trimmed.isEmpty ? nil : trimmed
    }

    static func exactNonEmpty(_ value: String?) -> String? {
        guard let value, !value.isEmpty else { return nil }
        return value
    }

    static func encodeNotificationPayload(
        id: String,
        params: OpenClawWatchNotifyParams,
        gatewayStableID: String?) -> [String: Any]
    {
        var payload: [String: Any] = [
            "type": OpenClawWatchPayloadType.notify.rawValue,
            "id": id,
            "title": params.title,
            "body": params.body,
            "priority": params.priority?.rawValue ?? OpenClawNotificationPriority.active.rawValue,
            "sentAtMs": self.nowMs(),
        ]
        if let promptId = nonEmpty(params.promptId) {
            payload["promptId"] = promptId
        }
        if let sessionKey = nonEmpty(params.sessionKey) {
            payload["sessionKey"] = sessionKey
        }
        if let gatewayStableID = GatewayStableIdentifier.exact(gatewayStableID) {
            payload["gatewayStableID"] = gatewayStableID
        }
        if let kind = nonEmpty(params.kind) {
            payload["kind"] = kind
        }
        if let details = nonEmpty(params.details) {
            payload["details"] = details
        }
        if let expiresAtMs = params.expiresAtMs {
            payload["expiresAtMs"] = expiresAtMs
        }
        if let risk = params.risk {
            payload["risk"] = risk.rawValue
        }
        if let actions = params.actions, !actions.isEmpty {
            payload["actions"] = actions.map { action in
                var encoded: [String: Any] = [
                    "id": action.id,
                    "label": action.label,
                ]
                if let style = nonEmpty(action.style) {
                    encoded["style"] = style
                }
                return encoded
            }
        }
        return payload
    }

    static func encodeDirectNodeSetupPayload(setupCode: String) -> [String: Any] {
        [
            "type": OpenClawWatchPayloadType.directNodeSetup.rawValue,
            "setupCode": setupCode,
            "sentAtMs": self.nowMs(),
        ]
    }

    static func encodeExecApprovalItem(_ item: OpenClawWatchExecApprovalItem) -> [String: Any] {
        var payload: [String: Any] = [
            "id": item.id,
            "commandText": item.commandText,
            "allowedDecisions": item.allowedDecisions.map(\.rawValue),
        ]
        if let gatewayStableID = GatewayStableIdentifier.exact(item.gatewayStableID) {
            payload["gatewayStableID"] = gatewayStableID
        }
        if let commandPreview = nonEmpty(item.commandPreview) {
            payload["commandPreview"] = commandPreview
        }
        if let warningText = nonEmpty(item.warningText) {
            payload["warningText"] = warningText
        }
        if let host = nonEmpty(item.host) {
            payload["host"] = host
        }
        if let nodeId = nonEmpty(item.nodeId) {
            payload["nodeId"] = nodeId
        }
        if let agentId = nonEmpty(item.agentId) {
            payload["agentId"] = agentId
        }
        if let expiresAtMs = item.expiresAtMs {
            payload["expiresAtMs"] = expiresAtMs
        }
        if let risk = item.risk {
            payload["risk"] = risk.rawValue
        }
        return payload
    }

    static func encodeExecApprovalPromptPayload(
        _ message: OpenClawWatchExecApprovalPromptMessage) -> [String: Any]
    {
        var payload: [String: Any] = [
            "type": OpenClawWatchPayloadType.execApprovalPrompt.rawValue,
            "approval": self.encodeExecApprovalItem(message.approval),
        ]
        if let sentAtMs = message.sentAtMs {
            payload["sentAtMs"] = sentAtMs
        }
        if let resetResolutionAttemptId = exactNonEmpty(message.resetResolutionAttemptId) {
            payload["resetResolutionAttemptId"] = resetResolutionAttemptId
        }
        return payload
    }

    static func encodeExecApprovalResolvedPayload(
        _ message: OpenClawWatchExecApprovalResolvedMessage) -> [String: Any]
    {
        var payload: [String: Any] = [
            "type": OpenClawWatchPayloadType.execApprovalResolved.rawValue,
            "approvalId": message.approvalId,
        ]
        if let gatewayStableID = GatewayStableIdentifier.exact(message.gatewayStableID) {
            payload["gatewayStableID"] = gatewayStableID
        }
        if let decision = message.decision {
            payload["decision"] = decision.rawValue
        }
        if let outcome = message.outcome {
            payload["outcome"] = outcome.rawValue
        }
        if let resolvedAtMs = message.resolvedAtMs {
            payload["resolvedAtMs"] = resolvedAtMs
        }
        if let source = nonEmpty(message.source) {
            payload["source"] = source
        }
        if let outcomeText = nonEmpty(message.outcomeText) {
            payload["outcomeText"] = outcomeText
        }
        return payload
    }

    static func encodeExecApprovalExpiredPayload(
        _ message: OpenClawWatchExecApprovalExpiredMessage) -> [String: Any]
    {
        var payload: [String: Any] = [
            "type": OpenClawWatchPayloadType.execApprovalExpired.rawValue,
            "approvalId": message.approvalId,
            "reason": message.reason.rawValue,
        ]
        if let gatewayStableID = GatewayStableIdentifier.exact(message.gatewayStableID) {
            payload["gatewayStableID"] = gatewayStableID
        }
        if let expiredAtMs = message.expiredAtMs {
            payload["expiredAtMs"] = expiredAtMs
        }
        return payload
    }

    static func encodeExecApprovalSnapshotPayload(
        _ message: OpenClawWatchExecApprovalSnapshotMessage) -> [String: Any]
    {
        var payload: [String: Any] = [
            "type": OpenClawWatchPayloadType.execApprovalSnapshot.rawValue,
            "approvals": message.approvals.map(self.encodeExecApprovalItem),
        ]
        if let gatewayStableID = GatewayStableIdentifier.exact(message.gatewayStableID) {
            payload["gatewayStableID"] = gatewayStableID
        }
        if let sentAtMs = message.sentAtMs {
            payload["sentAtMs"] = sentAtMs
        }
        if let snapshotId = nonEmpty(message.snapshotId) {
            payload["snapshotId"] = snapshotId
        }
        if let requestId = exactNonEmpty(message.requestId) {
            payload["requestId"] = requestId
        }
        if let requestGatewayStableID = GatewayStableIdentifier.exact(message.requestGatewayStableID) {
            payload["requestGatewayStableID"] = requestGatewayStableID
        }
        return payload
    }

    static func encodeAppSnapshotPayload(
        _ message: OpenClawWatchAppSnapshotMessage) -> [String: Any]
    {
        var payload: [String: Any] = [
            "type": OpenClawWatchPayloadType.appSnapshot.rawValue,
            "gatewayStatus": self.encodeAppStatus(message.gatewayStatus),
            "gatewayStatusText": message.gatewayStatusText,
            "gatewayConnected": message.gatewayConnected,
            "agentName": message.agentName,
            "sessionKey": message.sessionKey,
            "talkStatus": self.encodeAppStatus(message.talkStatus),
            "talkStatusText": message.talkStatusText,
            "talkEnabled": message.talkEnabled,
            "talkListening": message.talkListening,
            "talkSpeaking": message.talkSpeaking,
            "pendingApprovalCount": message.pendingApprovalCount,
        ]
        if let agentAvatarURL = nonEmpty(message.agentAvatarURL) {
            payload["agentAvatarUrl"] = agentAvatarURL
        }
        if let agentAvatarText = nonEmpty(message.agentAvatarText) {
            payload["agentAvatarText"] = agentAvatarText
        }
        if let gatewayStableID = GatewayStableIdentifier.exact(message.gatewayStableID) {
            payload["gatewayStableID"] = gatewayStableID
        }
        if let sentAtMs = message.sentAtMs {
            payload["sentAtMs"] = sentAtMs
        }
        if let chatItems = message.chatItems {
            payload["chatItems"] = chatItems.map { item in
                var encoded: [String: Any] = [
                    "id": item.id,
                    "role": item.role,
                    "text": item.text,
                ]
                if let timestampMs = item.timestampMs {
                    encoded["timestampMs"] = timestampMs
                }
                return encoded
            }
        }
        if let chatStatus = message.chatStatus {
            payload["chatStatus"] = self.encodeAppStatus(chatStatus)
        }
        if let chatStatusText = nonEmpty(message.chatStatusText) {
            payload["chatStatusText"] = chatStatusText
        }
        if let snapshotId = nonEmpty(message.snapshotId) {
            payload["snapshotId"] = snapshotId
        }
        return payload
    }

    private static func encodeAppStatus(_ status: OpenClawWatchAppStatus) -> [String: Any] {
        var payload: [String: Any] = ["code": status.code.rawValue]
        if let localizationKey = exactNonEmpty(status.localizationKey) {
            payload["localizationKey"] = localizationKey
        }
        if !status.arguments.isEmpty {
            payload["arguments"] = status.arguments
        }
        if let verbatim = exactNonEmpty(status.verbatim) {
            payload["verbatim"] = verbatim
        }
        return payload
    }

    static func encodeSnapshotApplicationContext(
        _ payload: [String: Any],
        merging existingContext: [String: Any]) -> [String: Any]
    {
        guard let payloadType = payload["type"] as? String,
              self.durableSnapshotTypes.contains(payloadType)
        else {
            return payload
        }

        // updateApplicationContext retains one dictionary. Nest both logical snapshots while
        // keeping the newest one at the top level for older Watch app versions.
        var context = payload
        for snapshotType in self.durableSnapshotTypes {
            if snapshotType == payloadType {
                context[snapshotType] = payload
            } else if let previous = existingContext[snapshotType] as? [String: Any] {
                context[snapshotType] = previous
            } else if existingContext["type"] as? String == snapshotType {
                context[snapshotType] = existingContext
            }
        }
        return context
    }

    static func encodeChatCompletionPayload(
        _ message: OpenClawWatchChatCompletionMessage) -> [String: Any]
    {
        [
            "type": message.type.rawValue,
            "commandId": message.commandId,
            "replyText": self.truncatedCompletedChatReplyText(message.replyText),
            "sentAtMs": message.sentAtMs ?? self.nowMs(),
        ]
    }

    private static func truncatedCompletedChatReplyText(_ text: String) -> String {
        guard text.count > self.completedChatReplyTextLimit else { return text }
        return "\(text.prefix(self.completedChatReplyTextLimit - 3))..."
    }

    static func parseInboundPayload(
        _ payload: [String: Any],
        transport: String) -> WatchMessagingInboundEvent?
    {
        switch payload["type"] as? String {
        case OpenClawWatchPayloadType.reply.rawValue:
            self.parseQuickReplyPayload(payload, transport: transport)
                .map(WatchMessagingInboundEvent.reply)
        case OpenClawWatchPayloadType.execApprovalResolve.rawValue:
            self.parseExecApprovalResolvePayload(payload, transport: transport)
                .map(WatchMessagingInboundEvent.execApprovalResolve)
        case OpenClawWatchPayloadType.execApprovalSnapshotRequest.rawValue:
            self.parseExecApprovalSnapshotRequestPayload(payload, transport: transport)
                .map(WatchMessagingInboundEvent.execApprovalSnapshotRequest)
        case OpenClawWatchPayloadType.appSnapshotRequest.rawValue:
            self.parseAppSnapshotRequestPayload(payload, transport: transport)
                .map(WatchMessagingInboundEvent.appSnapshotRequest)
        case OpenClawWatchPayloadType.appCommand.rawValue:
            self.parseAppCommandPayload(payload, transport: transport)
                .map(WatchMessagingInboundEvent.appCommand)
        default:
            nil
        }
    }

    static func parseQuickReplyPayload(
        _ payload: [String: Any],
        transport: String) -> WatchQuickReplyEvent?
    {
        guard (payload["type"] as? String) == OpenClawWatchPayloadType.reply.rawValue else {
            return nil
        }
        guard let actionId = nonEmpty(payload["actionId"] as? String) else {
            return nil
        }
        let promptId = self.nonEmpty(payload["promptId"] as? String) ?? "unknown"
        let replyId = self.nonEmpty(payload["replyId"] as? String) ?? UUID().uuidString
        let actionLabel = self.nonEmpty(payload["actionLabel"] as? String)
        let sessionKey = self.nonEmpty(payload["sessionKey"] as? String)
        let gatewayStableID = GatewayStableIdentifier.exact(payload["gatewayStableID"] as? String)
        let note = self.nonEmpty(payload["note"] as? String)
        let sentAtMs = (payload["sentAtMs"] as? NSNumber)?.int64Value

        return WatchQuickReplyEvent(
            replyId: replyId,
            promptId: promptId,
            actionId: actionId,
            actionLabel: actionLabel,
            sessionKey: sessionKey,
            gatewayStableID: gatewayStableID,
            note: note,
            sentAtMs: sentAtMs,
            transport: transport)
    }

    static func parseExecApprovalResolvePayload(
        _ payload: [String: Any],
        transport: String) -> WatchExecApprovalResolveEvent?
    {
        guard (payload["type"] as? String) == OpenClawWatchPayloadType.execApprovalResolve.rawValue else {
            return nil
        }
        guard let approvalId = ExecApprovalIdentifier.exact(payload["approvalId"] as? String),
              let rawDecision = nonEmpty(payload["decision"] as? String),
              let decision = OpenClawWatchExecApprovalDecision(rawValue: rawDecision)
        else {
            return nil
        }
        let replyId = self.exactNonEmpty(payload["replyId"] as? String) ?? UUID().uuidString
        let gatewayStableID = GatewayStableIdentifier.exact(payload["gatewayStableID"] as? String)
        let sentAtMs = (payload["sentAtMs"] as? NSNumber)?.int64Value
        return WatchExecApprovalResolveEvent(
            replyId: replyId,
            approvalId: approvalId,
            gatewayStableID: gatewayStableID,
            decision: decision,
            sentAtMs: sentAtMs,
            transport: transport)
    }

    static func parseExecApprovalSnapshotRequestPayload(
        _ payload: [String: Any],
        transport: String) -> WatchExecApprovalSnapshotRequestEvent?
    {
        guard (payload["type"] as? String) == OpenClawWatchPayloadType.execApprovalSnapshotRequest.rawValue else {
            return nil
        }
        // Version-skew compat: shipped Watch binaries request snapshots without requestId or
        // heldApprovals. A missing key decodes as the shipped shape (present-but-malformed
        // still rejects); remove once the minimum paired Watch app version sends heldApprovals.
        let requestId = self.exactNonEmpty(payload["requestId"] as? String) ?? UUID().uuidString
        let rawHeldApprovals: [Any]
        if let rawHeldApprovalsValue = payload["heldApprovals"] {
            guard let heldApprovalsArray = rawHeldApprovalsValue as? [Any] else { return nil }
            rawHeldApprovals = heldApprovalsArray
        } else {
            rawHeldApprovals = []
        }
        var heldApprovals: [WatchExecApprovalSnapshotRequestItem] = []
        heldApprovals.reserveCapacity(rawHeldApprovals.count)
        for rawItem in rawHeldApprovals {
            guard let item = rawItem as? [String: Any],
                  let approvalId = ExecApprovalIdentifier.exact(item["approvalId"] as? String)
            else {
                return nil
            }
            let activeResolutionAttemptId: String?
            if let rawAttemptId = item["activeResolutionAttemptId"] {
                guard let attemptId = exactNonEmpty(rawAttemptId as? String) else {
                    return nil
                }
                activeResolutionAttemptId = attemptId
            } else {
                activeResolutionAttemptId = nil
            }
            heldApprovals.append(WatchExecApprovalSnapshotRequestItem(
                approvalId: approvalId,
                activeResolutionAttemptId: activeResolutionAttemptId))
        }
        let gatewayStableID = GatewayStableIdentifier.exact(payload["gatewayStableID"] as? String)
        let sentAtMs = (payload["sentAtMs"] as? NSNumber)?.int64Value
        return WatchExecApprovalSnapshotRequestEvent(
            requestId: requestId,
            gatewayStableID: gatewayStableID,
            heldApprovals: heldApprovals,
            sentAtMs: sentAtMs,
            transport: transport)
    }

    static func parseAppSnapshotRequestPayload(
        _ payload: [String: Any],
        transport: String) -> WatchAppSnapshotRequestEvent?
    {
        guard (payload["type"] as? String) == OpenClawWatchPayloadType.appSnapshotRequest.rawValue else {
            return nil
        }
        let requestId = self.nonEmpty(payload["requestId"] as? String) ?? UUID().uuidString
        let sentAtMs = (payload["sentAtMs"] as? NSNumber)?.int64Value
        return WatchAppSnapshotRequestEvent(
            requestId: requestId,
            sentAtMs: sentAtMs,
            transport: transport)
    }

    static func parseAppCommandPayload(
        _ payload: [String: Any],
        transport: String) -> WatchAppCommandEvent?
    {
        guard (payload["type"] as? String) == OpenClawWatchPayloadType.appCommand.rawValue else {
            return nil
        }
        guard let rawCommand = nonEmpty(payload["command"] as? String),
              let command = OpenClawWatchAppCommand(rawValue: rawCommand)
        else {
            return nil
        }
        let commandId = self.nonEmpty(payload["commandId"] as? String) ?? UUID().uuidString
        let sessionKey = self.nonEmpty(payload["sessionKey"] as? String)
        let gatewayStableID = GatewayStableIdentifier.exact(payload["gatewayStableID"] as? String)
        let text = self.nonEmpty(payload["text"] as? String)
        let sentAtMs = (payload["sentAtMs"] as? NSNumber)?.int64Value
        return WatchAppCommandEvent(
            commandId: commandId,
            command: command,
            sessionKey: sessionKey,
            gatewayStableID: gatewayStableID,
            text: text,
            sentAtMs: sentAtMs,
            transport: transport)
    }
}

import Foundation
import OpenClawKit

struct WatchMessagingStartupBuffer<Event> {
    private let maxCount: Int
    private var events: [Event] = []
    private(set) var isReady = false

    init(maxCount: Int) {
        precondition(maxCount > 0)
        self.maxCount = maxCount
    }

    mutating func receive(_ event: Event) -> [Event] {
        guard !self.isReady else { return [event] }
        if self.events.count == self.maxCount {
            self.events.removeFirst()
        }
        self.events.append(event)
        return []
    }

    mutating func markReady() -> [Event] {
        guard !self.isReady else { return [] }
        self.isReady = true
        defer { self.events.removeAll(keepingCapacity: false) }
        return self.events
    }
}

enum WatchMessagingError: LocalizedError {
    case unsupported
    case notPaired
    case watchAppNotInstalled

    var errorDescription: String? {
        switch self {
        case .unsupported:
            "WATCH_UNAVAILABLE: WatchConnectivity is not supported on this device"
        case .notPaired:
            "WATCH_UNAVAILABLE: no paired Apple Watch"
        case .watchAppNotInstalled:
            "WATCH_UNAVAILABLE: OpenClaw watch companion app is not installed"
        }
    }
}

@MainActor
final class WatchMessagingService: @preconcurrency WatchMessagingServicing {
    private static let maxStartupEvents = 64

    private let transport: WatchConnectivityTransport
    private var startupEvents = WatchMessagingStartupBuffer<WatchMessagingInboundEvent>(
        maxCount: WatchMessagingService.maxStartupEvents)
    private var statusHandler: (@Sendable (WatchMessagingStatus) -> Void)?
    private var lastEmittedStatus: WatchMessagingStatus?
    private var replyHandler: (@Sendable (WatchQuickReplyEvent) -> Void)?
    private var execApprovalResolveHandler: (@Sendable (WatchExecApprovalResolveEvent) -> Void)?
    private var execApprovalSnapshotRequestHandler: (
        @Sendable (WatchExecApprovalSnapshotRequestEvent) -> Void)?
    private var appSnapshotRequestHandler: (@Sendable (WatchAppSnapshotRequestEvent) -> Void)?
    private var appCommandHandler: (@Sendable (WatchAppCommandEvent) -> Void)?

    init(transport: WatchConnectivityTransport = WatchConnectivityTransport()) {
        self.transport = transport
        self.transport.setStatusUpdateHandler { [weak self] snapshot in
            Task { @MainActor [weak self] in
                self?.emitStatusIfChanged(snapshot)
            }
        }
        self.transport.setInboundEventHandler { [weak self] event in
            Task { @MainActor [weak self] in
                self?.receiveStartupEvent(event)
            }
        }
        self.transport.activate()
    }

    nonisolated static func isSupportedOnDevice() -> Bool {
        WatchConnectivityTransport.isSupportedOnDevice()
    }

    func status() async -> WatchMessagingStatus {
        await self.transport.status()
    }

    func setStatusHandler(_ handler: (@Sendable (WatchMessagingStatus) -> Void)?) {
        self.statusHandler = handler
        guard let handler else {
            self.lastEmittedStatus = nil
            GatewayDiagnostics.log("watch messaging: cleared status handler")
            return
        }
        let snapshot = self.transport.currentStatusSnapshot()
        self.lastEmittedStatus = snapshot
        GatewayDiagnostics.log(
            "watch messaging: set status handler "
                + "supported=\(snapshot.supported) paired=\(snapshot.paired) "
                + "appInstalled=\(snapshot.appInstalled) reachable=\(snapshot.reachable) "
                + "activation=\(snapshot.activationState)")
        handler(snapshot)
    }

    func setReplyHandler(_ handler: (@Sendable (WatchQuickReplyEvent) -> Void)?) {
        self.replyHandler = handler
        self.finishStartupRegistrationIfReady()
    }

    func setExecApprovalResolveHandler(_ handler: (@Sendable (WatchExecApprovalResolveEvent) -> Void)?) {
        self.execApprovalResolveHandler = handler
        self.finishStartupRegistrationIfReady()
    }

    func setExecApprovalSnapshotRequestHandler(
        _ handler: (@Sendable (WatchExecApprovalSnapshotRequestEvent) -> Void)?)
    {
        self.execApprovalSnapshotRequestHandler = handler
        self.finishStartupRegistrationIfReady()
    }

    func setAppSnapshotRequestHandler(_ handler: (@Sendable (WatchAppSnapshotRequestEvent) -> Void)?) {
        self.appSnapshotRequestHandler = handler
        self.finishStartupRegistrationIfReady()
    }

    func setAppCommandHandler(_ handler: (@Sendable (WatchAppCommandEvent) -> Void)?) {
        self.appCommandHandler = handler
        self.finishStartupRegistrationIfReady()
    }

    func sendNotification(
        id: String,
        params: OpenClawWatchNotifyParams,
        gatewayStableID: String?) async throws -> WatchNotificationSendResult
    {
        let payload = WatchMessagingPayloadCodec.encodeNotificationPayload(
            id: id,
            params: params,
            gatewayStableID: gatewayStableID)
        return try await self.transport.sendPayload(payload)
    }

    func sendDirectNodeSetup(setupCode: String) async throws -> WatchNotificationSendResult {
        try await self.transport.sendPayload(
            WatchMessagingPayloadCodec.encodeDirectNodeSetupPayload(setupCode: setupCode))
    }

    func sendExecApprovalPrompt(
        _ message: OpenClawWatchExecApprovalPromptMessage) async throws -> WatchNotificationSendResult
    {
        try await self.transport.sendPayload(
            WatchMessagingPayloadCodec.encodeExecApprovalPromptPayload(message))
    }

    func sendExecApprovalResolved(
        _ message: OpenClawWatchExecApprovalResolvedMessage) async throws -> WatchNotificationSendResult
    {
        try await self.transport.sendPayload(
            WatchMessagingPayloadCodec.encodeExecApprovalResolvedPayload(message))
    }

    func sendExecApprovalExpired(
        _ message: OpenClawWatchExecApprovalExpiredMessage) async throws -> WatchNotificationSendResult
    {
        try await self.transport.sendPayload(
            WatchMessagingPayloadCodec.encodeExecApprovalExpiredPayload(message))
    }

    func syncExecApprovalSnapshot(
        _ message: OpenClawWatchExecApprovalSnapshotMessage) async throws -> WatchNotificationSendResult
    {
        try await self.transport.sendSnapshotPayload(
            WatchMessagingPayloadCodec.encodeExecApprovalSnapshotPayload(message))
    }

    func syncAppSnapshot(
        _ message: OpenClawWatchAppSnapshotMessage) async throws -> WatchNotificationSendResult
    {
        try await self.transport.sendSnapshotPayload(
            WatchMessagingPayloadCodec.encodeAppSnapshotPayload(message))
    }

    func sendChatCompletion(
        _ message: OpenClawWatchChatCompletionMessage) async throws -> WatchNotificationSendResult
    {
        try await self.transport.sendPayload(
            WatchMessagingPayloadCodec.encodeChatCompletionPayload(message))
    }

    private func emitStatusIfChanged(_ snapshot: WatchMessagingStatus) {
        guard snapshot != self.lastEmittedStatus else {
            return
        }
        self.lastEmittedStatus = snapshot
        GatewayDiagnostics.log(
            "watch messaging: status "
                + "supported=\(snapshot.supported) paired=\(snapshot.paired) "
                + "appInstalled=\(snapshot.appInstalled) reachable=\(snapshot.reachable) "
                + "activation=\(snapshot.activationState)")
        self.statusHandler?(snapshot)
    }

    private func emitReply(_ event: WatchQuickReplyEvent) {
        self.replyHandler?(event)
    }

    private func emitExecApprovalResolve(_ event: WatchExecApprovalResolveEvent) {
        self.execApprovalResolveHandler?(event)
    }

    private func emitExecApprovalSnapshotRequest(_ event: WatchExecApprovalSnapshotRequestEvent) {
        GatewayDiagnostics.log(
            "watch messaging: snapshot request "
                + "id=\(event.requestId) transport=\(event.transport) "
                + "sentAtMs=\(event.sentAtMs ?? -1)")
        self.execApprovalSnapshotRequestHandler?(event)
    }

    private func emitAppSnapshotRequest(_ event: WatchAppSnapshotRequestEvent) {
        GatewayDiagnostics.log(
            "watch messaging: app snapshot request "
                + "id=\(event.requestId) transport=\(event.transport) "
                + "sentAtMs=\(event.sentAtMs ?? -1)")
        self.appSnapshotRequestHandler?(event)
    }

    private func emitAppCommand(_ event: WatchAppCommandEvent) {
        GatewayDiagnostics.log(
            "watch messaging: app command "
                + "id=\(event.commandId) command=\(event.command.rawValue) "
                + "transport=\(event.transport)")
        self.appCommandHandler?(event)
    }

    private func receiveStartupEvent(_ event: WatchMessagingInboundEvent) {
        for event in self.startupEvents.receive(event) {
            self.dispatchStartupEvent(event)
        }
    }

    private func finishStartupRegistrationIfReady() {
        guard self.replyHandler != nil,
              self.execApprovalResolveHandler != nil,
              self.execApprovalSnapshotRequestHandler != nil,
              self.appSnapshotRequestHandler != nil,
              self.appCommandHandler != nil
        else {
            return
        }
        for event in self.startupEvents.markReady() {
            self.dispatchStartupEvent(event)
        }
    }

    private func dispatchStartupEvent(_ event: WatchMessagingInboundEvent) {
        switch event {
        case let .reply(event):
            self.emitReply(event)
        case let .execApprovalResolve(event):
            self.emitExecApprovalResolve(event)
        case let .execApprovalSnapshotRequest(event):
            self.emitExecApprovalSnapshotRequest(event)
        case let .appSnapshotRequest(event):
            self.emitAppSnapshotRequest(event)
        case let .appCommand(event):
            self.emitAppCommand(event)
        }
    }
}

import Foundation
@preconcurrency import WatchConnectivity

enum WatchMessageAcknowledgmentError: LocalizedError {
    case rejected(String)

    var errorDescription: String? {
        switch self {
        case let .rejected(reason):
            "WATCH_DELIVERY_REJECTED: \(reason)"
        }
    }
}

func requireAcceptedWatchMessageReply(_ reply: [String: Any]) throws {
    guard let accepted = reply["ok"] as? Bool else {
        throw WatchMessageAcknowledgmentError.rejected("malformed acknowledgment")
    }
    guard accepted else {
        let reason = (reply["error"] as? String)?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        throw WatchMessageAcknowledgmentError.rejected(
            reason.flatMap { $0.isEmpty ? nil : $0 } ?? "payload was rejected")
    }
}

final class WatchMessageSendCompletion: @unchecked Sendable {
    private let lock = NSLock()
    private var continuation: CheckedContinuation<Void, any Error>?

    init(_ continuation: CheckedContinuation<Void, any Error>) {
        self.continuation = continuation
    }

    func complete(_ result: Result<Void, any Error>) {
        let continuation = self.lock.withLock { () -> CheckedContinuation<Void, any Error>? in
            defer { self.continuation = nil }
            return self.continuation
        }
        continuation?.resume(with: result)
    }
}

func sendReachableWatchMessage(_ payload: [String: Any], with session: WCSession) async throws {
    // WatchConnectivity callbacks use their own executor and can race despite their
    // documented exactly-once contract; only the first callback owns this continuation.
    try await withCheckedThrowingContinuation(isolation: nil) { (continuation: CheckedContinuation<Void, any Error>) in
        // An executor hop can retire the caller before this SDK enqueue begins.
        guard !Task.isCancelled else {
            continuation.resume(throwing: CancellationError())
            return
        }
        let completion = WatchMessageSendCompletion(continuation)
        session.sendMessage(
            payload,
            replyHandler: { reply in
                completion.complete(Result { try requireAcceptedWatchMessageReply(reply) })
            },
            errorHandler: { error in
                completion.complete(.failure(error))
            })
    }
}

enum WatchSessionActivationError: LocalizedError {
    case failed(String)
    case timedOut

    var errorDescription: String? {
        switch self {
        case let .failed(reason):
            "WATCH_UNAVAILABLE: Apple Watch session activation failed (\(reason))"
        case .timedOut:
            "WATCH_UNAVAILABLE: Apple Watch session activation timed out"
        }
    }
}

/// Joins concurrent sends to one WCSession activation and bounds the wait for its delegate callback.
/// A failed or timed-out generation remains retryable so a later foreground launch can recover.
final class WatchSessionActivationGate: @unchecked Sendable {
    private typealias Waiter = CheckedContinuation<Void, any Error>

    private enum State {
        case idle
        case activating(UInt64)
        case completed(Result<Void, WatchSessionActivationError>)
    }

    private let lock = NSLock()
    private let timeoutNanoseconds: UInt64
    private var generation: UInt64 = 0
    private var state = State.idle
    private var waiters: [Waiter] = []

    init(timeoutNanoseconds: UInt64 = 15_000_000_000) {
        self.timeoutNanoseconds = timeoutNanoseconds
    }

    @discardableResult
    func beginActivation() -> Bool {
        let generationToStart: UInt64? = self.lock.withLock {
            switch self.state {
            case .idle:
                break
            case .activating:
                return nil
            case let .completed(result):
                if case .success = result {
                    return nil
                }
            }

            self.generation &+= 1
            self.state = .activating(self.generation)
            return self.generation
        }

        guard let generationToStart else { return false }
        Task { [weak self] in
            do {
                try await Task.sleep(nanoseconds: self?.timeoutNanoseconds ?? 0)
            } catch {
                return
            }
            self?.finish(.failure(.timedOut), generation: generationToStart)
        }
        return true
    }

    func waitUntilActivated() async throws {
        try await withCheckedThrowingContinuation { (continuation: Waiter) in
            let completedResult: Result<Void, WatchSessionActivationError>? = self.lock.withLock {
                switch self.state {
                case .idle:
                    return .failure(.failed("activation was not started"))
                case .activating:
                    self.waiters.append(continuation)
                    return nil
                case let .completed(result):
                    return result
                }
            }
            if let completedResult {
                Self.resume(continuation, with: completedResult)
            }
        }
    }

    func complete(activated: Bool, errorDescription: String?) {
        let result: Result<Void, WatchSessionActivationError>
        if activated {
            result = .success(())
        } else {
            let reason = errorDescription?.trimmingCharacters(in: .whitespacesAndNewlines)
            let failureReason = reason.flatMap { $0.isEmpty ? nil : $0 } ?? "session stayed inactive"
            result = .failure(.failed(failureReason))
        }
        self.finish(result, generation: nil)
    }

    func reset() {
        let waiters: [Waiter] = self.lock.withLock {
            self.state = .idle
            let waiters = self.waiters
            self.waiters.removeAll()
            return waiters
        }
        let result = Result<Void, WatchSessionActivationError>.failure(
            .failed("active Apple Watch changed"))
        for waiter in waiters {
            Self.resume(waiter, with: result)
        }
    }

    private func finish(
        _ result: Result<Void, WatchSessionActivationError>,
        generation expectedGeneration: UInt64?)
    {
        let waiters: [Waiter]? = self.lock.withLock {
            if let expectedGeneration {
                guard case let .activating(activeGeneration) = self.state,
                      activeGeneration == expectedGeneration
                else {
                    return nil
                }
            }
            self.state = .completed(result)
            let waiters = self.waiters
            self.waiters.removeAll()
            return waiters
        }
        guard let waiters else { return }
        for waiter in waiters {
            Self.resume(waiter, with: result)
        }
    }

    private static func resume(
        _ continuation: Waiter,
        with result: Result<Void, WatchSessionActivationError>)
    {
        switch result {
        case .success:
            continuation.resume(returning: ())
        case let .failure(error):
            continuation.resume(throwing: error)
        }
    }
}

import Foundation

enum SessionKey {
    static func normalizeMainKey(_ raw: String?) -> String {
        let trimmed = (raw ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? "main" : trimmed
    }

    static func makeAgentSessionKey(agentId: String, baseKey: String) -> String {
        let trimmedAgent = agentId.trimmingCharacters(in: .whitespacesAndNewlines)
        let trimmedBase = baseKey.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmedAgent.isEmpty { return trimmedBase.isEmpty ? "main" : trimmedBase }
        let normalizedBase = trimmedBase.isEmpty ? "main" : trimmedBase
        return "agent:\(trimmedAgent):\(normalizedBase)"
    }

    static func agentId(from value: String?) -> String? {
        let parts = (value ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .split(separator: ":", omittingEmptySubsequences: false)
        guard parts.count >= 3, parts[0].lowercased() == "agent" else { return nil }
        let agentId = String(parts[1]).trimmingCharacters(in: .whitespacesAndNewlines)
        return agentId.isEmpty ? nil : agentId
    }
}

import OpenClawKit
import SwiftUI

/// Per-gateway custom header editor for gateways behind authenticating reverse proxies
/// (Cloudflare Access-style service tokens). Header values are credentials: they render
/// masked, persist in the Keychain, and must never appear in logs or diagnostics.
struct GatewayCustomHeadersSettingsView: View {
    let gatewayStableID: String

    @State private var entries: [HeaderEntry] = []
    @State private var newName = ""
    @State private var newValue = ""
    @State private var loaded = false

    private struct HeaderEntry: Identifiable, Equatable {
        let id = UUID()
        var name: String
        var value: String
    }

    var body: some View {
        Form {
            if !self.entries.isEmpty {
                Section {
                    ForEach(self.$entries) { $entry in
                        VStack(alignment: .leading, spacing: 4) {
                            Text(entry.name)
                                .font(OpenClawType.subheadSemiBold)
                            self.headerValueField("Value", text: $entry.value)
                        }
                    }
                    .onDelete(perform: self.removeEntries)
                } header: {
                    Text("Headers")
                        .font(OpenClawType.captionSemiBold)
                } footer: {
                    // Keep the extraction key contiguous for the native localization inventory.
                    // swiftlint:disable line_length
                    Text(
                        String(
                            localized:
                            "Sent with foreground app connections to this gateway. Changes apply on the next reconnect; Share extension delivery is not yet supported."))
                        .font(OpenClawType.caption)
                    // swiftlint:enable line_length
                }
            }

            Section {
                TextField(text: self.$newName, prompt: Text("Header name").font(OpenClawType.subhead)) {
                    Text("Header name")
                        .font(OpenClawType.subhead)
                }
                .font(OpenClawType.subhead)
                .textInputAutocapitalization(.never)
                .autocorrectionDisabled()
                self.headerValueField("Header value", text: self.$newValue)
                Button {
                    self.addEntry()
                } label: {
                    Label {
                        Text("Add Header")
                            .font(OpenClawType.subheadSemiBold)
                    } icon: {
                        Image(systemName: "plus")
                    }
                }
                .disabled(!self.canAddEntry)
            } header: {
                Text("Add Header")
                    .font(OpenClawType.captionSemiBold)
            } footer: {
                Text(self.addFooterText)
                    .font(OpenClawType.caption)
            }
        }
        .navigationTitle("Custom Headers")
        .toolbar {
            EditButton()
                .font(OpenClawType.subheadSemiBold)
        }
        .onAppear(perform: self.loadOnce)
        .onChange(of: self.entries) { _, _ in
            guard self.loaded else { return }
            self.persist()
        }
    }

    private var trimmedNewName: String {
        self.newName.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private var newNameIsReserved: Bool {
        GatewayCustomHeaders.isReservedName(self.trimmedNewName)
    }

    private var newNameIsDuplicate: Bool {
        let name = self.trimmedNewName
        return self.entries.contains { $0.name.caseInsensitiveCompare(name) == .orderedSame }
    }

    private var canAddEntry: Bool {
        !self.trimmedNewName.isEmpty && !self.newNameIsReserved && !self.newNameIsDuplicate
    }

    private var addFooterText: String {
        if self.newNameIsReserved {
            return "This header is managed by the connection and cannot be overridden."
        }
        if self.newNameIsDuplicate {
            return "A header with this name already exists."
        }
        return "For secure gateways behind an authenticating proxy, for example Cloudflare Access "
            + "service token headers. Values are stored securely and sent only over TLS to this gateway."
    }

    private func headerValueField(_ placeholder: String, text: Binding<String>) -> some View {
        ZStack(alignment: .leading) {
            SecureField("", text: text)
                .font(OpenClawType.subhead)
                .textInputAutocapitalization(.never)
                .autocorrectionDisabled()
                .accessibilityLabel(placeholder)
            if text.wrappedValue.isEmpty {
                Text(placeholder)
                    .font(OpenClawType.subhead)
                    .foregroundStyle(.tertiary)
                    .allowsHitTesting(false)
                    .accessibilityHidden(true)
            }
        }
    }

    private func loadOnce() {
        guard !self.loaded else { return }
        self.entries = GatewaySettingsStore.loadGatewayCustomHeaders(gatewayStableID: self.gatewayStableID)
            .sorted { $0.key.localizedCaseInsensitiveCompare($1.key) == .orderedAscending }
            .map { HeaderEntry(name: $0.key, value: $0.value) }
        self.loaded = true
    }

    private func addEntry() {
        guard self.canAddEntry else { return }
        self.entries.append(HeaderEntry(name: self.trimmedNewName, value: self.newValue))
        self.newName = ""
        self.newValue = ""
    }

    private func removeEntries(at offsets: IndexSet) {
        self.entries.remove(atOffsets: offsets)
    }

    private func persist() {
        var headers: [String: String] = [:]
        for entry in self.entries {
            let name = entry.name.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !name.isEmpty else { continue }
            headers[name] = entry.value
        }
        GatewaySettingsStore.saveGatewayCustomHeaders(headers, gatewayStableID: self.gatewayStableID)
    }
}

import Contacts
import EventKit
import Photos
import SwiftUI
import UIKit

struct PrivacyGatewayPermissionSnapshot: Equatable {
    let contacts: Bool
    let photos: Bool
    let calendar: Bool
    let reminders: Bool

    init(
        contactsStatus: CNAuthorizationStatus,
        photosStatus: PHAuthorizationStatus,
        calendarStatus: EKAuthorizationStatus,
        remindersStatus: EKAuthorizationStatus)
    {
        self.contacts = contactsStatus == .authorized || contactsStatus == .limited
        self.photos = PhotoLibraryAccess.canRead(photosStatus)
        self.calendar = Self.hasReadableEventKitAccess(calendarStatus)
        self.reminders = Self.hasReadableEventKitAccess(remindersStatus)
    }

    private static func hasReadableEventKitAccess(_ status: EKAuthorizationStatus) -> Bool {
        status == .fullAccess
    }
}

struct PrivacyAccessSectionView: View {
    @Environment(GatewayConnectionController.self) private var gatewayController
    @State private var contactsStatus: CNAuthorizationStatus = CNContactStore.authorizationStatus(for: .contacts)
    @State private var calendarStatus: EKAuthorizationStatus = EKEventStore.authorizationStatus(for: .event)
    @State private var remindersStatus: EKAuthorizationStatus = EKEventStore.authorizationStatus(for: .reminder)
    @State private var photosStatus = PhotoLibraryAccess.authorizationStatus()
    @State private var requestingIdentifiers: Set<String> = []
    @State private var eventKitPermissions = EventKitPermissionRequester()

    @Environment(\.scenePhase) private var scenePhase

    var body: some View {
        DisclosureGroup {
            self.contactsRow
            self.photosRow
            self.calendarAddRow
            self.calendarViewRow
            self.remindersRow
        } label: {
            Text("Privacy & Access")
                .font(OpenClawType.subheadSemiBold)
        }
        .font(OpenClawType.body)
        .onAppear { self.refreshAll() }
        .onChange(of: self.scenePhase) { _, phase in
            if phase == .active {
                self.refreshAll()
            }
        }
    }

    private var contactsRow: some View {
        let grant = DevicePermissionStatusMap.contacts(self.contactsStatus)
        return self.permissionRow(
            identifier: "contacts",
            kind: .contacts,
            detail: LocalizedStringResource("Search and add contacts from the assistant."),
            grant: grant,
            statusLabel: grant == .limited ? LocalizedStringResource("Limited") : nil,
            actionTitle: self.standardActionTitle(for: grant, limitedTitle: "Manage Access"),
            action: self.standardAction(identifier: "contacts", for: grant) {
                await self.requestContacts()
            })
    }

    private var photosRow: some View {
        let grant = DevicePermissionStatusMap.photos(self.photosStatus)
        return self.permissionRow(
            identifier: "photos",
            kind: .photos,
            detail: grant == .limited
                ? LocalizedStringResource("Read photos you select for the assistant.")
                : LocalizedStringResource("Read recent photos for the assistant."),
            grant: grant,
            statusLabel: grant == .limited ? LocalizedStringResource("Limited") : nil,
            actionTitle: self.standardActionTitle(for: grant, limitedTitle: "Manage Access"),
            action: self.standardAction(identifier: "photos", for: grant) {
                await self.updatePhotosStatus(PhotoLibraryAccess.requestReadWrite())
            })
    }

    private var calendarAddRow: some View {
        let grant = DevicePermissionStatusMap.eventKitWrite(self.calendarStatus)
        return self.permissionRow(
            identifier: "calendar-add",
            kind: .calendar,
            symbol: "calendar.badge.plus",
            title: LocalizedStringResource("Calendar (Add Events)"),
            detail: LocalizedStringResource("Add events with least privilege."),
            grant: grant,
            actionTitle: self.standardActionTitle(for: grant),
            action: self.standardAction(identifier: "calendar-add", for: grant) {
                _ = await self.requestCalendarWriteOnly()
                self.applyCalendarStatus()
            })
    }

    private var calendarViewRow: some View {
        let grant = DevicePermissionStatusMap.eventKitRead(self.calendarStatus)
        return self.permissionRow(
            identifier: "calendar-view",
            kind: .calendar,
            detail: LocalizedStringResource("List and read calendar events."),
            grant: grant,
            statusLabel: grant == .limited ? LocalizedStringResource("Add-Only") : nil,
            actionTitle: self.standardActionTitle(for: grant, limitedTitle: "Upgrade"),
            action: self.standardAction(identifier: "calendar-view", for: grant, limitedRequests: true) {
                _ = await self.requestCalendarFull()
                self.applyCalendarStatus()
            })
    }

    private var remindersRow: some View {
        let grant = DevicePermissionStatusMap.eventKitRead(self.remindersStatus)
        return self.permissionRow(
            identifier: "reminders",
            kind: .reminders,
            detail: LocalizedStringResource("List, add, and complete reminders."),
            grant: grant,
            statusLabel: grant == .limited ? LocalizedStringResource("Add-Only") : nil,
            actionTitle: self.standardActionTitle(for: grant, limitedTitle: "Upgrade"),
            action: self.standardAction(identifier: "reminders", for: grant, limitedRequests: true) {
                _ = await self.requestRemindersFull()
                self.remindersStatus = EKEventStore.authorizationStatus(for: .reminder)
                self.refreshAll()
            })
    }

    private func permissionRow(
        identifier: String,
        kind: DevicePermissionKind,
        symbol: String? = nil,
        title: LocalizedStringResource? = nil,
        detail: LocalizedStringResource,
        grant: DevicePermissionGrant,
        statusLabel: LocalizedStringResource? = nil,
        actionTitle: LocalizedStringResource?,
        action: (() -> Void)?) -> some View
    {
        DevicePermissionRow(
            identifierPrefix: "privacy-access",
            identifier: identifier,
            symbol: symbol ?? kind.symbol,
            tint: kind.tint,
            title: title ?? kind.title,
            detail: detail,
            grant: grant,
            isRequesting: self.requestingIdentifiers.contains(identifier),
            statusLabel: statusLabel,
            actionTitle: actionTitle,
            action: action)
    }

    private func standardActionTitle(
        for grant: DevicePermissionGrant,
        limitedTitle: LocalizedStringResource? = nil) -> LocalizedStringResource?
    {
        switch grant {
        case .notRequested:
            LocalizedStringResource("Continue")
        case .denied:
            LocalizedStringResource("Open Settings")
        case .limited:
            limitedTitle
        case .granted:
            nil
        }
    }

    /// `limitedRequests`: a limited grant re-requests (EventKit write-only → full)
    /// instead of routing to Settings like Photos/Contacts limited access does.
    private func standardAction(
        identifier: String,
        for grant: DevicePermissionGrant,
        limitedRequests: Bool = false,
        request: @escaping () async -> Void) -> (() -> Void)?
    {
        let run: () -> Void = {
            guard !self.requestingIdentifiers.contains(identifier) else { return }
            Task {
                self.requestingIdentifiers.insert(identifier)
                defer { self.requestingIdentifiers.remove(identifier) }
                await request()
            }
        }
        switch grant {
        case .notRequested:
            return run
        case .limited:
            return limitedRequests ? run : { self.openSettings() }
        case .denied:
            return { self.openSettings() }
        case .granted:
            return nil
        }
    }

    private func requestContacts() async {
        let granted = await PermissionRequestBridge.awaitRequest { completion in
            let store = CNContactStore()
            store.requestAccess(for: .contacts) { granted, _ in
                completion(granted)
            }
        }
        self.refreshAll()
        if granted {
            self.contactsStatus = CNContactStore.authorizationStatus(for: .contacts)
        }
    }

    private func applyCalendarStatus() {
        self.calendarStatus = EKEventStore.authorizationStatus(for: .event)
        self.refreshAll()
    }

    private func refreshAll() {
        let previousPermissions = PrivacyGatewayPermissionSnapshot(
            contactsStatus: self.contactsStatus,
            photosStatus: self.photosStatus,
            calendarStatus: self.calendarStatus,
            remindersStatus: self.remindersStatus)
        let contactsStatus = CNContactStore.authorizationStatus(for: .contacts)
        let photosStatus = PhotoLibraryAccess.authorizationStatus()
        let calendarStatus = EKEventStore.authorizationStatus(for: .event)
        let remindersStatus = EKEventStore.authorizationStatus(for: .reminder)
        let currentPermissions = PrivacyGatewayPermissionSnapshot(
            contactsStatus: contactsStatus,
            photosStatus: photosStatus,
            calendarStatus: calendarStatus,
            remindersStatus: remindersStatus)

        self.contactsStatus = contactsStatus
        self.photosStatus = photosStatus
        self.calendarStatus = calendarStatus
        self.remindersStatus = remindersStatus
        if previousPermissions != currentPermissions {
            self.gatewayController.refreshActiveGatewayRegistrationFromSettings()
        }
    }

    private func updatePhotosStatus(_ status: PHAuthorizationStatus) {
        let changed = self.photosStatus != status
        self.photosStatus = status
        if changed {
            self.gatewayController.refreshActiveGatewayRegistrationFromSettings()
        }
    }

    private func requestCalendarWriteOnly() async -> Bool {
        await self.eventKitPermissions.requestWriteOnlyAccessToEvents()
    }

    private func requestCalendarFull() async -> Bool {
        await self.eventKitPermissions.requestFullAccessToEvents()
    }

    private func requestRemindersFull() async -> Bool {
        await self.eventKitPermissions.requestFullAccessToReminders()
    }

    private func openSettings() {
        guard let url = URL(string: UIApplication.openSettingsURLString) else { return }
        UIApplication.shared.open(url)
    }
}

import Combine
import SwiftUI

struct VoiceWakeWordsSettingsView: View {
    @Environment(NodeAppModel.self) private var appModel
    @State private var triggerWords: [String] = VoiceWakePreferences.loadTriggerWords()
    @FocusState private var focusedTriggerIndex: Int?
    @State private var syncTask: Task<Void, Never>?

    var body: some View {
        Form {
            Section {
                ForEach(self.triggerWords.indices, id: \.self) { index in
                    TextField("Wake word", text: self.binding(for: index))
                        .textInputAutocapitalization(.never)
                        .autocorrectionDisabled()
                        .font(OpenClawType.subhead)
                        .focused(self.$focusedTriggerIndex, equals: index)
                        .onSubmit {
                            self.commitTriggerWords()
                        }
                }
                .onDelete(perform: self.removeWords)

                Button {
                    self.addWord()
                } label: {
                    Label("Add word", systemImage: "plus")
                        .font(OpenClawType.subheadSemiBold)
                }
                .disabled(self.triggerWords
                    .contains(where: { $0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }))

                Button {
                    self.triggerWords = VoiceWakePreferences.defaultTriggerWords
                } label: {
                    Text("Reset defaults")
                        .font(OpenClawType.subheadSemiBold)
                }
            } header: {
                Text("Wake Words")
                    .font(OpenClawType.captionSemiBold)
            } footer: {
                // Keep the extraction key contiguous for the native localization inventory.
                // swiftlint:disable line_length
                Text(
                    String(
                        localized:
                        "OpenClaw reacts when any trigger appears in a transcription. Keep them short to avoid false positives."))
                    .font(OpenClawType.caption)
                // swiftlint:enable line_length
            }
        }
        .navigationTitle("Wake Words")
        .toolbar {
            EditButton()
                .font(OpenClawType.subheadSemiBold)
        }
        .onAppear {
            if self.triggerWords.isEmpty {
                self.triggerWords = VoiceWakePreferences.defaultTriggerWords
                self.commitTriggerWords()
            }
        }
        .onChange(of: self.focusedTriggerIndex) { oldValue, newValue in
            guard oldValue != nil, oldValue != newValue else { return }
            self.commitTriggerWords()
        }
        .onReceive(NotificationCenter.default.publisher(for: UserDefaults.didChangeNotification)) { _ in
            guard self.focusedTriggerIndex == nil else { return }
            let updated = VoiceWakePreferences.loadTriggerWords()
            if updated != self.triggerWords {
                self.triggerWords = updated
            }
        }
    }

    private func addWord() {
        self.triggerWords.append("")
    }

    private func removeWords(at offsets: IndexSet) {
        self.triggerWords.remove(atOffsets: offsets)
        if self.triggerWords.isEmpty {
            self.triggerWords = VoiceWakePreferences.defaultTriggerWords
        }
        self.commitTriggerWords()
    }

    private func binding(for index: Int) -> Binding<String> {
        Binding(
            get: {
                guard self.triggerWords.indices.contains(index) else { return "" }
                return self.triggerWords[index]
            },
            set: { newValue in
                guard self.triggerWords.indices.contains(index) else { return }
                self.triggerWords[index] = newValue
            })
    }

    private func commitTriggerWords() {
        VoiceWakePreferences.saveTriggerWords(self.triggerWords)

        let snapshot = VoiceWakePreferences.sanitizeTriggerWords(self.triggerWords)
        self.syncTask?.cancel()
        self.syncTask = Task { [snapshot, weak appModel = self.appModel] in
            try? await Task.sleep(nanoseconds: 650_000_000)
            await appModel?.setGlobalWakeWords(snapshot)
        }
    }
}

import Foundation
import OpenClawKit

enum GatewayDisplayState: Equatable {
    case connected
    case connecting
    case error
    case disconnected
}

enum GatewayStatusBuilder {
    @MainActor
    static func build(appModel: NodeAppModel) -> GatewayDisplayState {
        self.build(
            gatewayServerName: appModel.gatewayServerName,
            lastGatewayProblem: appModel.lastGatewayProblem,
            gatewayStatusText: appModel.gatewayStatusText)
    }

    static func build(
        gatewayServerName: String?,
        lastGatewayProblem: GatewayConnectionProblem?,
        gatewayStatusText: String) -> GatewayDisplayState
    {
        if lastGatewayProblem != nil { return .error }
        if gatewayServerName != nil { return .connected }

        let text = gatewayStatusText.trimmingCharacters(in: .whitespacesAndNewlines)
        if text.localizedCaseInsensitiveContains("connecting") ||
            text.localizedCaseInsensitiveContains("reconnecting")
        {
            return .connecting
        }

        if text.localizedCaseInsensitiveContains("error") {
            return .error
        }

        return .disconnected
    }
}

import OpenClawKit
import SwiftUI

/// Control-hub Terminal destination: embeds the gateway-served terminal page
/// (`/focus/terminal`, the ghostty-web surface shared with the Control UI) in a
/// WKWebView, authenticated with the stored gateway credentials.
struct TerminalHubScreen: View {
    @Environment(NodeAppModel.self) private var appModel
    let headerSidebarAction: OpenClawSidebarHeaderAction?
    let usesNativeNavigationChrome: Bool
    let gatewayAction: (() -> Void)?

    init(
        headerSidebarAction: OpenClawSidebarHeaderAction? = nil,
        usesNativeNavigationChrome: Bool = false,
        gatewayAction: (() -> Void)? = nil)
    {
        self.headerSidebarAction = headerSidebarAction
        self.usesNativeNavigationChrome = usesNativeNavigationChrome
        self.gatewayAction = gatewayAction
    }

    var body: some View {
        let config = self.appModel.activeGatewayConnectConfig
        let storedOperatorToken = Self.storedOperatorToken(config: config)
        ZStack {
            OpenClawProBackground()
            if let url = Self.terminalURL(config: config) {
                AuthenticatedControlUIWebView(
                    url: url,
                    authScript: Self.terminalAuthUserScript(
                        config: config,
                        storedOperatorToken: storedOperatorToken),
                    tls: config?.tls)
                    // Recreate the web view only when the connection inputs
                    // change; SwiftUI update passes must not restart live shells.
                        .id(Self.webContentIdentity(
                            config: config,
                            storedOperatorToken: storedOperatorToken))
                        .ignoresSafeArea(.container, edges: .bottom)
            } else {
                self.unavailableCard
            }
        }
        .navigationTitle("Terminal")
        .navigationBarTitleDisplayMode(.inline)
        .toolbar(
            self.usesNativeNavigationChrome || self.headerSidebarAction != nil ? .visible : .hidden,
            for: .navigationBar)
        .toolbar {
            if self.usesNativeNavigationChrome, let gatewayAction {
                ToolbarItem(placement: .topBarTrailing) {
                    Button(action: gatewayAction) {
                        Image(systemName: "antenna.radiowaves.left.and.right")
                            .font(OpenClawType.subheadSemiBold)
                    }
                    .accessibilityLabel("Gateway settings")
                }
            }
            if let headerSidebarAction {
                OpenClawSidebarToolbarItem(
                    action: headerSidebarAction,
                    placement: .topBarLeading)
            }
        }
    }

    private var unavailableCard: some View {
        VStack(spacing: 12) {
            ProIconBadge(systemName: "terminal", color: OpenClawBrand.accent)
            Text("Terminal needs a connected gateway")
                .font(OpenClawType.subheadSemiBold)
            Text("Connect to your gateway to open a shell in the agent workspace.")
                .font(OpenClawType.caption)
                .foregroundStyle(.secondary)
                .multilineTextAlignment(.center)
            if let gatewayAction {
                Button(action: gatewayAction) {
                    Text("Open Gateway Settings")
                        .font(OpenClawType.subheadSemiBold)
                }
                .buttonStyle(.borderedProminent)
                .tint(OpenClawBrand.accent)
            }
        }
        .padding(24)
    }

    /// Derives the terminal page URL from the active gateway connection: the
    /// WS endpoint flips to HTTP(S) and the configured Control UI base path is preserved.
    /// Credentials never enter the URL — they are injected as a document-start
    /// user script (see `terminalAuthUserScript`), matching the macOS Dashboard.
    static func terminalURL(config: GatewayConnectConfig?) -> URL? {
        AuthenticatedControlUI.pageURL(
            config: config,
            path: "/focus/terminal",
            queryItems: [])
    }

    /// Origin-gated document-start script that hands the gateway credentials to
    /// the Control UI via its `__OPENCLAW_NATIVE_CONTROL_AUTH__` startup contract
    /// (the same mechanism the macOS Dashboard window uses), so the token never
    /// appears in the page URL, WebKit history, or gateway request logs.
    static func terminalAuthUserScript(config: GatewayConnectConfig?) -> String? {
        self.terminalAuthUserScript(
            config: config,
            storedOperatorToken: self.storedOperatorToken(config: config))
    }

    static func terminalAuthUserScript(
