        let range = try DateInterval(
            start: #require(formatter.date(from: "2026-07-12T00:00:00Z")),
            end: #require(formatter.date(from: "2026-07-12T12:00:00Z")))
        let intervals = try [
            DateInterval(
                start: #require(formatter.date(from: "2026-07-11T23:30:00Z")),
