        {
          "gatewayStatusText": "Ancien statut",
          "gatewayConnected": false,
          "agentName": "Main",
          "sessionKey": "main",
          "talkStatusText": "Ancien mode vocal",
          "talkEnabled": true,
          "talkListening": false,
          "talkSpeaking": false,
          "pendingApprovalCount": 0,
