@MainActor
@discardableResult
private func waitForMainActorWork(
    timeout: Duration = .seconds(2),
    _ condition: () -> Bool) async -> Bool
{
    let clock = ContinuousClock()
    let deadline = clock.now.advanced(by: timeout)
    while clock.now < deadline {
        if condition() {
            return true
        }
        await Task.yield()
    }
    return condition()
}

