private struct WatchExecApprovalListView: View {
    var store: WatchInboxStore
    var onDecision: ((String, String?, WatchExecApprovalDecision) -> Void)?

    var body: some View {
        WatchDetailScroll(title: "Approvals") {
            if self.store.sortedExecApprovals.isEmpty {
                WatchHeroCard(
                    label: .localized("Clear"),
                    title: .localized("No approvals waiting"),
                    subtitle: .verbatim(
                        self.store.lastExecApprovalOutcomeText
                            ?? String(localized: "You are caught up")),
                    accessory: .localized("Ready"))
            } else {
                ForEach(self.store.sortedExecApprovals) { record in
                    NavigationLink {
                        WatchExecApprovalDetailView(
                            store: self.store,
                            record: record,
                            onDecision: self.onDecision)
                    } label: {
                        WatchStackCard(
                            label: .localized("Approval"),
                            title: .verbatim(record.approval.commandPreview ?? record.approval.commandText),
                            subtitle: .verbatim(self.metadataLine(for: record)),
                            badge: nil)
                    }
                    .buttonStyle(.plain)
                }
            }

            if let outcome = self.store.lastExecApprovalOutcomeText, !outcome.isEmpty {
                WatchTinyStatus(text: outcome)
            }
        }
    }

    private func metadataLine(for record: WatchExecApprovalRecord) -> String {
        var parts: [String] = []
        if let host = record.approval.host, !host.isEmpty {
            parts.append(host)
        }
        if let nodeId = record.approval.nodeId, !nodeId.isEmpty {
            parts.append(nodeId)
        }
        if let expiresText = Self.expiresText(record.approval.expiresAtMs) {
            parts.append(expiresText)
        }
        if let statusText = record.status?.localizedText(), !statusText.isEmpty {
            parts.append(statusText)
        }
        return parts.isEmpty ? String(localized: "Pending review") : parts.joined(separator: " · ")
    }

    private static func expiresText(_ expiresAtMs: Int64?) -> String? {
        guard let expiresAtMs else { return nil }
        let deltaSeconds = max(0, (expiresAtMs - Int64(Date().timeIntervalSince1970 * 1000)) / 1000)
        if deltaSeconds < 60 {
            return String(localized: "Expires in less than 1 min")
        }
        return String(
            format: String(localized: "Expires in %@ min"),
            (deltaSeconds / 60).formatted())
    }
}

private struct WatchExecApprovalDetailView: View {
    var store: WatchInboxStore
    let record: WatchExecApprovalRecord
    var onDecision: ((String, String?, WatchExecApprovalDecision) -> Void)?

    var body: some View {
        WatchDetailScroll(title: "Review Command") {
            WatchHeroCard(
                label: .verbatim(
                    self.riskText(self.currentRecord?.approval.risk ?? self.record.approval.risk)
                        ?? String(localized: "Review")),
                title: .localized("Command execution"),
                subtitle: .verbatim(self.metadataSummary),
                accessory: .verbatim(
                    Self.expiresText(
                        self.currentRecord?.approval.expiresAtMs ?? self.record.approval.expiresAtMs)
                        ?? String(localized: "Now")))

            WatchApprovalCommandReview(commandText: self.commandText)

            if let warningText = WatchExecApprovalDisplay.warningText(
                self.currentRecord?.approval.warningText ?? self.record.approval.warningText)
            {
                WatchApprovalWarning(text: warningText)
            }

            if let currentRecord {
                if let statusText = WatchExecApprovalDisplay.statusText(for: currentRecord) {
                    WatchTinyStatus(text: statusText)
                }

                if !currentRecord.isResolving {
                    VStack(spacing: 8) {
                        if currentRecord.approval.allowedDecisions.contains(.allowOnce) {
                            WatchDecisionButton(title: "Allow Once", color: .green) {
                                self.onDecision?(
                                    currentRecord.approvalID,
                                    currentRecord.approval.gatewayStableID,
                                    .allowOnce)
                            }
                        }

                        if currentRecord.approval.allowedDecisions.contains(.deny) {
                            WatchDecisionButton(title: "Deny", color: WatchClawStyle.accent) {
                                self.onDecision?(
                                    currentRecord.approvalID,
                                    currentRecord.approval.gatewayStableID,
                                    .deny)
                            }
                        }
                    }
                }
            } else if let terminalOutcomeText = self.store.terminalExecApprovalOutcomeText(
                approvalId: self.record.approvalID,
                gatewayStableID: self.record.approval.gatewayStableID)
            {
                WatchTinyStatus(text: terminalOutcomeText)
            }
        }
        .onAppear {
            self.store.selectExecApproval(
                id: self.record.approvalID,
                gatewayStableID: self.record.approval.gatewayStableID)
        }
    }

    private var currentRecord: WatchExecApprovalRecord? {
        self.store.execApprovals.first(where: { $0.id == self.record.id })
    }

    private var commandText: String {
        self.currentRecord?.approval.commandText ?? self.record.approval.commandText
    }

    private var metadataSummary: String {
        let approval = self.currentRecord?.approval ?? self.record.approval
        var parts: [String] = []
        if let host = approval.host, !host.isEmpty {
            parts.append(host)
        }
        if let nodeId = approval.nodeId, !nodeId.isEmpty {
            parts.append(nodeId)
        }
        if let agentId = approval.agentId, !agentId.isEmpty {
            parts.append(agentId)
        }
        return parts.isEmpty
            ? String(localized: "Review command below")
            : parts.joined(separator: " · ")
    }

    private func riskText(_ risk: WatchRiskLevel?) -> String? {
        switch risk {
        case .high:
            String(localized: "High risk")
        case .medium:
            String(localized: "Medium risk")
        case .low:
            String(localized: "Low risk")
        case nil:
            nil
        }
    }

    private static func expiresText(_ expiresAtMs: Int64?) -> String? {
        guard let expiresAtMs else { return nil }
        let deltaSeconds = max(0, (expiresAtMs - Int64(Date().timeIntervalSince1970 * 1000)) / 1000)
        if deltaSeconds < 60 {
            return String(localized: "less than 1 minute")
        }
        let minutes = deltaSeconds / 60
        return String(
            AttributedString(localized: "^[\(minutes) minute](inflect: true)").characters)
    }
}

import SwiftUI

struct WatchMascot: View {
    @Environment(\.colorScheme) private var colorScheme
    @Environment(\.isLuminanceReduced) private var isLuminanceReduced

    let mood: OpenClawMascotMood
    let size: CGFloat

    var body: some View {
        Group {
            if self.isLuminanceReduced {
                // Always-On display must stay static so the animation loop never consumes background power.
                OpenClawMascotCanvas(
                    pose: .staticPose(for: self.mood),
                    palette: .forScheme(self.colorScheme))
            } else {
                // Fifteen frames per second keeps the tiny watch animation expressive without needless battery cost.
                OpenClawMascotView(
                    mood: self.mood,
                    minimumFrameInterval: 1.0 / 15.0)
            }
        }
        .frame(width: self.size, height: self.size)
        .accessibilityHidden(true)
    }
}

func watchInboxMascotMood(
    hasSnapshot: Bool,
    hasApprovals: Bool,
    hasChats: Bool) -> OpenClawMascotMood
{
    // Approval decisions demand attention above every other inbox state.
    if hasApprovals { return .attentive }
    // No snapshot means the watch is still waiting and thinking.
    if !hasSnapshot { return .thinking }
    // A synchronized inbox with nothing waiting can settle into sleep.
    if !hasChats { return .sleepy }
    // Existing chats keep the mascot present but neutral.
    return .idle
}

import Foundation
import WatchKit

enum WatchNativeTextInput {
    @MainActor
    static func present(
        suggestions: [String],
        onSubmit: @escaping (String) -> Void)
    {
        WKApplication.shared().visibleInterfaceController?.presentTextInputController(
            withSuggestions: suggestions,
            allowedInputMode: .allowEmoji)
        { results in
            guard let text = results?.compactMap(stringValue).first?
                .trimmingCharacters(in: .whitespacesAndNewlines),
                !text.isEmpty
            else {
                return
            }
            onSubmit(text)
        }
    }

    private static func stringValue(_ result: Any) -> String? {
        if let string = result as? String {
            return string
        }
        if let attributed = result as? NSAttributedString {
            return attributed.string
        }
        return nil
    }
}

import Foundation
import Observation
import OpenClawKit

@MainActor
@Observable
final class WatchSpeechPlayback {
    private var speechTask: Task<Void, Never>?
    private(set) var isSpeaking = false
    private(set) var errorText: String?

    func speak(_ text: String) {
        self.stop()
        guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        self.isSpeaking = true
        self.speechTask = Task { @MainActor in
            // A stopped task can still be scheduled, or finish after its replacement.
            // Only the current task may start speech or clear the playback controls.
            guard !Task.isCancelled else { return }
            do {
                try await TalkSystemSpeechSynthesizer.shared.speak(text: text)
            } catch TalkSystemSpeechSynthesizer.SpeakError.canceled {
            } catch {
                guard !Task.isCancelled else { return }
                self.errorText = String(localized: "Couldn't speak the reply. Read it in Chat.")
            }
            guard !Task.isCancelled else { return }
            self.isSpeaking = false
            self.speechTask = nil
        }
    }

    func stop() {
        self.speechTask?.cancel()
        self.speechTask = nil
        self.isSpeaking = false
        self.errorText = nil
    }
}

import Foundation

struct WatchVoiceTurnTracker: Codable, Equatable {
    private(set) var commandId: String?
    private(set) var isAwaitingReply = false

    mutating func begin(commandId: String) {
        self.commandId = commandId
        self.isAwaitingReply = true
    }

    mutating func takeReply(completedCommandId: String?, text: String?) -> String? {
        guard self.isAwaitingReply,
              let completedCommandId,
              completedCommandId == commandId,
              let text = text?.trimmingCharacters(in: .whitespacesAndNewlines),
              !text.isEmpty
        else {
            return nil
        }

        self.commandId = nil
        self.isAwaitingReply = false
        return text
    }

    mutating func cancel() {
        self.commandId = nil
        self.isAwaitingReply = false
    }
}

struct WatchVoiceTurnState: Codable, Equatable {
    static let timeoutMs: Int64 = 90000

    private(set) var tracker = WatchVoiceTurnTracker()
    private(set) var completion: WatchChatCompletionMessage?
    private(set) var startedAtMs: Int64?

    var isAwaitingReply: Bool {
        self.tracker.isAwaitingReply
    }

    mutating func begin(commandId: String, nowMs: Int64) {
        self.tracker.begin(commandId: commandId)
        self.completion = nil
        self.startedAtMs = nowMs
    }

    mutating func receive(_ message: WatchChatCompletionMessage, nowMs: Int64) {
        self.expireIfNeeded(nowMs: nowMs)
        guard self.tracker.isAwaitingReply,
              message.commandId == self.tracker.commandId
        else {
            return
        }
        if let current = completion {
            switch (current.sentAtMs, message.sentAtMs) {
            case let (currentSentAtMs?, incomingSentAtMs?) where incomingSentAtMs < currentSentAtMs:
                return
            case (_?, nil):
                return
            default:
                break
            }
        }
        self.completion = message
    }

    mutating func takeReply(nowMs: Int64) -> String? {
        self.expireIfNeeded(nowMs: nowMs)
        guard let completion,
              let reply = tracker.takeReply(
                  completedCommandId: completion.commandId,
                  text: completion.replyText)
        else {
            return nil
        }
        self.completion = nil
        self.startedAtMs = nil
        return reply
    }

    mutating func cancel() {
        self.tracker.cancel()
        self.completion = nil
        self.startedAtMs = nil
    }

    @discardableResult
    mutating func expireIfNeeded(nowMs: Int64) -> Bool {
        guard self.remainingTimeoutMs(nowMs: nowMs) == 0 else { return false }
        self.cancel()
        return true
    }

    func remainingTimeoutMs(nowMs: Int64) -> Int64? {
        guard self.tracker.isAwaitingReply, let startedAtMs else { return nil }
        let elapsedMs = max(0, nowMs - startedAtMs)
        return max(0, Self.timeoutMs - elapsedMs)
    }

    static func nowMs() -> Int64 {
        Int64(Date().timeIntervalSince1970 * 1000)
    }
}

#if os(watchOS)
extension WatchInboxStore {
    var chatCompletion: WatchChatCompletionMessage? {
        self.voiceTurnState.completion
    }

    var isAwaitingVoiceReply: Bool {
        self.voiceTurnState.isAwaitingReply
    }

    func consume(chatCompletion message: WatchChatCompletionMessage) {
        let nowMs = WatchVoiceTurnState.nowMs()
        self.expireVoiceTurnIfNeeded(nowMs: nowMs)
        let previousState = self.voiceTurnState
        self.voiceTurnState.receive(message, nowMs: nowMs)
        guard self.voiceTurnState != previousState else { return }
        self.persistVoiceTurnState()
    }

    func beginVoiceTurn(commandId: String) {
        self.voiceTurnState.begin(commandId: commandId, nowMs: WatchVoiceTurnState.nowMs())
        self.persistVoiceTurnState()
    }

    func takeVoiceReply() -> String? {
        let nowMs = WatchVoiceTurnState.nowMs()
        self.expireVoiceTurnIfNeeded(nowMs: nowMs)
        let previousState = self.voiceTurnState
        let reply = self.voiceTurnState.takeReply(nowMs: nowMs)
        if self.voiceTurnState != previousState {
            self.persistVoiceTurnState()
        }
        return reply
    }

    func cancelVoiceTurn() {
        guard self.voiceTurnState.isAwaitingReply || self.voiceTurnState.completion != nil else { return }
        self.voiceTurnState.cancel()
        self.persistVoiceTurnState()
    }

    func voiceReplyTimeoutNanoseconds() -> UInt64? {
        let nowMs = WatchVoiceTurnState.nowMs()
        self.expireVoiceTurnIfNeeded(nowMs: nowMs)
        guard let remainingMs = self.voiceTurnState.remainingTimeoutMs(nowMs: nowMs) else {
            return nil
        }
        return UInt64(remainingMs) * 1_000_000
    }

    func expireVoiceTurnIfNeeded(nowMs: Int64) {
        guard self.voiceTurnState.expireIfNeeded(nowMs: nowMs) else { return }
        // Only readback expires; the message may already be delivered or still running.
        self.markAppCommandBlocked(
            .sendChat,
            reason: String(localized: "Spoken reply timed out. Check Chat on iPhone."))
    }
}
#endif

import Foundation
import Testing
@testable import OpenClawWatchApp

@MainActor
struct WatchInboxStoreOperationTests {
    @Test func `reply completion cannot overwrite a replacement prompt`() throws {
        try Self.withStore { store, defaults in
            let originalAction = WatchPromptAction(id: "original-action", label: "Approve original")
            store.consume(
                message: Self.prompt(id: "original-prompt", action: originalAction),
                transport: "sendMessage")
            let originalAttempt = try #require(store.markReplySending(actionLabel: originalAction.label))

            let replacementAction = WatchPromptAction(id: "replacement-action", label: "Approve replacement")
            store.consume(
                message: Self.prompt(id: "replacement-prompt", action: replacementAction),
                transport: "sendMessage")
            let replacementAttempt = try #require(store.markReplySending(actionLabel: replacementAction.label))

            #expect(!store.markReplyResult(
                Self.result(.delivered),
                actionLabel: originalAction.label,
                attemptID: originalAttempt))
            #expect(store.promptId == "replacement-prompt")
            #expect(store.isReplySending)
            #expect(store.replyStatus?.code == .sending)
            #expect(store.replyStatus?.actionLabel == replacementAction.label)

            let restoredStore = WatchInboxStore(defaults: defaults, requestNotificationAuthorization: false)
            #expect(restoredStore.promptId == "replacement-prompt")
            #expect(restoredStore.replyStatus?.code == .failed)
            #expect(restoredStore.replyStatus?.actionLabel == replacementAction.label)
            #expect(!restoredStore.isReplySending)

            #expect(store.markReplyResult(
                Self.result(.delivered),
                actionLabel: replacementAction.label,
                attemptID: replacementAttempt))
            #expect(store.replyStatus?.code == .sent)
            #expect(!store.isReplySending)
        }
    }

    @Test func `current prompt rejects duplicate reply submissions`() throws {
        try Self.withStore { store, _ in
            let action = WatchPromptAction(id: "approve", label: "Approve")
            store.consume(message: Self.prompt(id: "current-prompt", action: action), transport: "sendMessage")
            let attempt = try #require(store.markReplySending(actionLabel: action.label))

            #expect(store.markReplySending(actionLabel: "Duplicate") == nil)
            #expect(store.isReplySending)
            #expect(store.replyStatus?.actionLabel == action.label)
            #expect(store.markReplyResult(Self.result(.delivered), actionLabel: action.label, attemptID: attempt))
            #expect(store.markReplySending(actionLabel: action.label) != nil)
        }
    }

    @Test func `restored interrupted operations become recoverable before actions reopen`() throws {
        try Self.withStore { store, defaults in
            let action = WatchPromptAction(id: "approve", label: "Approve")
            store.consume(message: Self.prompt(id: "current-prompt", action: action), transport: "sendMessage")
            store.consume(appSnapshot: Self.snapshot(id: "current-snapshot"))
            _ = try #require(store.markReplySending(actionLabel: action.label))
